{"line": 90, "text": ""}
{"line": 91, "text": "print()"}
{"line": 92, "text": "print(\"=\" * 72)"}
{"line": 93, "text": "print(\"TARGET FILE SCAN\")"}
{"line": 94, "text": "print(\"=\" * 72)"}
{"line": 95, "text": ""}
{"line": 96, "text": "patterns = ["}
{"line": 97, "text": "    r\"torch\","}
{"line": 98, "text": "    r\"tensorflow\","}
{"line": 99, "text": "    r\"transformers\","}
{"line": 100, "text": "    r\"numpy\","}
{"line": 101, "text": "    r\"embedding\","}
{"line": 102, "text": "    r\"token\","}
