{"line": 62, "text": ""}
{"line": 63, "text": "def sha256_bytes(data: bytes) -> str:"}
{"line": 64, "text": "    return hashlib.sha256(data).hexdigest()"}
{"line": 65, "text": ""}
{"line": 66, "text": ""}
{"line": 67, "text": "def sha256_file(path: Path) -> str:"}
{"line": 68, "text": "    h = hashlib.sha256()"}
{"line": 69, "text": ""}
{"line": 70, "text": "    with path.open(\"rb\") as f:"}
{"line": 71, "text": "        while True:"}
{"line": 72, "text": "            block = f.read(1024 * 1024)"}
{"line": 73, "text": ""}
{"line": 74, "text": "            if not block:"}
{"line": 75, "text": "                break"}
{"line": 76, "text": ""}
{"line": 77, "text": "            h.update(block)"}
{"line": 78, "text": ""}
{"line": 79, "text": "    return h.hexdigest()"}
{"line": 80, "text": ""}
{"line": 81, "text": ""}
{"line": 82, "text": "def write_json(path: Path, obj: Any) -> None:"}
