{"line": 87, "text": "    tmp.write_text("}
{"line": 88, "text": "        json.dumps("}
{"line": 89, "text": "            obj,"}
{"line": 90, "text": "            indent=2,"}
{"line": 91, "text": "            ensure_ascii=False,"}
{"line": 92, "text": "            default=str,"}
{"line": 93, "text": "        ),"}
{"line": 94, "text": "        encoding=\"utf-8\","}
{"line": 95, "text": "    )"}
