{"line": 1278, "text": "                        \"inspect validation encoding\","}
{"line": 1279, "text": "                        \"verify vocabulary consistency\","}
{"line": 1280, "text": "                        \"identify exact historical/source-backed producer\","}
{"line": 1281, "text": "                        \"only repair from verified evidence\","}
{"line": 1282, "text": "                        \"backup bloom_real.py before modification\","}
{"line": 1283, "text": "                        \"apply smallest evidence-backed repair\","}
{"line": 1284, "text": "                        \"re-run import probe\","}
{"line": 1285, "text": "                    ]"}
{"line": 1286, "text": ""}
{"line": 1287, "text": "                return decision"}
{"line": 1288, "text": ""}
{"line": 1289, "text": "            # ----------------------------------------------"}
{"line": 1290, "text": "            # GENERAL NAME ERROR"}
{"line": 1291, "text": "            # ----------------------------------------------"}
{"line": 1292, "text": ""}
{"line": 1293, "text": "            decision[\"decision\"] = ("}
{"line": 1294, "text": "                \"TRACE_MISSING_SYMBOL\""}
