{"line": 1302, "text": "                \"locate first consumer\","}
{"line": 1303, "text": "                \"verify execution ordering\","}
{"line": 1304, "text": "                \"verify dependency chain\","}
{"line": 1305, "text": "                \"reproduce in isolated subprocess\","}
{"line": 1306, "text": "                \"repair only after contract verification\","}
{"line": 1307, "text": "                \"re-run runtime probe\","}
{"line": 1308, "text": "            ]"}
{"line": 1309, "text": ""}
{"line": 1310, "text": "            return decision"}
{"line": 1311, "text": ""}
{"line": 1312, "text": "        # ----------------------------------------------------"}
{"line": 1313, "text": "        # OTHER ERRORS"}
{"line": 1314, "text": "        # ----------------------------------------------------"}
{"line": 1315, "text": ""}
{"line": 1316, "text": "        decision[\"decision\"] = ("}
{"line": 1317, "text": "            \"FORENSIC_RUNTIME_INVESTIGATION\""}
{"line": 1318, "text": "        )"}
{"line": 1319, "text": ""}
{"line": 1320, "text": "        decision[\"confidence\"] = 0.50"}
{"line": 1321, "text": ""}
{"line": 1322, "text": "        decision[\"next_actions\"] = ["}
{"line": 1323, "text": "            \"capture complete traceback\","}
{"line": 1324, "text": "            \"map failing line to source\","}
{"line": 1325, "text": "            \"inspect AST context\","}
{"line": 1326, "text": "            \"inspect dependency graph\","}
{"line": 1327, "text": "            \"reproduce in isolated subprocess\","}
{"line": 1328, "text": "            \"identify smallest causal boundary\","}
{"line": 1329, "text": "            \"form competing hypotheses\","}
{"line": 1330, "text": "            \"select evidence-supported repair\","}
{"line": 1331, "text": "            \"validate repair\","}
{"line": 1332, "text": "        ]"}
{"line": 1333, "text": ""}
{"line": 1334, "text": "        knowledge[\"unknown\"].append("}
{"line": 1335, "text": "            \"The current runtime failure is not yet mapped to a safe repair boundary.\""}
