{"line": 1338, "text": "        return decision"}
{"line": 1339, "text": ""}
{"line": 1340, "text": ""}
{"line": 1341, "text": "# ============================================================"}
{"line": 1342, "text": "# CONTRACT TRACER"}
{"line": 1343, "text": "# ============================================================"}
{"line": 1344, "text": ""}
{"line": 1345, "text": "class ContractTracer:"}
{"line": 1346, "text": ""}
{"line": 1347, "text": "    def __init__("}
{"line": 1348, "text": "        self,"}
{"line": 1349, "text": "        inspector: SourceIntrospector,"}
{"line": 1350, "text": "    ):"}
{"line": 1351, "text": "        self.inspector = inspector"}
{"line": 1352, "text": ""}
{"line": 1353, "text": "    def trace_symbol("}
{"line": 1354, "text": "        self,"}
{"line": 1355, "text": "        symbol: str,"}
{"line": 1356, "text": "    ):"}
{"line": 1357, "text": ""}
{"line": 1358, "text": "        evidence = {"}
{"line": 1359, "text": "            \"symbol\": symbol,"}
{"line": 1360, "text": "            \"definition\":"}
{"line": 1361, "text": "                self.inspector.definitions.get("}
{"line": 1362, "text": "                    symbol"}
{"line": 1363, "text": "                ),"}
{"line": 1364, "text": "            \"assignments\":"}
{"line": 1365, "text": "                self.inspector.assignments.get("}
{"line": 1366, "text": "                    symbol,"}
{"line": 1367, "text": "                    [],"}
{"line": 1368, "text": "                ),"}
{"line": 1369, "text": "            \"references\":"}
{"line": 1370, "text": "                self.inspector.references.get("}
{"line": 1371, "text": "                    symbol,"}
{"line": 1372, "text": "                    [],"}
{"line": 1373, "text": "                ),"}
{"line": 1374, "text": "            \"producer_exists\": bool("}
{"line": 1375, "text": "                self.inspector.assignments.get("}
{"line": 1376, "text": "                    symbol"}
{"line": 1377, "text": "                )"}
{"line": 1378, "text": "                or self.inspector.definitions.get("}
{"line": 1379, "text": "                    symbol"}
{"line": 1380, "text": "                )"}
{"line": 1381, "text": "            ),"}
{"line": 1382, "text": "        }"}
{"line": 1383, "text": ""}
{"line": 1384, "text": "        contexts = []"}
{"line": 1385, "text": ""}
{"line": 1386, "text": "        for line in evidence[\"references\"]:"}
{"line": 1387, "text": ""}
{"line": 1388, "text": "            contexts.append("}
{"line": 1389, "text": "                self.inspector.line_context("}
{"line": 1390, "text": "                    line,"}
{"line": 1391, "text": "                    radius=10,"}
{"line": 1392, "text": "                )"}
{"line": 1393, "text": "            )"}
{"line": 1394, "text": ""}
{"line": 1395, "text": "        evidence["}
{"line": 1396, "text": "            \"reference_contexts\""}
{"line": 1397, "text": "        ] = contexts"}
{"line": 1398, "text": ""}
{"line": 1399, "text": "        return evidence"}
{"line": 1400, "text": ""}
{"line": 1401, "text": "    def trace_tokenization(self):"}
{"line": 1402, "text": ""}
{"line": 1403, "text": "        result = {"}
{"line": 1404, "text": "            \"symbols\": {},"}
{"line": 1405, "text": "            \"corpus_producers\": [],"}
{"line": 1406, "text": "            \"tokenization_functions\": [],"}
{"line": 1407, "text": "            \"likely_contract\": [],"}
{"line": 1408, "text": "        }"}
{"line": 1409, "text": ""}
{"line": 1410, "text": "        for symbol in sorted("}
{"line": 1411, "text": "            TOKEN_SYMBOLS"}
{"line": 1412, "text": "        ):"}
{"line": 1413, "text": ""}
{"line": 1414, "text": "            result[\"symbols\"][symbol] = ("}
{"line": 1415, "text": "                self.trace_symbol(symbol)"}
{"line": 1416, "text": "            )"}
{"line": 1417, "text": ""}
{"line": 1418, "text": "        # ----------------------------------------------------"}
{"line": 1419, "text": "        # TOKENIZATION FUNCTIONS"}
{"line": 1420, "text": "        # ----------------------------------------------------"}
{"line": 1421, "text": ""}
{"line": 1422, "text": "        for name, info in ("}
{"line": 1423, "text": "            self.inspector.functions.items()"}
{"line": 1424, "text": "        ):"}
{"line": 1425, "text": ""}
{"line": 1426, "text": "            segment = ("}
{"line": 1427, "text": "                self.inspector.source_segment("}
{"line": 1428, "text": "                    name"}
{"line": 1429, "text": "                )"}
{"line": 1430, "text": "            )"}
{"line": 1431, "text": ""}
{"line": 1432, "text": "            if not segment:"}
{"line": 1433, "text": "                continue"}
{"line": 1434, "text": ""}
{"line": 1435, "text": "            lower = segment.lower()"}
{"line": 1436, "text": ""}
{"line": 1437, "text": "            token_words = ["}
{"line": 1438, "text": "                \"stoi\","}
{"line": 1439, "text": "                \"itos\","}
{"line": 1440, "text": "                \"vocab\","}
{"line": 1441, "text": "                \"encode\","}
{"line": 1442, "text": "                \"decode\","}
{"line": 1443, "text": "                \"token\","}
{"line": 1444, "text": "                \"tokens\","}
{"line": 1445, "text": "            ]"}
{"line": 1446, "text": ""}
{"line": 1447, "text": "            if any("}
{"line": 1448, "text": "                word in lower"}
{"line": 1449, "text": "                for word in token_words"}
{"line": 1450, "text": "            ):"}
{"line": 1451, "text": ""}
{"line": 1452, "text": "                result["}
{"line": 1453, "text": "                    \"tokenization_functions\""}
{"line": 1454, "text": "                ].append({"}
{"line": 1455, "text": "                    \"name\": name,"}
{"line": 1456, "text": "                    \"line\": info[\"line\"],"}
{"line": 1457, "text": "                    \"end_line\": info[\"end_line\"],"}
{"line": 1458, "text": "                })"}
{"line": 1459, "text": ""}
{"line": 1460, "text": "        # ----------------------------------------------------"}
{"line": 1461, "text": "        # REAL CORPUS"}
{"line": 1462, "text": "        # ----------------------------------------------------"}
{"line": 1463, "text": ""}
{"line": 1464, "text": "        for filename in ["}
{"line": 1465, "text": "            \"bloom_train_v2.txt\","}
{"line": 1466, "text": "            \"bloom_valid_v2.txt\","}
{"line": 1467, "text": "            \"my_texts.txt\","}
{"line": 1468, "text": "        ]:"}
{"line": 1469, "text": ""}
{"line": 1470, "text": "            path = ROOT / filename"}
{"line": 1471, "text": ""}
{"line": 1472, "text": "            if path.exists():"}
{"line": 1473, "text": ""}
{"line": 1474, "text": "                result["}
{"line": 1475, "text": "                    \"corpus_producers\""}
{"line": 1476, "text": "                ].append({"}
{"line": 1477, "text": "                    \"path\": str(path),"}
{"line": 1478, "text": "                    \"bytes\": path.stat().st_size,"}
{"line": 1479, "text": "                    \"sha256\": sha256_file(path),"}
{"line": 1480, "text": "                })"}
{"line": 1481, "text": ""}
{"line": 1482, "text": "        # ----------------------------------------------------"}
{"line": 1483, "text": "        # CONTRACT ASSESSMENT"}
{"line": 1484, "text": "        # ----------------------------------------------------"}
{"line": 1485, "text": ""}
{"line": 1486, "text": "        for symbol in ["}
{"line": 1487, "text": "            \"stoi\","}
{"line": 1488, "text": "            \"itos\","}
{"line": 1489, "text": "            \"vocab_size\","}
{"line": 1490, "text": "        ]:"}
{"line": 1491, "text": ""}
{"line": 1492, "text": "            info = result["}
{"line": 1493, "text": "                \"symbols\""}
{"line": 1494, "text": "            ][symbol]"}
{"line": 1495, "text": ""}
{"line": 1496, "text": "            if info[\"producer_exists\"]:"}
{"line": 1497, "text": ""}
{"line": 1498, "text": "                result[\"likely_contract\"].append("}
{"line": 1499, "text": "                    f\"{symbol} has an existing source producer.\""}
{"line": 1500, "text": "                )"}
{"line": 1501, "text": ""}
{"line": 1502, "text": "            else:"}
{"line": 1503, "text": ""}
{"line": 1504, "text": "                result[\"likely_contract\"].append("}
{"line": 1505, "text": "                    f\"{symbol} has no discovered source producer.\""}
{"line": 1506, "text": "                )"}
{"line": 1507, "text": ""}
{"line": 1508, "text": "        return result"}
{"line": 1509, "text": ""}
{"line": 1510, "text": "    def model_contract(self):"}
{"line": 1511, "text": ""}
{"line": 1512, "text": "        result = {"}
{"line": 1513, "text": "            \"GPT\": self.trace_symbol(\"GPT\"),"}
{"line": 1514, "text": "            \"model\": self.trace_symbol(\"model\"),"}
{"line": 1515, "text": "            \"params\": self.trace_symbol(\"params\"),"}
{"line": 1516, "text": "            \"calls\": [],"}
{"line": 1517, "text": "        }"}
{"line": 1518, "text": ""}
{"line": 1519, "text": "        for call in self.inspector.calls:"}
{"line": 1520, "text": ""}
{"line": 1521, "text": "            if ("}
{"line": 1522, "text": "                call[\"name\"] == \"GPT\""}
{"line": 1523, "text": "                or call[\"name\"].endswith(\".GPT\")"}
{"line": 1524, "text": "            ):"}
{"line": 1525, "text": ""}
{"line": 1526, "text": "                result[\"calls\"].append(call)"}
{"line": 1527, "text": ""}
{"line": 1528, "text": "        return result"}
{"line": 1529, "text": ""}
{"line": 1530, "text": "    def batching_contract(self):"}
{"line": 1531, "text": ""}
{"line": 1532, "text": "        return {"}
{"line": 1533, "text": "            \"get_batch\":"}
{"line": 1534, "text": "                self.trace_symbol(\"get_batch\"),"}
{"line": 1535, "text": "            \"data\":"}
{"line": 1536, "text": "                self.trace_symbol(\"data\"),"}
{"line": 1537, "text": "            \"validation_data\":"}
{"line": 1538, "text": "                self.trace_symbol("}
{"line": 1539, "text": "                    \"validation_data\""}
{"line": 1540, "text": "                ),"}
{"line": 1541, "text": "        }"}
{"line": 1542, "text": ""}
{"line": 1543, "text": "    def inference_contract(self):"}
{"line": 1544, "text": ""}
{"line": 1545, "text": "        return {"}
{"line": 1546, "text": "            \"generate\":"}
{"line": 1547, "text": "                self.trace_symbol(\"generate\"),"}
{"line": 1548, "text": "            \"retrieve\":"}
{"line": 1549, "text": "                self.trace_symbol(\"retrieve\"),"}
{"line": 1550, "text": "        }"}
{"line": 1551, "text": ""}
{"line": 1552, "text": "    def full_trace(self):"}
{"line": 1553, "text": ""}
{"line": 1554, "text": "        return {"}
{"line": 1555, "text": "            \"tokenization\":"}
{"line": 1556, "text": "                self.trace_tokenization(),"}
{"line": 1557, "text": "            \"model\":"}
{"line": 1558, "text": "                self.model_contract(),"}
{"line": 1559, "text": "            \"batching\":"}
{"line": 1560, "text": "                self.batching_contract(),"}
{"line": 1561, "text": "            \"inference\":"}
{"line": 1562, "text": "                self.inference_contract(),"}
{"line": 1563, "text": "            \"definitions\":"}
{"line": 1564, "text": "                self.inspector.definitions,"}
{"line": 1565, "text": "            \"references\":"}
{"line": 1566, "text": "                self.inspector.references,"}
{"line": 1567, "text": "            \"assignments\":"}
{"line": 1568, "text": "                self.inspector.assignments,"}
{"line": 1569, "text": "            \"functions\":"}
{"line": 1570, "text": "                self.inspector.functions,"}
{"line": 1571, "text": "            \"classes\":"}
{"line": 1572, "text": "                self.inspector.classes,"}
{"line": 1573, "text": "        }"}
{"line": 1574, "text": ""}
{"line": 1575, "text": ""}
{"line": 1576, "text": "# ============================================================"}
{"line": 1577, "text": "# REPAIR SAFETY"}
{"line": 1578, "text": "# ============================================================"}
{"line": 1579, "text": ""}
{"line": 1580, "text": "class RepairSafety:"}
{"line": 1581, "text": ""}
{"line": 1582, "text": "    def __init__(self):"}
{"line": 1583, "text": ""}
{"line": 1584, "text": "        BACKUP_DIR.mkdir("}
{"line": 1585, "text": "            parents=True,"}
{"line": 1586, "text": "            exist_ok=True,"}
{"line": 1587, "text": "        )"}
{"line": 1588, "text": ""}
{"line": 1589, "text": "    def backup("}
{"line": 1590, "text": "        self,"}
{"line": 1591, "text": "        path: Path,"}
{"line": 1592, "text": "    ):"}
{"line": 1593, "text": ""}
{"line": 1594, "text": "        timestamp = time.strftime("}
{"line": 1595, "text": "            \"%Y%m%d_%H%M%S\""}
{"line": 1596, "text": "        )"}
{"line": 1597, "text": ""}
{"line": 1598, "text": "        destination = ("}
{"line": 1599, "text": "            BACKUP_DIR"}
{"line": 1600, "text": "            / f\"{path.name}.{timestamp}.bak\""}
{"line": 1601, "text": "        )"}
{"line": 1602, "text": ""}
{"line": 1603, "text": "        shutil.copy2("}
{"line": 1604, "text": "            path,"}
{"line": 1605, "text": "            destination,"}
{"line": 1606, "text": "        )"}
{"line": 1607, "text": ""}
{"line": 1608, "text": "        return destination"}
{"line": 1609, "text": ""}
{"line": 1610, "text": ""}
{"line": 1611, "text": "# ============================================================"}
{"line": 1612, "text": "# VALIDATION"}
{"line": 1613, "text": "# ============================================================"}
{"line": 1614, "text": ""}
{"line": 1615, "text": "class ValidationEngine:"}
{"line": 1616, "text": ""}
{"line": 1617, "text": "    def __init__("}
{"line": 1618, "text": "        self,"}
{"line": 1619, "text": "        terminal: AutonomousTerminal,"}
{"line": 1620, "text": "    ):"}
{"line": 1621, "text": "        self.terminal = terminal"}
{"line": 1622, "text": ""}
{"line": 1623, "text": "    def compile(self):"}
{"line": 1624, "text": ""}
{"line": 1625, "text": "        return self.terminal.run("}
{"line": 1626, "text": "            \"python3 -m py_compile bloom_real.py\","}
{"line": 1627, "text": "            timeout=120,"}
{"line": 1628, "text": "        )"}
{"line": 1629, "text": ""}
{"line": 1630, "text": "    def import_probe(self):"}
{"line": 1631, "text": ""}
{"line": 1632, "text": "        return RuntimeProbe("}
{"line": 1633, "text": "            self.terminal"}
{"line": 1634, "text": "        ).import_model()"}
{"line": 1635, "text": ""}
{"line": 1636, "text": "    def corpus_probe(self):"}
{"line": 1637, "text": ""}
{"line": 1638, "text": "        return RuntimeProbe("}
{"line": 1639, "text": "            self.terminal"}
{"line": 1640, "text": "        ).corpus_probe()"}
{"line": 1641, "text": ""}
{"line": 1642, "text": ""}
{"line": 1643, "text": "# ============================================================"}
{"line": 1644, "text": "# BLOOM OPERATOR"}
{"line": 1645, "text": "# ============================================================"}
{"line": 1646, "text": ""}
{"line": 1647, "text": "class BloomAutonomousOperator:"}
{"line": 1648, "text": ""}
{"line": 1649, "text": "    def __init__(self):"}
{"line": 1650, "text": ""}
{"line": 1651, "text": "        self.terminal = ("}
{"line": 1652, "text": "            AutonomousTerminal()"}
{"line": 1653, "text": "        )"}
{"line": 1654, "text": ""}
{"line": 1655, "text": "        self.inspector = ("}
{"line": 1656, "text": "            SourceIntrospector()"}
{"line": 1657, "text": "        )"}
{"line": 1658, "text": ""}
{"line": 1659, "text": "        self.tracer = None"}
{"line": 1660, "text": ""}
{"line": 1661, "text": "        self.discerner = ("}
{"line": 1662, "text": "            ErrorDiscerner()"}
{"line": 1663, "text": "        )"}
{"line": 1664, "text": ""}
{"line": 1665, "text": "        self.safety = ("}
{"line": 1666, "text": "            RepairSafety()"}
{"line": 1667, "text": "        )"}
{"line": 1668, "text": ""}
{"line": 1669, "text": "        self.validation = ("}
{"line": 1670, "text": "            ValidationEngine("}
{"line": 1671, "text": "                self.terminal"}
{"line": 1672, "text": "            )"}
{"line": 1673, "text": "        )"}
{"line": 1674, "text": ""}
{"line": 1675, "text": "        self.state = {"}
{"line": 1676, "text": "            \"system\": \"BLOOM\","}
{"line": 1677, "text": "            \"operator\":"}
{"line": 1678, "text": "                \"evidence-first\","}
{"line": 1679, "text": "            \"mode\":"}
{"line": 1680, "text": "                \"OBSERVE -> TRACE -> DISCERN -> VERIFY\","}
{"line": 1681, "text": "            \"started\": now(),"}
{"line": 1682, "text": "            \"cycles\": [],"}
{"line": 1683, "text": "        }"}
{"line": 1684, "text": ""}
{"line": 1685, "text": "    # --------------------------------------------------------"}
{"line": 1686, "text": "    # INSPECTION"}
{"line": 1687, "text": "    # --------------------------------------------------------"}
{"line": 1688, "text": ""}
{"line": 1689, "text": "    def inspect(self):"}
{"line": 1690, "text": ""}
{"line": 1691, "text": "        self.inspector.load()"}
{"line": 1692, "text": ""}
{"line": 1693, "text": "        self.tracer = ContractTracer("}
{"line": 1694, "text": "            self.inspector"}
{"line": 1695, "text": "        )"}
{"line": 1696, "text": ""}
{"line": 1697, "text": "        return self.inspector.summary()"}
{"line": 1698, "text": ""}
{"line": 1699, "text": "    # --------------------------------------------------------"}
{"line": 1700, "text": "    # PROBE"}
{"line": 1701, "text": "    # --------------------------------------------------------"}
{"line": 1702, "text": ""}
{"line": 1703, "text": "    def probe(self):"}
{"line": 1704, "text": ""}
{"line": 1705, "text": "        result = self.validation.import_probe()"}
