{"line": 15, "text": ""}
{"line": 16, "text": "GARDEN=Path(\"garden_best_llm\"); GARDEN.mkdir(exist_ok=True)"}
{"line": 17, "text": ""}
{"line": 18, "text": "# 1. DATA - real text, not synthetic"}
{"line": 19, "text": "def get_data():"}
{"line": 20, "text": "    txt=\"\""}
{"line": 21, "text": "    urls=[\"https://raw.githubusercontent.com/karpathy/char-rnn/master/data/tinyshakespeare/input.txt\"]"}
