{"line": 35, "text": "    \"\"\"0=plenty, 1=scarcity, 2=temptation, 3=crisis\"\"\""}
{"line": 36, "text": "    regime = (step // 25) % 4"}
{"line": 37, "text": "    if regime == 0: # plenty - low need, low risk - easy to be noble"}
{"line": 38, "text": "        return {\"power\": random.uniform(6,10), \"need\": random.uniform(0,4), \"oath\": random.uniform(2,6), \"risk\": random.uniform(0,3)}, regime"}
{"line": 39, "text": "    elif regime == 1: # scarcity - high need, low power - true test"}
