{"line": 30, "text": ""}
{"line": 31, "text": "@dataclass"}
{"line": 32, "text": "class CommandResult:"}
{"line": 33, "text": "    command: str"}
{"line": 34, "text": "    cwd: str"}
{"line": 35, "text": "    returncode: int"}
{"line": 36, "text": "    stdout: str"}
{"line": 37, "text": "    stderr: str"}
{"line": 38, "text": "    duration: float"}
{"line": 39, "text": "    timed_out: bool"}
{"line": 40, "text": ""}
{"line": 41, "text": "    @property"}
{"line": 42, "text": "    def success(self):"}
{"line": 43, "text": "        return ("}
{"line": 44, "text": "            self.returncode == 0"}
{"line": 45, "text": "            and not self.timed_out"}
{"line": 46, "text": "        )"}
{"line": 47, "text": ""}
{"line": 48, "text": "    def as_dict(self):"}
{"line": 49, "text": "        return asdict(self)"}
{"line": 50, "text": ""}
{"line": 51, "text": ""}
{"line": 52, "text": "# ============================================================"}
{"line": 53, "text": "# AUTONOMOUS TERMINAL"}
{"line": 54, "text": "# ============================================================"}
{"line": 55, "text": ""}
{"line": 56, "text": "class BloomTerminal:"}
{"line": 57, "text": ""}
{"line": 58, "text": "    def __init__(self, root=ROOT):"}
{"line": 59, "text": "        self.root = Path(root).resolve()"}
{"line": 60, "text": "        self.root.mkdir("}
{"line": 61, "text": "            parents=True,"}
{"line": 62, "text": "            exist_ok=True,"}
{"line": 63, "text": "        )"}
{"line": 64, "text": ""}
{"line": 65, "text": "    def snapshot(self):"}
{"line": 66, "text": "        result = {}"}
{"line": 67, "text": ""}
{"line": 68, "text": "        for path in self.root.rglob(\"*\"):"}
{"line": 69, "text": ""}
{"line": 70, "text": "            if not path.is_file():"}
{"line": 71, "text": "                continue"}
{"line": 72, "text": ""}
{"line": 73, "text": "            # Do not allow the terminal's own logs to become"}
{"line": 74, "text": "            # an uncontrolled recursive observation surface."}
{"line": 75, "text": "            try:"}
{"line": 76, "text": "                rel = path.relative_to(self.root)"}
{"line": 77, "text": "            except Exception:"}
{"line": 78, "text": "                continue"}
{"line": 79, "text": ""}
{"line": 80, "text": "            try:"}
{"line": 81, "text": "                raw = path.read_bytes()"}
{"line": 82, "text": "            except Exception:"}
{"line": 83, "text": "                continue"}
{"line": 84, "text": ""}
{"line": 85, "text": "            result[str(rel)] = {"}
{"line": 86, "text": "                \"bytes\": len(raw),"}
{"line": 87, "text": "                \"sha256\": hashlib.sha256(raw).hexdigest(),"}
{"line": 88, "text": "            }"}
{"line": 89, "text": ""}
{"line": 90, "text": "        return result"}
{"line": 91, "text": ""}
{"line": 92, "text": "    def run("}
{"line": 93, "text": "        self,"}
{"line": 94, "text": "        command,"}
{"line": 95, "text": "        timeout=120,"}
{"line": 96, "text": "        cwd=None,"}
{"line": 97, "text": "    ):"}
{"line": 98, "text": ""}
{"line": 99, "text": "        cwd = ("}
{"line": 100, "text": "            self.root"}
{"line": 101, "text": "            if cwd is None"}
{"line": 102, "text": "            else Path(cwd).resolve()"}
{"line": 103, "text": "        )"}
{"line": 104, "text": ""}
{"line": 105, "text": "        if self.root not in cwd.parents and cwd != self.root:"}
{"line": 106, "text": "            raise ValueError("}
{"line": 107, "text": "                \"Terminal cwd escaped BLOOM root.\""}
{"line": 108, "text": "            )"}
{"line": 109, "text": ""}
{"line": 110, "text": "        before = self.snapshot()"}
{"line": 111, "text": ""}
{"line": 112, "text": "        started = time.time()"}
{"line": 113, "text": ""}
{"line": 114, "text": "        try:"}
{"line": 115, "text": ""}
{"line": 116, "text": "            proc = subprocess.run("}
{"line": 117, "text": "                command,"}
{"line": 118, "text": "                shell=True,"}
{"line": 119, "text": "                cwd=str(cwd),"}
{"line": 120, "text": "                text=True,"}
{"line": 121, "text": "                capture_output=True,"}
{"line": 122, "text": "                timeout=timeout,"}
{"line": 123, "text": "            )"}
{"line": 124, "text": ""}
{"line": 125, "text": "            result = CommandResult("}
{"line": 126, "text": "                command=command,"}
{"line": 127, "text": "                cwd=str(cwd),"}
{"line": 128, "text": "                returncode=proc.returncode,"}
{"line": 129, "text": "                stdout=proc.stdout or \"\","}
{"line": 130, "text": "                stderr=proc.stderr or \"\","}
{"line": 131, "text": "                duration=time.time() - started,"}
{"line": 132, "text": "                timed_out=False,"}
{"line": 133, "text": "            )"}
{"line": 134, "text": ""}
{"line": 135, "text": "        except subprocess.TimeoutExpired as e:"}
{"line": 136, "text": ""}
{"line": 137, "text": "            stdout = e.stdout or \"\""}
{"line": 138, "text": "            stderr = e.stderr or \"\""}
{"line": 139, "text": ""}
{"line": 140, "text": "            if isinstance(stdout, bytes):"}
{"line": 141, "text": "                stdout = stdout.decode("}
{"line": 142, "text": "                    \"utf-8\","}
{"line": 143, "text": "                    \"replace\","}
{"line": 144, "text": "                )"}
{"line": 145, "text": ""}
{"line": 146, "text": "            if isinstance(stderr, bytes):"}
{"line": 147, "text": "                stderr = stderr.decode("}
{"line": 148, "text": "                    \"utf-8\","}
{"line": 149, "text": "                    \"replace\","}
{"line": 150, "text": "                )"}
{"line": 151, "text": ""}
{"line": 152, "text": "            result = CommandResult("}
{"line": 153, "text": "                command=command,"}
{"line": 154, "text": "                cwd=str(cwd),"}
{"line": 155, "text": "                returncode=-1,"}
{"line": 156, "text": "                stdout=stdout,"}
{"line": 157, "text": "                stderr=stderr,"}
{"line": 158, "text": "                duration=time.time() - started,"}
{"line": 159, "text": "                timed_out=True,"}
{"line": 160, "text": "            )"}
{"line": 161, "text": ""}
{"line": 162, "text": "        after = self.snapshot()"}
{"line": 163, "text": ""}
{"line": 164, "text": "        changed = {}"}
{"line": 165, "text": ""}
{"line": 166, "text": "        for path in sorted("}
{"line": 167, "text": "            set(before) | set(after)"}
{"line": 168, "text": "        ):"}
{"line": 169, "text": ""}
{"line": 170, "text": "            if before.get(path) != after.get(path):"}
{"line": 171, "text": ""}
{"line": 172, "text": "                changed[path] = {"}
{"line": 173, "text": "                    \"before\": before.get(path),"}
{"line": 174, "text": "                    \"after\": after.get(path),"}
{"line": 175, "text": "                }"}
{"line": 176, "text": ""}
{"line": 177, "text": "        record = {"}
{"line": 178, "text": "            \"timestamp\": time.time(),"}
{"line": 179, "text": "            \"type\": \"terminal_execution\","}
{"line": 180, "text": "            \"command\": command,"}
{"line": 181, "text": "            \"cwd\": str(cwd),"}
{"line": 182, "text": "            \"result\": result.as_dict(),"}
{"line": 183, "text": "            \"changed_files\": changed,"}
{"line": 184, "text": "        }"}
{"line": 185, "text": ""}
{"line": 186, "text": "        self.record(record)"}
{"line": 187, "text": ""}
{"line": 188, "text": "        return result"}
{"line": 189, "text": ""}
{"line": 190, "text": "    def record(self, record):"}
{"line": 191, "text": ""}
{"line": 192, "text": "        with LEDGER_FILE.open("}
{"line": 193, "text": "            \"a\","}
{"line": 194, "text": "            encoding=\"utf-8\","}
{"line": 195, "text": "        ) as f:"}
{"line": 196, "text": ""}
{"line": 197, "text": "            f.write("}
{"line": 198, "text": "                json.dumps("}
{"line": 199, "text": "                    record,"}
{"line": 200, "text": "                    ensure_ascii=False,"}
{"line": 201, "text": "                )"}
{"line": 202, "text": "                + \"\\n\""}
{"line": 203, "text": "            )"}
{"line": 204, "text": ""}
{"line": 205, "text": ""}
{"line": 206, "text": "# ============================================================"}
{"line": 207, "text": "# SOURCE INTROSPECTION"}
{"line": 208, "text": "# ============================================================"}
{"line": 209, "text": ""}
{"line": 210, "text": "class SourceIntrospector:"}
{"line": 211, "text": ""}
{"line": 212, "text": "    def __init__(self, model=MODEL):"}
{"line": 213, "text": ""}
{"line": 214, "text": "        self.model = Path(model)"}
{"line": 215, "text": ""}
{"line": 216, "text": "        self.source = \"\""}
{"line": 217, "text": "        self.tree = None"}
{"line": 218, "text": ""}
{"line": 219, "text": "        self.definitions = {}"}
{"line": 220, "text": "        self.references = {}"}
{"line": 221, "text": "        self.functions = {}"}
{"line": 222, "text": "        self.classes = {}"}
{"line": 223, "text": "        self.imports = set()"}
{"line": 224, "text": ""}
{"line": 225, "text": "    def load(self):"}
{"line": 226, "text": ""}
{"line": 227, "text": "        if not self.model.exists():"}
{"line": 228, "text": ""}
{"line": 229, "text": "            raise FileNotFoundError("}
{"line": 230, "text": "                f\"Missing model: {self.model}\""}
{"line": 231, "text": "            )"}
{"line": 232, "text": ""}
{"line": 233, "text": "        self.source = self.model.read_text("}
{"line": 234, "text": "            encoding=\"utf-8\","}
{"line": 235, "text": "            errors=\"replace\","}
{"line": 236, "text": "        )"}
{"line": 237, "text": ""}
{"line": 238, "text": "        self.tree = ast.parse("}
{"line": 239, "text": "            self.source"}
{"line": 240, "text": "        )"}
{"line": 241, "text": ""}
{"line": 242, "text": "        self._inspect()"}
{"line": 243, "text": ""}
{"line": 244, "text": "        return self"}
{"line": 245, "text": ""}
{"line": 246, "text": "    def _inspect(self):"}
{"line": 247, "text": ""}
{"line": 248, "text": "        self.definitions.clear()"}
{"line": 249, "text": "        self.references.clear()"}
{"line": 250, "text": "        self.functions.clear()"}
{"line": 251, "text": "        self.classes.clear()"}
{"line": 252, "text": "        self.imports.clear()"}
{"line": 253, "text": ""}
{"line": 254, "text": "        # Imports"}
{"line": 255, "text": ""}
{"line": 256, "text": "        for node in ast.walk(self.tree):"}
{"line": 257, "text": ""}
{"line": 258, "text": "            if isinstance(node, ast.Import):"}
{"line": 259, "text": ""}
{"line": 260, "text": "                for alias in node.names:"}
{"line": 261, "text": ""}
{"line": 262, "text": "                    self.imports.add("}
{"line": 263, "text": "                        alias.asname"}
{"line": 264, "text": "                        or alias.name.split(\".\")[0]"}
{"line": 265, "text": "                    )"}
{"line": 266, "text": ""}
{"line": 267, "text": "            elif isinstance("}
{"line": 268, "text": "                node,"}
{"line": 269, "text": "                ast.ImportFrom,"}
{"line": 270, "text": "            ):"}
{"line": 271, "text": ""}
{"line": 272, "text": "                for alias in node.names:"}
{"line": 273, "text": ""}
{"line": 274, "text": "                    self.imports.add("}
{"line": 275, "text": "                        alias.asname"}
{"line": 276, "text": "                        or alias.name"}
{"line": 277, "text": "                    )"}
{"line": 278, "text": ""}
{"line": 279, "text": "        # Top-level definitions"}
{"line": 280, "text": ""}
{"line": 281, "text": "        for node in self.tree.body:"}
{"line": 282, "text": ""}
{"line": 283, "text": "            if isinstance(node, ast.Assign):"}
{"line": 284, "text": ""}
{"line": 285, "text": "                for target in node.targets:"}
{"line": 286, "text": ""}
{"line": 287, "text": "                    if isinstance("}
{"line": 288, "text": "                        target,"}
{"line": 289, "text": "                        ast.Name,"}
{"line": 290, "text": "                    ):"}
{"line": 291, "text": ""}
{"line": 292, "text": "                        self.definitions["}
{"line": 293, "text": "                            target.id"}
{"line": 294, "text": "                        ] = {"}
{"line": 295, "text": "                            \"line\": node.lineno,"}
{"line": 296, "text": "                            \"kind\": \"assignment\","}
{"line": 297, "text": "                        }"}
{"line": 298, "text": ""}
{"line": 299, "text": "            elif isinstance("}
{"line": 300, "text": "                node,"}
{"line": 301, "text": "                ast.AnnAssign,"}
{"line": 302, "text": "            ):"}
{"line": 303, "text": ""}
{"line": 304, "text": "                if isinstance("}
{"line": 305, "text": "                    node.target,"}
{"line": 306, "text": "                    ast.Name,"}
{"line": 307, "text": "                ):"}
{"line": 308, "text": ""}
{"line": 309, "text": "                    self.definitions["}
{"line": 310, "text": "                        node.target.id"}
{"line": 311, "text": "                    ] = {"}
{"line": 312, "text": "                        \"line\": node.lineno,"}
{"line": 313, "text": "                        \"kind\": \"assignment\","}
{"line": 314, "text": "                    }"}
{"line": 315, "text": ""}
{"line": 316, "text": "            elif isinstance("}
{"line": 317, "text": "                node,"}
{"line": 318, "text": "                ("}
{"line": 319, "text": "                    ast.FunctionDef,"}
{"line": 320, "text": "                    ast.AsyncFunctionDef,"}
{"line": 321, "text": "                    ast.ClassDef,"}
{"line": 322, "text": "                ),"}
{"line": 323, "text": "            ):"}
{"line": 324, "text": ""}
{"line": 325, "text": "                self.definitions["}
{"line": 326, "text": "                    node.name"}
{"line": 327, "text": "                ] = {"}
{"line": 328, "text": "                    \"line\": node.lineno,"}
{"line": 329, "text": "                    \"kind\": type(node).__name__,"}
{"line": 330, "text": "                }"}
{"line": 331, "text": ""}
{"line": 332, "text": "        # Functions/classes anywhere"}
{"line": 333, "text": ""}
{"line": 334, "text": "        for node in ast.walk(self.tree):"}
{"line": 335, "text": ""}
{"line": 336, "text": "            if isinstance("}
{"line": 337, "text": "                node,"}
{"line": 338, "text": "                ("}
{"line": 339, "text": "                    ast.FunctionDef,"}
{"line": 340, "text": "                    ast.AsyncFunctionDef,"}
{"line": 341, "text": "                ),"}
{"line": 342, "text": "            ):"}
{"line": 343, "text": ""}
{"line": 344, "text": "                self.functions[node.name] = {"}
{"line": 345, "text": "                    \"line\": node.lineno,"}
{"line": 346, "text": "                    \"end_line\": getattr("}
{"line": 347, "text": "                        node,"}
{"line": 348, "text": "                        \"end_lineno\","}
{"line": 349, "text": "                        node.lineno,"}
{"line": 350, "text": "                    ),"}
{"line": 351, "text": "                }"}
{"line": 352, "text": ""}
{"line": 353, "text": "            elif isinstance("}
{"line": 354, "text": "                node,"}
{"line": 355, "text": "                ast.ClassDef,"}
{"line": 356, "text": "            ):"}
{"line": 357, "text": ""}
{"line": 358, "text": "                self.classes[node.name] = {"}
{"line": 359, "text": "                    \"line\": node.lineno,"}
{"line": 360, "text": "                    \"end_line\": getattr("}
{"line": 361, "text": "                        node,"}
{"line": 362, "text": "                        \"end_lineno\","}
{"line": 363, "text": "                        node.lineno,"}
{"line": 364, "text": "                    ),"}
{"line": 365, "text": "                }"}
{"line": 366, "text": ""}
{"line": 367, "text": "        # References"}
{"line": 368, "text": ""}
{"line": 369, "text": "        for node in ast.walk(self.tree):"}
{"line": 370, "text": ""}
{"line": 371, "text": "            if not isinstance("}
{"line": 372, "text": "                node,"}
{"line": 373, "text": "                ast.Name,"}
{"line": 374, "text": "            ):"}
{"line": 375, "text": "                continue"}
{"line": 376, "text": ""}
{"line": 377, "text": "            if not isinstance("}
{"line": 378, "text": "                node.ctx,"}
{"line": 379, "text": "                ast.Load,"}
{"line": 380, "text": "            ):"}
{"line": 381, "text": "                continue"}
{"line": 382, "text": ""}
{"line": 383, "text": "            self.references.setdefault("}
{"line": 384, "text": "                node.id,"}
{"line": 385, "text": "                [],"}
{"line": 386, "text": "            ).append(node.lineno)"}
{"line": 387, "text": ""}
{"line": 388, "text": "    def source_segment("}
{"line": 389, "text": "        self,"}
{"line": 390, "text": "        name,"}
{"line": 391, "text": "    ):"}
{"line": 392, "text": ""}
{"line": 393, "text": "        node = None"}
{"line": 394, "text": ""}
{"line": 395, "text": "        if name in self.functions:"}
{"line": 396, "text": ""}
{"line": 397, "text": "            target_line = self.functions["}
{"line": 398, "text": "                name"}
{"line": 399, "text": "            ][\"line\"]"}
{"line": 400, "text": ""}
{"line": 401, "text": "            for n in ast.walk(self.tree):"}
{"line": 402, "text": ""}
{"line": 403, "text": "                if isinstance("}
{"line": 404, "text": "                    n,"}
{"line": 405, "text": "                    ("}
{"line": 406, "text": "                        ast.FunctionDef,"}
{"line": 407, "text": "                        ast.AsyncFunctionDef,"}
{"line": 408, "text": "                    ),"}
{"line": 409, "text": "                ) and n.name == name:"}
{"line": 410, "text": ""}
{"line": 411, "text": "                    if n.lineno == target_line:"}
{"line": 412, "text": "                        node = n"}
{"line": 413, "text": "                        break"}
{"line": 414, "text": ""}
{"line": 415, "text": "        elif name in self.classes:"}
{"line": 416, "text": ""}
{"line": 417, "text": "            target_line = self.classes["}
{"line": 418, "text": "                name"}
{"line": 419, "text": "            ][\"line\"]"}
{"line": 420, "text": ""}
{"line": 421, "text": "            for n in ast.walk(self.tree):"}
{"line": 422, "text": ""}
{"line": 423, "text": "                if isinstance("}
{"line": 424, "text": "                    n,"}
{"line": 425, "text": "                    ast.ClassDef,"}
{"line": 426, "text": "                ) and n.name == name:"}
{"line": 427, "text": ""}
{"line": 428, "text": "                    if n.lineno == target_line:"}
{"line": 429, "text": "                        node = n"}
{"line": 430, "text": "                        break"}
{"line": 431, "text": ""}
{"line": 432, "text": "        if node is None:"}
{"line": 433, "text": "            return None"}
{"line": 434, "text": ""}
{"line": 435, "text": "        return ast.get_source_segment("}
{"line": 436, "text": "            self.source,"}
{"line": 437, "text": "            node,"}
{"line": 438, "text": "        )"}
{"line": 439, "text": ""}
{"line": 440, "text": "    def top_level_source(self):"}
{"line": 441, "text": ""}
{"line": 442, "text": "        return ["}
{"line": 443, "text": "            {"}
{"line": 444, "text": "                \"line\": node.lineno,"}
{"line": 445, "text": "                \"end_line\": getattr("}
{"line": 446, "text": "                    node,"}
{"line": 447, "text": "                    \"end_lineno\","}
{"line": 448, "text": "                    node.lineno,"}
{"line": 449, "text": "                ),"}
{"line": 450, "text": "                \"type\": type(node).__name__,"}
{"line": 451, "text": "            }"}
{"line": 452, "text": "            for node in self.tree.body"}
{"line": 453, "text": "        ]"}
{"line": 454, "text": ""}
{"line": 455, "text": "    def unresolved_references("}
{"line": 456, "text": "        self,"}
{"line": 457, "text": "        names=None,"}
{"line": 458, "text": "    ):"}
{"line": 459, "text": ""}
{"line": 460, "text": "        if names is None:"}
{"line": 461, "text": "            names = sorted("}
{"line": 462, "text": "                self.references"}
{"line": 463, "text": "            )"}
{"line": 464, "text": ""}
{"line": 465, "text": "        result = {}"}
{"line": 466, "text": ""}
{"line": 467, "text": "        builtin_names = set("}
{"line": 468, "text": "            dir(__builtins__)"}
{"line": 469, "text": "        )"}
{"line": 470, "text": ""}
{"line": 471, "text": "        for name in names:"}
{"line": 472, "text": ""}
{"line": 473, "text": "            if name in self.definitions:"}
{"line": 474, "text": "                continue"}
{"line": 475, "text": ""}
{"line": 476, "text": "            if name in self.imports:"}
{"line": 477, "text": "                continue"}
{"line": 478, "text": ""}
{"line": 479, "text": "            if name in builtin_names:"}
{"line": 480, "text": "                continue"}
{"line": 481, "text": ""}
{"line": 482, "text": "            result[name] = self.references.get("}
{"line": 483, "text": "                name,"}
{"line": 484, "text": "                [],"}
{"line": 485, "text": "            )"}
{"line": 486, "text": ""}
{"line": 487, "text": "        return result"}
{"line": 488, "text": ""}
{"line": 489, "text": ""}
{"line": 490, "text": "# ============================================================"}
{"line": 491, "text": "# RUNTIME PROBE"}
{"line": 492, "text": "# ============================================================"}
{"line": 493, "text": ""}
{"line": 494, "text": "class RuntimeProbe:"}
{"line": 495, "text": ""}
{"line": 496, "text": "    def __init__("}
{"line": 497, "text": "        self,"}
{"line": 498, "text": "        terminal,"}
{"line": 499, "text": "    ):"}
{"line": 500, "text": ""}
{"line": 501, "text": "        self.terminal = terminal"}
{"line": 502, "text": ""}
{"line": 503, "text": "    def import_model(self):"}
{"line": 504, "text": ""}
{"line": 505, "text": "        probe = r'''"}
{"line": 506, "text": "import sys"}
{"line": 507, "text": "import traceback"}
{"line": 508, "text": ""}
{"line": 509, "text": "sys.path.insert("}
{"line": 510, "text": "    0,"}
{"line": 511, "text": "    %r"}
{"line": 512, "text": ")"}
{"line": 513, "text": ""}
{"line": 514, "text": "try:"}
{"line": 515, "text": ""}
{"line": 516, "text": "    import bloom_real"}
{"line": 517, "text": ""}
{"line": 518, "text": "    print(\"BLOOM_IMPORT_SUCCESS\")"}
{"line": 519, "text": ""}
{"line": 520, "text": "    names = ["}
{"line": 521, "text": "        \"VALIDATION_TEXT\","}
{"line": 522, "text": "        \"stoi\","}
{"line": 523, "text": "        \"itos\","}
{"line": 524, "text": "        \"vocab_size\","}
{"line": 525, "text": "        \"data\","}
{"line": 526, "text": "        \"validation_data\","}
{"line": 527, "text": "        \"model\","}
{"line": 528, "text": "        \"params\","}
{"line": 529, "text": "        \"adam_m\","}
{"line": 530, "text": "        \"adam_v\","}
{"line": 531, "text": "        \"best_loss\","}
{"line": 532, "text": "    ]"}
{"line": 533, "text": ""}
{"line": 534, "text": "    for name in names:"}
{"line": 535, "text": ""}
{"line": 536, "text": "        if hasattr("}
{"line": 537, "text": "            bloom_real,"}
{"line": 538, "text": "            name,"}
{"line": 539, "text": "        ):"}
{"line": 540, "text": ""}
{"line": 541, "text": "            value = getattr("}
{"line": 542, "text": "                bloom_real,"}
{"line": 543, "text": "                name,"}
{"line": 544, "text": "            )"}
{"line": 545, "text": ""}
{"line": 546, "text": "            try:"}
{"line": 547, "text": "                length = len(value)"}
{"line": 548, "text": "            except Exception:"}
{"line": 549, "text": "                length = None"}
{"line": 550, "text": ""}
{"line": 551, "text": "            shape = getattr("}
{"line": 552, "text": "                value,"}
{"line": 553, "text": "                \"shape\","}
{"line": 554, "text": "                None,"}
{"line": 555, "text": "            )"}
{"line": 556, "text": ""}
{"line": 557, "text": "            print("}
{"line": 558, "text": "                \"RUNTIME_SYMBOL\","}
{"line": 559, "text": "                name,"}
{"line": 560, "text": "                type(value).__name__,"}
{"line": 561, "text": "                \"len=\","}
{"line": 562, "text": "                length,"}
{"line": 563, "text": "                \"shape=\","}
{"line": 564, "text": "                shape,"}
{"line": 565, "text": "            )"}
{"line": 566, "text": ""}
{"line": 567, "text": "        else:"}
{"line": 568, "text": ""}
{"line": 569, "text": "            print("}
{"line": 570, "text": "                \"RUNTIME_MISSING\","}
{"line": 571, "text": "                name,"}
{"line": 572, "text": "            )"}
{"line": 573, "text": ""}
{"line": 574, "text": "except Exception as e:"}
{"line": 575, "text": ""}
{"line": 576, "text": "    print("}
{"line": 577, "text": "        \"BLOOM_IMPORT_FAILURE\","}
{"line": 578, "text": "        type(e).__name__,"}
{"line": 579, "text": "        str(e),"}
{"line": 580, "text": "    )"}
{"line": 581, "text": ""}
{"line": 582, "text": "    traceback.print_exc()"}
{"line": 583, "text": "''' % str(ROOT)"}
{"line": 584, "text": ""}
{"line": 585, "text": "        return self.terminal.run("}
{"line": 586, "text": "            f\"{shlex.quote(sys.executable)} -c {shlex.quote(probe)}\","}
{"line": 587, "text": "            timeout=120,"}
{"line": 588, "text": "        )"}
{"line": 589, "text": ""}
{"line": 590, "text": ""}
{"line": 591, "text": "# ============================================================"}
{"line": 592, "text": "# ERROR DISCERNMENT"}
{"line": 593, "text": "# ============================================================"}
{"line": 594, "text": ""}
{"line": 595, "text": "class ErrorDiscerner:"}
{"line": 596, "text": ""}
{"line": 597, "text": "    PATTERNS = ["}
{"line": 598, "text": ""}
{"line": 599, "text": "        ("}
{"line": 600, "text": "            \"NAME_ERROR\","}
{"line": 601, "text": "            re.compile("}
{"line": 602, "text": "                r\"NameError:\\s+name ['\\\"]([^'\\\"]+)['\\\"] is not defined\""}
{"line": 603, "text": "            ),"}
{"line": 604, "text": "        ),"}
{"line": 605, "text": ""}
{"line": 606, "text": "        ("}
{"line": 607, "text": "            \"ATTRIBUTE_ERROR\","}
{"line": 608, "text": "            re.compile("}
{"line": 609, "text": "                r\"AttributeError:\\s+(.+)\""}
{"line": 610, "text": "            ),"}
{"line": 611, "text": "        ),"}
{"line": 612, "text": ""}
{"line": 613, "text": "        ("}
{"line": 614, "text": "            \"TYPE_ERROR\","}
{"line": 615, "text": "            re.compile("}
{"line": 616, "text": "                r\"TypeError:\\s+(.+)\""}
{"line": 617, "text": "            ),"}
{"line": 618, "text": "        ),"}
{"line": 619, "text": ""}
{"line": 620, "text": "        ("}
{"line": 621, "text": "            \"VALUE_ERROR\","}
{"line": 622, "text": "            re.compile("}
{"line": 623, "text": "                r\"ValueError:\\s+(.+)\""}
{"line": 624, "text": "            ),"}
{"line": 625, "text": "        ),"}
{"line": 626, "text": ""}
{"line": 627, "text": "        ("}
{"line": 628, "text": "            \"KEY_ERROR\","}
{"line": 629, "text": "            re.compile("}
{"line": 630, "text": "                r\"KeyError:\\s+(.+)\""}
{"line": 631, "text": "            ),"}
{"line": 632, "text": "        ),"}
{"line": 633, "text": ""}
{"line": 634, "text": "        ("}
{"line": 635, "text": "            \"FILE_NOT_FOUND\","}
{"line": 636, "text": "            re.compile("}
{"line": 637, "text": "                r\"FileNotFoundError:\\s+(.+)\""}
{"line": 638, "text": "            ),"}
{"line": 639, "text": "        ),"}
{"line": 640, "text": ""}
{"line": 641, "text": "        ("}
{"line": 642, "text": "            \"IMPORT_ERROR\","}
{"line": 643, "text": "            re.compile("}
{"line": 644, "text": "                r\"(?:ImportError|ModuleNotFoundError):\\s+(.+)\""}
{"line": 645, "text": "            ),"}
{"line": 646, "text": "        ),"}
{"line": 647, "text": ""}
{"line": 648, "text": "        ("}
{"line": 649, "text": "            \"SYNTAX_ERROR\","}
{"line": 650, "text": "            re.compile("}
{"line": 651, "text": "                r\"SyntaxError:\\s+(.+)\""}
{"line": 652, "text": "            ),"}
{"line": 653, "text": "        ),"}
{"line": 654, "text": "    ]"}
{"line": 655, "text": ""}
{"line": 656, "text": "    def classify("}
{"line": 657, "text": "        self,"}
{"line": 658, "text": "        stdout,"}
{"line": 659, "text": "        stderr,"}
{"line": 660, "text": "        returncode,"}
{"line": 661, "text": "    ):"}
{"line": 662, "text": ""}
{"line": 663, "text": "        text = ("}
{"line": 664, "text": "            (stdout or \"\")"}
{"line": 665, "text": "            + \"\\n\""}
{"line": 666, "text": "            + (stderr or \"\")"}
{"line": 667, "text": "        )"}
{"line": 668, "text": ""}
{"line": 669, "text": "        for category, pattern in self.PATTERNS:"}
{"line": 670, "text": ""}
{"line": 671, "text": "            match = pattern.search(text)"}
{"line": 672, "text": ""}
{"line": 673, "text": "            if match:"}
{"line": 674, "text": ""}
{"line": 675, "text": "                detail = ("}
{"line": 676, "text": "                    match.group(1)"}
{"line": 677, "text": "                    if match.groups()"}
{"line": 678, "text": "                    else match.group(0)"}
{"line": 679, "text": "                )"}
{"line": 680, "text": ""}
{"line": 681, "text": "                return {"}
{"line": 682, "text": "                    \"category\": category,"}
{"line": 683, "text": "                    \"detail\": detail,"}
{"line": 684, "text": "                    \"confidence\": 1.0,"}
{"line": 685, "text": "                    \"raw\": text[-5000:],"}
{"line": 686, "text": "                }"}
{"line": 687, "text": ""}
{"line": 688, "text": "        if returncode == 0:"}
{"line": 689, "text": ""}
{"line": 690, "text": "            return {"}
{"line": 691, "text": "                \"category\": \"NO_ERROR\","}
{"line": 692, "text": "                \"detail\": \"\","}
{"line": 693, "text": "                \"confidence\": 1.0,"}
{"line": 694, "text": "                \"raw\": text[-5000:],"}
{"line": 695, "text": "            }"}
{"line": 696, "text": ""}
{"line": 697, "text": "        return {"}
{"line": 698, "text": "            \"category\": \"UNKNOWN_RUNTIME_FAILURE\","}
{"line": 699, "text": "            \"detail\": text[-2000:],"}
{"line": 700, "text": "            \"confidence\": 0.25,"}
{"line": 701, "text": "            \"raw\": text[-5000:],"}
{"line": 702, "text": "        }"}
{"line": 703, "text": ""}
{"line": 704, "text": ""}
{"line": 705, "text": "# ============================================================"}
{"line": 706, "text": "# DEPENDENCY / NEXT-STEP REASONER"}
{"line": 707, "text": "# ============================================================"}
{"line": 708, "text": ""}
{"line": 709, "text": "class NextStepReasoner:"}
{"line": 710, "text": ""}
{"line": 711, "text": "    REQUIRED = ["}
{"line": 712, "text": "        \"load_text\","}
{"line": 713, "text": "        \"stoi\","}
{"line": 714, "text": "        \"itos\","}
{"line": 715, "text": "        \"vocab_size\","}
{"line": 716, "text": "        \"data\","}
{"line": 717, "text": "        \"validation_data\","}
{"line": 718, "text": "        \"VALIDATION_TEXT\","}
{"line": 719, "text": "        \"get_batch\","}
{"line": 720, "text": "        \"GPT\","}
{"line": 721, "text": "        \"model\","}
{"line": 722, "text": "        \"params\","}
{"line": 723, "text": "        \"adam_m\","}
{"line": 724, "text": "        \"adam_v\","}
{"line": 725, "text": "        \"best_loss\","}
{"line": 726, "text": "        \"generate\","}
{"line": 727, "text": "        \"retrieve\","}
{"line": 728, "text": "    ]"}
{"line": 729, "text": ""}
{"line": 730, "text": "    def __init__("}
{"line": 731, "text": "        self,"}
{"line": 732, "text": "        inspector,"}
{"line": 733, "text": "    ):"}
{"line": 734, "text": ""}
{"line": 735, "text": "        self.inspector = inspector"}
{"line": 736, "text": ""}
{"line": 737, "text": "    def required_symbol_report(self):"}
{"line": 738, "text": ""}
{"line": 739, "text": "        result = {}"}
{"line": 740, "text": ""}
{"line": 741, "text": "        for name in self.REQUIRED:"}
{"line": 742, "text": ""}
{"line": 743, "text": "            result[name] = {"}
{"line": 744, "text": "                \"defined\": ("}
{"line": 745, "text": "                    name in self.inspector.definitions"}
{"line": 746, "text": "                ),"}
{"line": 747, "text": "                \"definition\": self.inspector.definitions.get("}
{"line": 748, "text": "                    name"}
{"line": 749, "text": "                ),"}
{"line": 750, "text": "                \"references\": self.inspector.references.get("}
{"line": 751, "text": "                    name,"}
{"line": 752, "text": "                    [],"}
{"line": 753, "text": "                ),"}
{"line": 754, "text": "            }"}
{"line": 755, "text": ""}
{"line": 756, "text": "        return result"}
{"line": 757, "text": ""}
{"line": 758, "text": "    def dependency_report(self):"}
{"line": 759, "text": ""}
{"line": 760, "text": "        report = {}"}
{"line": 761, "text": ""}
{"line": 762, "text": "        for name in ["}
{"line": 763, "text": "            \"load_text\","}
{"line": 764, "text": "            \"get_batch\","}
{"line": 765, "text": "            \"save_ckpt\","}
{"line": 766, "text": "            \"generate\","}
{"line": 767, "text": "            \"retrieve\","}
{"line": 768, "text": "        ]:"}
{"line": 769, "text": ""}
{"line": 770, "text": "            if name not in self.inspector.functions:"}
{"line": 771, "text": "                continue"}
{"line": 772, "text": ""}
{"line": 773, "text": "            segment = self.inspector.source_segment("}
{"line": 774, "text": "                name"}
{"line": 775, "text": "            )"}
{"line": 776, "text": ""}
{"line": 777, "text": "            if not segment:"}
{"line": 778, "text": "                continue"}
{"line": 779, "text": ""}
{"line": 780, "text": "            try:"}
{"line": 781, "text": "                tree = ast.parse("}
{"line": 782, "text": "                    segment"}
{"line": 783, "text": "                )"}
{"line": 784, "text": "            except Exception:"}
{"line": 785, "text": "                continue"}
{"line": 786, "text": ""}
{"line": 787, "text": "            loads = sorted({"}
{"line": 788, "text": "                n.id"}
{"line": 789, "text": "                for n in ast.walk(tree)"}
{"line": 790, "text": "                if isinstance("}
{"line": 791, "text": "                    n,"}
{"line": 792, "text": "                    ast.Name,"}
{"line": 793, "text": "                )"}
{"line": 794, "text": "                and isinstance("}
{"line": 795, "text": "                    n.ctx,"}
{"line": 796, "text": "                    ast.Load,"}
{"line": 797, "text": "                )"}
{"line": 798, "text": "            })"}
{"line": 799, "text": ""}
{"line": 800, "text": "            report[name] = {"}
{"line": 801, "text": ""}
{"line": 802, "text": "                \"reads\": loads,"}
{"line": 803, "text": ""}
{"line": 804, "text": "                \"undefined_reads\": ["}
{"line": 805, "text": "                    x"}
{"line": 806, "text": "                    for x in loads"}
{"line": 807, "text": "                    if ("}
{"line": 808, "text": "                        x not in self.inspector.definitions"}
{"line": 809, "text": "                        and x not in self.inspector.imports"}
{"line": 810, "text": "                        and x not in dir(__builtins__)"}
{"line": 811, "text": "                    )"}
{"line": 812, "text": "                ],"}
{"line": 813, "text": "            }"}
{"line": 814, "text": ""}
{"line": 815, "text": "        return report"}
{"line": 816, "text": ""}
{"line": 817, "text": "    def decide("}
{"line": 818, "text": "        self,"}
{"line": 819, "text": "        runtime_error,"}
{"line": 820, "text": "    ):"}
{"line": 821, "text": ""}
{"line": 822, "text": "        symbols = self.required_symbol_report()"}
{"line": 823, "text": "        dependencies = self.dependency_report()"}
{"line": 824, "text": ""}
{"line": 825, "text": "        missing = ["}
{"line": 826, "text": "            name"}
{"line": 827, "text": "            for name, info in symbols.items()"}
{"line": 828, "text": "            if not info[\"defined\"]"}
{"line": 829, "text": "        ]"}
{"line": 830, "text": ""}
{"line": 831, "text": "        category = runtime_error["}
{"line": 832, "text": "            \"category\""}
{"line": 833, "text": "        ]"}
{"line": 834, "text": ""}
{"line": 835, "text": "        decision = {"}
{"line": 836, "text": "            \"decision\": None,"}
{"line": 837, "text": "            \"confidence\": 0.0,"}
{"line": 838, "text": "            \"reason\": [],"}
{"line": 839, "text": "            \"next_actions\": [],"}
{"line": 840, "text": "            \"do_not_do\": [],"}
{"line": 841, "text": "        }"}
{"line": 842, "text": ""}
{"line": 843, "text": "        # ----------------------------------------------------"}
{"line": 844, "text": "        # CURRENT BLOOM CONDITION"}
{"line": 845, "text": "        # ----------------------------------------------------"}
{"line": 846, "text": ""}
{"line": 847, "text": "        if category == \"NAME_ERROR\":"}
{"line": 848, "text": ""}
{"line": 849, "text": "            missing_name = runtime_error["}
{"line": 850, "text": "                \"detail\""}
{"line": 851, "text": "            ]"}
{"line": 852, "text": ""}
{"line": 853, "text": "            if ("}
{"line": 854, "text": "                missing_name"}
{"line": 855, "text": "                in symbols"}
{"line": 856, "text": "                and not symbols["}
{"line": 857, "text": "                    missing_name"}
{"line": 858, "text": "                ][\"defined\"]"}
{"line": 859, "text": "            ):"}
{"line": 860, "text": ""}
{"line": 861, "text": "                decision[\"decision\"] = ("}
{"line": 862, "text": "                    \"TRACE_MISSING_SYMBOL\""}
{"line": 863, "text": "                )"}
{"line": 864, "text": ""}
{"line": 865, "text": "                decision[\"confidence\"] = 1.0"}
{"line": 866, "text": ""}
{"line": 867, "text": "                decision[\"reason\"].append("}
{"line": 868, "text": "                    f\"{missing_name} is referenced \""}
{"line": 869, "text": "                    \"during top-level execution but \""}
{"line": 870, "text": "                    \"has no top-level definition.\""}
{"line": 871, "text": "                )"}
{"line": 872, "text": ""}
{"line": 873, "text": "                refs = symbols["}
{"line": 874, "text": "                    missing_name"}
{"line": 875, "text": "                ][\"references\"]"}
{"line": 876, "text": ""}
{"line": 877, "text": "                decision[\"reason\"].append("}
{"line": 878, "text": "                    f\"Static references occur at lines {refs}.\""}
{"line": 879, "text": "                )"}
{"line": 880, "text": ""}
{"line": 881, "text": "                decision[\"next_actions\"].extend(["}
{"line": 882, "text": "                    \"inspect the producer function/source \""}
{"line": 883, "text": "                    \"for the missing symbol\","}
{"line": 884, "text": "                    \"determine whether the producer returns \""}
{"line": 885, "text": "                    \"the required value\","}
{"line": 886, "text": "                    \"determine where the value should enter \""}
{"line": 887, "text": "                    \"the runtime\","}
{"line": 888, "text": "                    \"repair only after the data contract \""}
{"line": 889, "text": "                    \"is established\","}
{"line": 890, "text": "                    \"re-run AST inspection\","}
{"line": 891, "text": "                    \"re-run import probe\","}
{"line": 892, "text": "                ])"}
{"line": 893, "text": ""}
{"line": 894, "text": "                decision[\"do_not_do\"].extend(["}
{"line": 895, "text": "                    \"do not insert a guessed assignment\","}
{"line": 896, "text": "                    \"do not create synthetic vocabulary\","}
{"line": 897, "text": "                    \"do not invent stoi/itos/data values\","}
{"line": 898, "text": "                    \"do not declare the runtime repaired \""}
{"line": 899, "text": "                    \"until import succeeds\","}
{"line": 900, "text": "                ])"}
{"line": 901, "text": ""}
{"line": 902, "text": "                return decision"}
{"line": 903, "text": ""}
{"line": 904, "text": "        # ----------------------------------------------------"}
{"line": 905, "text": "        # MISSING DATA PIPELINE"}
{"line": 906, "text": "        # ----------------------------------------------------"}
{"line": 907, "text": ""}
{"line": 908, "text": "        pipeline_missing = ["}
{"line": 909, "text": "            x"}
{"line": 910, "text": "            for x in ["}
{"line": 911, "text": "                \"stoi\","}
{"line": 912, "text": "                \"itos\","}
{"line": 913, "text": "                \"vocab_size\","}
{"line": 914, "text": "                \"data\","}
{"line": 915, "text": "            ]"}
{"line": 916, "text": "            if not symbols[x][\"defined\"]"}
{"line": 917, "text": "        ]"}
{"line": 918, "text": ""}
{"line": 919, "text": "        if pipeline_missing:"}
{"line": 920, "text": ""}
{"line": 921, "text": "            decision[\"decision\"] = ("}
{"line": 922, "text": "                \"RECONSTRUCT_DATA_PIPELINE\""}
{"line": 923, "text": "            )"}
{"line": 924, "text": ""}
{"line": 925, "text": "            decision[\"confidence\"] = 0.98"}
{"line": 926, "text": ""}
{"line": 927, "text": "            decision[\"reason\"].append("}
{"line": 928, "text": "                \"The model has a broken vocabulary/data \""}
{"line": 929, "text": "                \"runtime contract, not merely one missing name.\""}
{"line": 930, "text": "            )"}
{"line": 931, "text": ""}
{"line": 932, "text": "            decision[\"reason\"].append("}
{"line": 933, "text": "                \"The missing symbols are consumed by \""}
{"line": 934, "text": "                \"checkpointing, generation, and batching.\""}
{"line": 935, "text": "            )"}
{"line": 936, "text": ""}
{"line": 937, "text": "            decision[\"next_actions\"].extend(["}
{"line": 938, "text": "                \"inspect load_text() completely\","}
{"line": 939, "text": "                \"inspect its return values\","}
{"line": 940, "text": "                \"identify training corpus\","}
{"line": 941, "text": "                \"identify validation corpus\","}
{"line": 942, "text": "                \"construct stoi and itos from verified corpus\","}
{"line": 943, "text": "                \"derive vocab_size from itos/stoi\","}
{"line": 944, "text": "                \"construct data from the same verified vocabulary\","}
{"line": 945, "text": "                \"verify get_batch() against data length\","}
{"line": 946, "text": "                \"verify checkpoint serialization\","}
{"line": 947, "text": "                \"verify generation lookup\","}
{"line": 948, "text": "                \"import the model\","}
{"line": 949, "text": "                \"execute one forward pass\","}
{"line": 950, "text": "                \"execute one backward pass\","}
{"line": 951, "text": "                \"only then permit training\","}
{"line": 952, "text": "            ])"}
{"line": 953, "text": ""}
{"line": 954, "text": "            decision[\"do_not_do\"].extend(["}
{"line": 955, "text": "                \"do not guess an insertion point\","}
{"line": 956, "text": "                \"do not hard-code vocab_size\","}
{"line": 957, "text": "                \"do not use random vocabulary\","}
{"line": 958, "text": "                \"do not fabricate training data\","}
{"line": 959, "text": "            ])"}
{"line": 960, "text": ""}
{"line": 961, "text": "            return decision"}
{"line": 962, "text": ""}
{"line": 963, "text": "        # ----------------------------------------------------"}
{"line": 964, "text": "        # OTHERWISE"}
{"line": 965, "text": "        # ----------------------------------------------------"}
{"line": 966, "text": ""}
{"line": 967, "text": "        decision[\"decision\"] = ("}
{"line": 968, "text": "            \"INVESTIGATE_RUNTIME_FAILURE\""}
{"line": 969, "text": "        )"}
{"line": 970, "text": ""}
{"line": 971, "text": "        decision[\"confidence\"] = 0.5"}
{"line": 972, "text": ""}
{"line": 973, "text": "        decision[\"reason\"].append("}
{"line": 974, "text": "            \"The observed error does not map cleanly \""}
{"line": 975, "text": "            \"to a verified missing runtime dependency.\""}
{"line": 976, "text": "        )"}
{"line": 977, "text": ""}
{"line": 978, "text": "        decision[\"next_actions\"].extend(["}
{"line": 979, "text": "            \"capture complete traceback\","}
{"line": 980, "text": "            \"map failing line to AST node\","}
{"line": 981, "text": "            \"inspect local/global dependencies\","}
{"line": 982, "text": "            \"reproduce in isolated subprocess\","}
{"line": 983, "text": "            \"verify the smallest causal boundary\","}
{"line": 984, "text": "        ])"}
{"line": 985, "text": ""}
{"line": 986, "text": "        return decision"}
{"line": 987, "text": ""}
{"line": 988, "text": ""}
{"line": 989, "text": "# ============================================================"}
{"line": 990, "text": "# VERIFIED REPAIR PLAN GENERATOR"}
{"line": 991, "text": "# ============================================================"}
{"line": 992, "text": ""}
{"line": 993, "text": "class RepairPlanner:"}
{"line": 994, "text": ""}
{"line": 995, "text": "    def __init__("}
{"line": 996, "text": "        self,"}
{"line": 997, "text": "        inspector,"}
{"line": 998, "text": "        reasoner,"}
{"line": 999, "text": "    ):"}
{"line": 1000, "text": ""}
{"line": 1001, "text": "        self.inspector = inspector"}
{"line": 1002, "text": "        self.reasoner = reasoner"}
{"line": 1003, "text": ""}
{"line": 1004, "text": "    def build(self):"}
{"line": 1005, "text": ""}
{"line": 1006, "text": "        load_text = ("}
{"line": 1007, "text": "            self.inspector.source_segment("}
{"line": 1008, "text": "                \"load_text\""}
{"line": 1009, "text": "            )"}
{"line": 1010, "text": "            or \"\""}
{"line": 1011, "text": "        )"}
{"line": 1012, "text": ""}
{"line": 1013, "text": "        get_batch = ("}
{"line": 1014, "text": "            self.inspector.source_segment("}
{"line": 1015, "text": "                \"get_batch\""}
{"line": 1016, "text": "            )"}
{"line": 1017, "text": "            or \"\""}
{"line": 1018, "text": "        )"}
{"line": 1019, "text": ""}
{"line": 1020, "text": "        return {"}
{"line": 1021, "text": ""}
{"line": 1022, "text": "            \"repair_policy\":"}
{"line": 1023, "text": "                \"EVIDENCE_FIRST\","}
{"line": 1024, "text": ""}
{"line": 1025, "text": "            \"source_integrity\": {"}
{"line": 1026, "text": "                \"bytes\": len("}
{"line": 1027, "text": "                    self.inspector.source.encode("}
{"line": 1028, "text": "                        \"utf-8\""}
{"line": 1029, "text": "                    )"}
{"line": 1030, "text": "                ),"}
{"line": 1031, "text": "                \"sha256\":"}
{"line": 1032, "text": "                    hashlib.sha256("}
{"line": 1033, "text": "                        self.inspector.source.encode("}
{"line": 1034, "text": "                            \"utf-8\""}
{"line": 1035, "text": "                        )"}
{"line": 1036, "text": "                    ).hexdigest(),"}
{"line": 1037, "text": "            },"}
{"line": 1038, "text": ""}
{"line": 1039, "text": "            \"load_text_source\":"}
{"line": 1040, "text": "                load_text,"}
{"line": 1041, "text": ""}
{"line": 1042, "text": "            \"get_batch_source\":"}
{"line": 1043, "text": "                get_batch,"}
{"line": 1044, "text": ""}
{"line": 1045, "text": "            \"required_symbols\":"}
{"line": 1046, "text": "                self.reasoner.required_symbol_report(),"}
{"line": 1047, "text": ""}
{"line": 1048, "text": "            \"dependencies\":"}
{"line": 1049, "text": "                self.reasoner.dependency_report(),"}
{"line": 1050, "text": ""}
{"line": 1051, "text": "            \"repair_order\": ["}
{"line": 1052, "text": ""}
{"line": 1053, "text": "                {"}
{"line": 1054, "text": "                    \"stage\": 1,"}
{"line": 1055, "text": "                    \"name\": \"CORPUS_CONTRACT\","}
{"line": 1056, "text": "                    \"purpose\":"}
{"line": 1057, "text": "                        \"Establish exactly what load_text \""}
{"line": 1058, "text": "                        \"loads and returns.\","}
{"line": 1059, "text": "                },"}
{"line": 1060, "text": ""}
{"line": 1061, "text": "                {"}
{"line": 1062, "text": "                    \"stage\": 2,"}
{"line": 1063, "text": "                    \"name\": \"VOCABULARY_CONTRACT\","}
{"line": 1064, "text": "                    \"purpose\":"}
{"line": 1065, "text": "                        \"Establish stoi, itos and vocab_size \""}
{"line": 1066, "text": "                        \"from the verified corpus.\","}
{"line": 1067, "text": "                },"}
{"line": 1068, "text": ""}
{"line": 1069, "text": "                {"}
{"line": 1070, "text": "                    \"stage\": 3,"}
{"line": 1071, "text": "                    \"name\": \"TOKEN_DATA_CONTRACT\","}
{"line": 1072, "text": "                    \"purpose\":"}
{"line": 1073, "text": "                        \"Establish data and validation data \""}
{"line": 1074, "text": "                        \"with explicit provenance.\","}
{"line": 1075, "text": "                },"}
{"line": 1076, "text": ""}
{"line": 1077, "text": "                {"}
{"line": 1078, "text": "                    \"stage\": 4,"}
{"line": 1079, "text": "                    \"name\": \"BATCH_CONTRACT\","}
{"line": 1080, "text": "                    \"purpose\":"}
{"line": 1081, "text": "                        \"Verify get_batch() can legally sample \""}
{"line": 1082, "text": "                        \"the resulting data.\","}
{"line": 1083, "text": "                },"}
{"line": 1084, "text": ""}
{"line": 1085, "text": "                {"}
{"line": 1086, "text": "                    \"stage\": 5,"}
{"line": 1087, "text": "                    \"name\": \"MODEL_CONTRACT\","}
{"line": 1088, "text": "                    \"purpose\":"}
{"line": 1089, "text": "                        \"Instantiate GPT only after vocabulary \""}
{"line": 1090, "text": "                        \"dimensions are valid.\","}
{"line": 1091, "text": "                },"}
{"line": 1092, "text": ""}
{"line": 1093, "text": "                {"}
{"line": 1094, "text": "                    \"stage\": 6,"}
{"line": 1095, "text": "                    \"name\": \"GRADIENT_CONTRACT\","}
{"line": 1096, "text": "                    \"purpose\":"}
{"line": 1097, "text": "                        \"Execute forward/backward without training.\","}
{"line": 1098, "text": "                },"}
{"line": 1099, "text": ""}
{"line": 1100, "text": "                {"}
{"line": 1101, "text": "                    \"stage\": 7,"}
{"line": 1102, "text": "                    \"name\": \"CHECKPOINT_CONTRACT\","}
{"line": 1103, "text": "                    \"purpose\":"}
{"line": 1104, "text": "                        \"Verify checkpoint state can be serialized.\","}
{"line": 1105, "text": "                },"}
{"line": 1106, "text": ""}
{"line": 1107, "text": "                {"}
{"line": 1108, "text": "                    \"stage\": 8,"}
{"line": 1109, "text": "                    \"name\": \"GENERATION_CONTRACT\","}
{"line": 1110, "text": "                    \"purpose\":"}
{"line": 1111, "text": "                        \"Verify stoi/itos/model generation path.\","}
{"line": 1112, "text": "                },"}
{"line": 1113, "text": ""}
{"line": 1114, "text": "                {"}
{"line": 1115, "text": "                    \"stage\": 9,"}
{"line": 1116, "text": "                    \"name\": \"TRAINING_PERMISSION\","}
{"line": 1117, "text": "                    \"purpose\":"}
{"line": 1118, "text": "                        \"Permit training only after all prior stages pass.\","}
{"line": 1119, "text": "                },"}
{"line": 1120, "text": "            ],"}
{"line": 1121, "text": ""}
{"line": 1122, "text": "            \"current_status\":"}
{"line": 1123, "text": "                \"REPAIR_REQUIRED\","}
{"line": 1124, "text": "        }"}
{"line": 1125, "text": ""}
{"line": 1126, "text": ""}
{"line": 1127, "text": "# ============================================================"}
{"line": 1128, "text": "# SYSTEM EXECUTION"}
{"line": 1129, "text": "# ============================================================"}
{"line": 1130, "text": ""}
{"line": 1131, "text": "class BloomOperator:"}
{"line": 1132, "text": ""}
{"line": 1133, "text": "    def __init__(self):"}
{"line": 1134, "text": ""}
{"line": 1135, "text": "        self.terminal = BloomTerminal()"}
{"line": 1136, "text": ""}
{"line": 1137, "text": "        self.inspector = ("}
{"line": 1138, "text": "            SourceIntrospector()"}
{"line": 1139, "text": "        )"}
{"line": 1140, "text": ""}
{"line": 1141, "text": "        self.discerner = ("}
{"line": 1142, "text": "            ErrorDiscerner()"}
{"line": 1143, "text": "        )"}
{"line": 1144, "text": ""}
{"line": 1145, "text": "        self.inspector.load()"}
{"line": 1146, "text": ""}
{"line": 1147, "text": "        self.reasoner = ("}
{"line": 1148, "text": "            NextStepReasoner("}
{"line": 1149, "text": "                self.inspector"}
{"line": 1150, "text": "            )"}
{"line": 1151, "text": "        )"}
{"line": 1152, "text": ""}
{"line": 1153, "text": "        self.planner = ("}
{"line": 1154, "text": "            RepairPlanner("}
{"line": 1155, "text": "                self.inspector,"}
{"line": 1156, "text": "                self.reasoner,"}
{"line": 1157, "text": "            )"}
{"line": 1158, "text": "        )"}
{"line": 1159, "text": ""}
{"line": 1160, "text": "    def run(self):"}
{"line": 1161, "text": ""}
{"line": 1162, "text": "        started = time.time()"}
{"line": 1163, "text": ""}
{"line": 1164, "text": "        print(\"=\" * 80)"}
{"line": 1165, "text": "        print("}
{"line": 1166, "text": "            \"BLOOM AUTONOMOUS OPERATOR\""}
{"line": 1167, "text": "        )"}
{"line": 1168, "text": "        print(\"=\" * 80)"}
{"line": 1169, "text": "        print("}
{"line": 1170, "text": "            \"MODE: EVIDENCE-FIRST\""}
{"line": 1171, "text": "        )"}
{"line": 1172, "text": "        print("}
{"line": 1173, "text": "            \"ROOT:\","}
{"line": 1174, "text": "            ROOT,"}
{"line": 1175, "text": "        )"}
{"line": 1176, "text": "        print("}
{"line": 1177, "text": "            \"MODEL:\","}
{"line": 1178, "text": "            MODEL,"}
{"line": 1179, "text": "        )"}
{"line": 1180, "text": ""}
{"line": 1181, "text": "        print()"}
{"line": 1182, "text": "        print(\"=\" * 80)"}
{"line": 1183, "text": "        print(\"1. SOURCE INTROSPECTION\")"}
{"line": 1184, "text": "        print(\"=\" * 80)"}
{"line": 1185, "text": ""}
{"line": 1186, "text": "        print("}
{"line": 1187, "text": "            \"AST: SUCCESS\""}
{"line": 1188, "text": "        )"}
{"line": 1189, "text": ""}
{"line": 1190, "text": "        print("}
{"line": 1191, "text": "            \"TOP-LEVEL DEFINITIONS:\","}
{"line": 1192, "text": "            len("}
{"line": 1193, "text": "                self.inspector.definitions"}
{"line": 1194, "text": "            ),"}
{"line": 1195, "text": "        )"}
{"line": 1196, "text": ""}
{"line": 1197, "text": "        print("}
{"line": 1198, "text": "            \"FUNCTIONS:\","}
{"line": 1199, "text": "            len("}
{"line": 1200, "text": "                self.inspector.functions"}
{"line": 1201, "text": "            ),"}
{"line": 1202, "text": "        )"}
{"line": 1203, "text": ""}
{"line": 1204, "text": "        print("}
{"line": 1205, "text": "            \"CLASSES:\","}
{"line": 1206, "text": "            len("}
{"line": 1207, "text": "                self.inspector.classes"}
{"line": 1208, "text": "            ),"}
{"line": 1209, "text": "        )"}
{"line": 1210, "text": ""}
{"line": 1211, "text": "        print()"}
{"line": 1212, "text": "        print(\"=\" * 80)"}
{"line": 1213, "text": "        print(\"2. REQUIRED RUNTIME CONTRACT\")"}
{"line": 1214, "text": "        print(\"=\" * 80)"}
{"line": 1215, "text": ""}
{"line": 1216, "text": "        symbols = ("}
{"line": 1217, "text": "            self.reasoner"}
{"line": 1218, "text": "            .required_symbol_report()"}
{"line": 1219, "text": "        )"}
{"line": 1220, "text": ""}
{"line": 1221, "text": "        for name, info in symbols.items():"}
{"line": 1222, "text": ""}
{"line": 1223, "text": "            print("}
{"line": 1224, "text": "                f\"{name:<22} \""}
{"line": 1225, "text": "                f\"defined={info['defined']} \""}
{"line": 1226, "text": "                f\"refs={info['references']}\""}
{"line": 1227, "text": "            )"}
{"line": 1228, "text": ""}
{"line": 1229, "text": "        print()"}
{"line": 1230, "text": "        print(\"=\" * 80)"}
{"line": 1231, "text": "        print(\"3. ACTUAL RUNTIME PROBE\")"}
{"line": 1232, "text": "        print(\"=\" * 80)"}
{"line": 1233, "text": ""}
{"line": 1234, "text": "        runtime = ("}
{"line": 1235, "text": "            RuntimeProbe("}
{"line": 1236, "text": "                self.terminal"}
{"line": 1237, "text": "            )"}
{"line": 1238, "text": "            .import_model()"}
{"line": 1239, "text": "        )"}
{"line": 1240, "text": ""}
{"line": 1241, "text": "        print("}
{"line": 1242, "text": "            runtime.stdout"}
{"line": 1243, "text": "        )"}
{"line": 1244, "text": ""}
{"line": 1245, "text": "        if runtime.stderr:"}
{"line": 1246, "text": ""}
{"line": 1247, "text": "            print("}
{"line": 1248, "text": "                \"--- STDERR ---\""}
{"line": 1249, "text": "            )"}
{"line": 1250, "text": ""}
{"line": 1251, "text": "            print("}
{"line": 1252, "text": "                runtime.stderr"}
{"line": 1253, "text": "            )"}
{"line": 1254, "text": ""}
{"line": 1255, "text": "        error = ("}
{"line": 1256, "text": "            self.discerner.classify("}
{"line": 1257, "text": "                runtime.stdout,"}
{"line": 1258, "text": "                runtime.stderr,"}
{"line": 1259, "text": "                runtime.returncode,"}
{"line": 1260, "text": "            )"}
{"line": 1261, "text": "        )"}
{"line": 1262, "text": ""}
{"line": 1263, "text": "        print()"}
{"line": 1264, "text": "        print(\"=\" * 80)"}
{"line": 1265, "text": "        print(\"4. ERROR DISCERNMENT\")"}
{"line": 1266, "text": "        print(\"=\" * 80)"}
{"line": 1267, "text": ""}
{"line": 1268, "text": "        print("}
{"line": 1269, "text": "            \"CATEGORY:\","}
{"line": 1270, "text": "            error[\"category\"],"}
{"line": 1271, "text": "        )"}
{"line": 1272, "text": ""}
{"line": 1273, "text": "        print("}
{"line": 1274, "text": "            \"DETAIL:\","}
{"line": 1275, "text": "            error[\"detail\"],"}
{"line": 1276, "text": "        )"}
{"line": 1277, "text": ""}
{"line": 1278, "text": "        print("}
{"line": 1279, "text": "            \"CONFIDENCE:\","}
{"line": 1280, "text": "            error[\"confidence\"],"}
{"line": 1281, "text": "        )"}
{"line": 1282, "text": ""}
{"line": 1283, "text": "        print()"}
{"line": 1284, "text": "        print(\"=\" * 80)"}
{"line": 1285, "text": "        print(\"5. NEXT-STEP REASONING\")"}
{"line": 1286, "text": "        print(\"=\" * 80)"}
{"line": 1287, "text": ""}
{"line": 1288, "text": "        decision = ("}
{"line": 1289, "text": "            self.reasoner.decide("}
{"line": 1290, "text": "                error"}
{"line": 1291, "text": "            )"}
{"line": 1292, "text": "        )"}
{"line": 1293, "text": ""}
{"line": 1294, "text": "        print("}
{"line": 1295, "text": "            \"DECISION:\","}
{"line": 1296, "text": "            decision[\"decision\"],"}
{"line": 1297, "text": "        )"}
{"line": 1298, "text": ""}
{"line": 1299, "text": "        print("}
{"line": 1300, "text": "            \"CONFIDENCE:\","}
{"line": 1301, "text": "            decision[\"confidence\"],"}
{"line": 1302, "text": "        )"}
{"line": 1303, "text": ""}
{"line": 1304, "text": "        print()"}
{"line": 1305, "text": "        print(\"REASONS:\")"}
{"line": 1306, "text": ""}
{"line": 1307, "text": "        for item in decision[\"reason\"]:"}
{"line": 1308, "text": ""}
{"line": 1309, "text": "            print("}
{"line": 1310, "text": "                \" -\","}
{"line": 1311, "text": "                item,"}
{"line": 1312, "text": "            )"}
{"line": 1313, "text": ""}
{"line": 1314, "text": "        print()"}
{"line": 1315, "text": "        print(\"NEXT ACTIONS:\")"}
{"line": 1316, "text": ""}
{"line": 1317, "text": "        for i, item in enumerate("}
{"line": 1318, "text": "            decision[\"next_actions\"],"}
{"line": 1319, "text": "            1,"}
{"line": 1320, "text": "        ):"}
{"line": 1321, "text": ""}
{"line": 1322, "text": "            print("}
{"line": 1323, "text": "                f\" {i:02d}.\","}
{"line": 1324, "text": "                item,"}
{"line": 1325, "text": "            )"}
{"line": 1326, "text": ""}
{"line": 1327, "text": "        print()"}
{"line": 1328, "text": "        print(\"DO NOT DO:\")"}
{"line": 1329, "text": ""}
{"line": 1330, "text": "        for item in decision[\"do_not_do\"]:"}
{"line": 1331, "text": ""}
{"line": 1332, "text": "            print("}
{"line": 1333, "text": "                \" -\","}
{"line": 1334, "text": "                item,"}
{"line": 1335, "text": "            )"}
{"line": 1336, "text": ""}
{"line": 1337, "text": "        print()"}
{"line": 1338, "text": "        print(\"=\" * 80)"}
{"line": 1339, "text": "        print(\"6. VERIFIED REPAIR PLAN\")"}
{"line": 1340, "text": "        print(\"=\" * 80)"}
{"line": 1341, "text": ""}
{"line": 1342, "text": "        plan = self.planner.build()"}
{"line": 1343, "text": ""}
{"line": 1344, "text": "        for stage in plan["}
{"line": 1345, "text": "            \"repair_order\""}
{"line": 1346, "text": "        ]:"}
{"line": 1347, "text": ""}
{"line": 1348, "text": "            print("}
{"line": 1349, "text": "                f\"{stage['stage']:02d}. \""}
{"line": 1350, "text": "                f\"{stage['name']}\""}
{"line": 1351, "text": "            )"}
{"line": 1352, "text": ""}
{"line": 1353, "text": "            print("}
{"line": 1354, "text": "                \"    \","}
{"line": 1355, "text": "                stage[\"purpose\"],"}
{"line": 1356, "text": "            )"}
{"line": 1357, "text": ""}
{"line": 1358, "text": "        print()"}
{"line": 1359, "text": "        print(\"=\" * 80)"}
{"line": 1360, "text": "        print(\"7. CURRENT FORENSIC VERDICT\")"}
{"line": 1361, "text": "        print(\"=\" * 80)"}
{"line": 1362, "text": ""}
{"line": 1363, "text": "        print("}
{"line": 1364, "text": "            \"STATUS: REPAIR_REQUIRED\""}
{"line": 1365, "text": "        )"}
{"line": 1366, "text": ""}
{"line": 1367, "text": "        print("}
{"line": 1368, "text": "            \"FIRST OBSERVED FAILURE:\","}
{"line": 1369, "text": "            error[\"category\"],"}
{"line": 1370, "text": "        )"}
{"line": 1371, "text": ""}
{"line": 1372, "text": "        print("}
{"line": 1373, "text": "            \"FIRST OBSERVED DETAIL:\","}
{"line": 1374, "text": "            error[\"detail\"],"}
{"line": 1375, "text": "        )"}
{"line": 1376, "text": ""}
{"line": 1377, "text": "        print("}
{"line": 1378, "text": "            \"SYSTEM-LEVEL CONDITION:\","}
{"line": 1379, "text": "            decision[\"decision\"],"}
{"line": 1380, "text": "        )"}
{"line": 1381, "text": ""}
{"line": 1382, "text": "        print("}
{"line": 1383, "text": "            \"TRAINING PERMISSION: DENIED\""}
{"line": 1384, "text": "        )"}
{"line": 1385, "text": ""}
{"line": 1386, "text": "        print("}
{"line": 1387, "text": "            \"REASON: Runtime contract is not verified.\""}
{"line": 1388, "text": "        )"}
{"line": 1389, "text": ""}
{"line": 1390, "text": "        state = {"}
{"line": 1391, "text": ""}
{"line": 1392, "text": "            \"timestamp\":"}
{"line": 1393, "text": "                time.time(),"}
{"line": 1394, "text": ""}
{"line": 1395, "text": "            \"duration\":"}
{"line": 1396, "text": "                time.time() - started,"}
{"line": 1397, "text": ""}
{"line": 1398, "text": "            \"model\":"}
{"line": 1399, "text": "                str(MODEL),"}
{"line": 1400, "text": ""}
{"line": 1401, "text": "            \"model_sha256\":"}
{"line": 1402, "text": "                hashlib.sha256("}
{"line": 1403, "text": "                    MODEL.read_bytes()"}
{"line": 1404, "text": "                ).hexdigest(),"}
{"line": 1405, "text": ""}
{"line": 1406, "text": "            \"runtime_probe\":"}
{"line": 1407, "text": "                runtime.as_dict(),"}
{"line": 1408, "text": ""}
{"line": 1409, "text": "            \"error\":"}
{"line": 1410, "text": "                error,"}
{"line": 1411, "text": ""}
{"line": 1412, "text": "            \"decision\":"}
{"line": 1413, "text": "                decision,"}
{"line": 1414, "text": ""}
{"line": 1415, "text": "            \"plan\":"}
{"line": 1416, "text": "                plan,"}
{"line": 1417, "text": "        }"}
{"line": 1418, "text": ""}
{"line": 1419, "text": "        STATE_FILE.write_text("}
{"line": 1420, "text": "            json.dumps("}
{"line": 1421, "text": "                state,"}
{"line": 1422, "text": "                indent=2,"}
{"line": 1423, "text": "                ensure_ascii=False,"}
{"line": 1424, "text": "            ),"}
{"line": 1425, "text": "            encoding=\"utf-8\","}
{"line": 1426, "text": "        )"}
{"line": 1427, "text": ""}
{"line": 1428, "text": "        self.terminal.record({"}
{"line": 1429, "text": "            \"timestamp\":"}
{"line": 1430, "text": "                time.time(),"}
{"line": 1431, "text": ""}
{"line": 1432, "text": "            \"type\":"}
{"line": 1433, "text": "                \"autonomous_forensic_cycle\","}
{"line": 1434, "text": ""}
{"line": 1435, "text": "            \"error\":"}
{"line": 1436, "text": "                error,"}
{"line": 1437, "text": ""}
{"line": 1438, "text": "            \"decision\":"}
{"line": 1439, "text": "                decision,"}
{"line": 1440, "text": ""}
{"line": 1441, "text": "            \"state_file\":"}
{"line": 1442, "text": "                str(STATE_FILE),"}
{"line": 1443, "text": "        })"}
{"line": 1444, "text": ""}
{"line": 1445, "text": "        print()"}
{"line": 1446, "text": "        print(\"=\" * 80)"}
{"line": 1447, "text": "        print(\"8. MACHINE STATE\")"}
{"line": 1448, "text": "        print(\"=\" * 80)"}
{"line": 1449, "text": ""}
{"line": 1450, "text": "        print("}
{"line": 1451, "text": "            \"STATE:\","}
{"line": 1452, "text": "            STATE_FILE,"}
{"line": 1453, "text": "        )"}
{"line": 1454, "text": ""}
