{"line": 40, "text": "    \"tiny\":   dict(D=64,  H=4, L=3, T=64, lr=1e-3),"}
{"line": 41, "text": "    \"small\":  dict(D=128, H=4, L=4, T=64, lr=5e-4),"}
{"line": 42, "text": "    \"medium\": dict(D=256, H=8, L=6, T=96, lr=3e-4),"}
{"line": 43, "text": "}"}
{"line": 44, "text": ""}
{"line": 45, "text": "cfg = PRESETS[PRESET]"}
{"line": 46, "text": ""}
{"line": 47, "text": "D = cfg[\"D\"]"}
{"line": 48, "text": "H = cfg[\"H\"]"}
{"line": 49, "text": "L = cfg[\"L\"]"}
{"line": 50, "text": "T = cfg[\"T\"]"}
{"line": 51, "text": "LR = cfg[\"lr\"]"}
{"line": 52, "text": ""}
{"line": 53, "text": "if D % H != 0:"}
{"line": 54, "text": "    raise ValueError(\"D must divide evenly by H\")"}
{"line": 55, "text": ""}
{"line": 56, "text": "DH = D // H"}
{"line": 57, "text": ""}
{"line": 58, "text": "BATCH = 4"}
{"line": 59, "text": "MAX_ITERS = 2000"}
{"line": 60, "text": "EVAL_EVERY = 25"}
{"line": 61, "text": "SEED = 42"}
{"line": 62, "text": ""}
{"line": 63, "text": "BETA1 = 0.9"}
{"line": 64, "text": "BETA2 = 0.999"}
{"line": 65, "text": "EPS = 1e-8"}
{"line": 66, "text": "WEIGHT_DECAY = 1e-4"}
{"line": 67, "text": "MAX_GRAD_NORM = 1.0"}
{"line": 68, "text": ""}
{"line": 69, "text": "np.random.seed(SEED)"}
{"line": 70, "text": "random.seed(SEED)"}
{"line": 71, "text": ""}
{"line": 72, "text": "# ============================================================"}
{"line": 73, "text": "# UTILS"}
{"line": 74, "text": "# ============================================================"}
{"line": 75, "text": ""}
{"line": 76, "text": "def zeros(*shape):"}
{"line": 77, "text": "    return np.zeros(shape, dtype=np.float32)"}
{"line": 78, "text": ""}
{"line": 79, "text": ""}
{"line": 80, "text": "def randn(*shape, scale=0.02):"}
{"line": 81, "text": "    return ("}
{"line": 82, "text": "        np.random.randn(*shape).astype(np.float32) * scale"}
{"line": 83, "text": "    )"}
{"line": 84, "text": ""}
{"line": 85, "text": ""}
{"line": 86, "text": "def check_finite(name, x):"}
{"line": 87, "text": "    if not np.all(np.isfinite(x)):"}
{"line": 88, "text": "        bad = np.size(x) - np.isfinite(x).sum()"}
{"line": 89, "text": "        raise FloatingPointError("}
{"line": 90, "text": "            f\"[NONFINITE] {name}: {bad} non-finite values\""}
{"line": 91, "text": "        )"}
{"line": 92, "text": ""}
{"line": 93, "text": ""}
{"line": 94, "text": "# ============================================================"}
{"line": 95, "text": "# RoPE"}
{"line": 96, "text": "# ============================================================"}
{"line": 97, "text": ""}
{"line": 98, "text": "def precompute_rope(dim, end, theta=10000.0):"}
{"line": 99, "text": "    if dim % 2 != 0:"}
{"line": 100, "text": "        raise ValueError(\"RoPE head dimension must be even\")"}
{"line": 101, "text": ""}
{"line": 102, "text": "    inv_freq = 1.0 / ("}
{"line": 103, "text": "        theta ** ("}
{"line": 104, "text": "            np.arange(0, dim, 2, dtype=np.float32) / dim"}
{"line": 105, "text": "        )"}
{"line": 106, "text": "    )"}
{"line": 107, "text": ""}
{"line": 108, "text": "    positions = np.arange(end, dtype=np.float32)"}
{"line": 109, "text": ""}
{"line": 110, "text": "    angles = np.outer(positions, inv_freq)"}
{"line": 111, "text": ""}
{"line": 112, "text": "    cos = np.cos(angles).astype(np.float32)"}
{"line": 113, "text": "    sin = np.sin(angles).astype(np.float32)"}
{"line": 114, "text": ""}
{"line": 115, "text": "    return cos, sin"}
{"line": 116, "text": ""}
{"line": 117, "text": ""}
{"line": 118, "text": "def rope_rotate(x, cos, sin):"}
{"line": 119, "text": "    \"\"\""}
{"line": 120, "text": "    x: (B, H, T, DH)"}
{"line": 121, "text": "    cos/sin: (T, DH/2)"}
{"line": 122, "text": "    \"\"\""}
{"line": 123, "text": ""}
{"line": 124, "text": "    B, heads, seq, dim = x.shape"}
{"line": 125, "text": ""}
{"line": 126, "text": "    x_pair = x.reshape(B, heads, seq, dim // 2, 2)"}
{"line": 127, "text": ""}
{"line": 128, "text": "    even = x_pair[..., 0]"}
{"line": 129, "text": "    odd = x_pair[..., 1]"}
{"line": 130, "text": ""}
{"line": 131, "text": "    c = cos[:seq][None, None, :, :]"}
{"line": 132, "text": "    s = sin[:seq][None, None, :, :]"}
{"line": 133, "text": ""}
{"line": 134, "text": "    out_even = even * c - odd * s"}
{"line": 135, "text": "    out_odd = even * s + odd * c"}
{"line": 136, "text": ""}
{"line": 137, "text": "    out = np.stack("}
{"line": 138, "text": "        [out_even, out_odd],"}
{"line": 139, "text": "        axis=-1"}
{"line": 140, "text": "    )"}
{"line": 141, "text": ""}
{"line": 142, "text": "    return out.reshape(B, heads, seq, dim).astype(np.float32)"}
{"line": 143, "text": ""}
{"line": 144, "text": ""}
{"line": 145, "text": "def rope_inverse(grad, cos, sin):"}
{"line": 146, "text": "    \"\"\""}
{"line": 147, "text": "    Exact backward through orthogonal RoPE rotation."}
{"line": 148, "text": "    Inverse rotation = rotation by -angle."}
{"line": 149, "text": "    \"\"\""}
{"line": 150, "text": ""}
{"line": 151, "text": "    B, heads, seq, dim = grad.shape"}
{"line": 152, "text": ""}
{"line": 153, "text": "    g_pair = grad.reshape("}
{"line": 154, "text": "        B, heads, seq, dim // 2, 2"}
{"line": 155, "text": "    )"}
{"line": 156, "text": ""}
{"line": 157, "text": "    even = g_pair[..., 0]"}
{"line": 158, "text": "    odd = g_pair[..., 1]"}
{"line": 159, "text": ""}
{"line": 160, "text": "    c = cos[:seq][None, None, :, :]"}
{"line": 161, "text": "    s = sin[:seq][None, None, :, :]"}
{"line": 162, "text": ""}
{"line": 163, "text": "    out_even = even * c + odd * s"}
{"line": 164, "text": "    out_odd = -even * s + odd * c"}
{"line": 165, "text": ""}
{"line": 166, "text": "    out = np.stack("}
{"line": 167, "text": "        [out_even, out_odd],"}
{"line": 168, "text": "        axis=-1"}
{"line": 169, "text": "    )"}
{"line": 170, "text": ""}
{"line": 171, "text": "    return out.reshape(B, heads, seq, dim).astype(np.float32)"}
{"line": 172, "text": ""}
{"line": 173, "text": ""}
{"line": 174, "text": "# ============================================================"}
{"line": 175, "text": "# DATA"}
{"line": 176, "text": "# ============================================================"}
{"line": 177, "text": ""}
{"line": 178, "text": "VALIDATION_TEXT = None"}
{"line": 179, "text": ""}
{"line": 180, "text": ""}
{"line": 181, "text": "def load_text():"}
{"line": 182, "text": "    \"\"\""}
{"line": 183, "text": "    BLOOM V2 REAL DATA LOADER"}
{"line": 184, "text": ""}
{"line": 185, "text": "    Training:"}
{"line": 186, "text": "        bloom_train_v2.txt"}
{"line": 187, "text": ""}
{"line": 188, "text": "    Validation:"}
{"line": 189, "text": "        bloom_valid_v2.txt"}
{"line": 190, "text": ""}
{"line": 191, "text": "    The validated V2 corpora are loaded directly."}
{"line": 192, "text": "    No fabricated text is introduced."}
{"line": 193, "text": "    No archive material is silently mixed into training."}
{"line": 194, "text": "    \"\"\""}
{"line": 195, "text": ""}
{"line": 196, "text": "    train_path = BLOOM_DIR / \"bloom_train_v2.txt\""}
{"line": 197, "text": "    valid_path = BLOOM_DIR / \"bloom_valid_v2.txt\""}
{"line": 198, "text": ""}
{"line": 199, "text": "    if not train_path.exists():"}
{"line": 200, "text": "        raise RuntimeError("}
{"line": 201, "text": "            f\"Missing validated V2 training corpus: {train_path}\""}
{"line": 202, "text": "        )"}
{"line": 203, "text": ""}
{"line": 204, "text": "    if not valid_path.exists():"}
{"line": 205, "text": "        raise RuntimeError("}
{"line": 206, "text": "            f\"Missing validated V2 validation corpus: {valid_path}\""}
{"line": 207, "text": "        )"}
{"line": 208, "text": ""}
{"line": 209, "text": "    train_text = train_path.read_text("}
{"line": 210, "text": "        encoding=\"utf-8\","}
{"line": 211, "text": "        errors=\"ignore\""}
{"line": 212, "text": "    )"}
{"line": 213, "text": ""}
{"line": 214, "text": "    valid_text = valid_path.read_text("}
{"line": 215, "text": "        encoding=\"utf-8\","}
{"line": 216, "text": "        errors=\"ignore\""}
{"line": 217, "text": "    )"}
{"line": 218, "text": ""}
{"line": 219, "text": "    if len(train_text.strip()) < 100:"}
{"line": 220, "text": "        raise RuntimeError("}
{"line": 221, "text": "            \"Validated V2 training corpus is too small.\""}
{"line": 222, "text": "        )"}
{"line": 223, "text": ""}
{"line": 224, "text": "    if len(valid_text.strip()) < 20:"}
{"line": 225, "text": "        raise RuntimeError("}
{"line": 226, "text": "            \"Validated V2 validation corpus is too small.\""}
{"line": 227, "text": "        )"}
{"line": 228, "text": ""}
{"line": 229, "text": "    # Keep validation available to the runtime without contaminating"}
{"line": 230, "text": "    # the training stream."}
{"line": 231, "text": "    global VALIDATION_TEXT"}
{"line": 232, "text": "    VALIDATION_TEXT = valid_text"}
{"line": 233, "text": ""}
{"line": 234, "text": "    # The existing GPT runtime expects load_text() to return the"}
{"line": 235, "text": "    # training text and an archive count."}
{"line": 236, "text": "    #"}
{"line": 237, "text": "    # archive_count is retained for compatibility."}
{"line": 238, "text": "    archive_count = 0"}
{"line": 239, "text": ""}
{"line": 240, "text": "    return train_text, archive_count"}
{"line": 241, "text": "def get_batch():"}
{"line": 242, "text": ""}
{"line": 243, "text": "    max_start = len(data) - T - 1"}
{"line": 244, "text": ""}
{"line": 245, "text": "    ix = np.random.randint("}
{"line": 246, "text": "        0,"}
{"line": 247, "text": "        max_start,"}
{"line": 248, "text": "        size=BATCH"}
{"line": 249, "text": "    )"}
{"line": 250, "text": ""}
{"line": 251, "text": "    x = np.stack("}
{"line": 252, "text": "        [data[i:i + T] for i in ix]"}
{"line": 253, "text": "    )"}
{"line": 254, "text": ""}
{"line": 255, "text": "    y = np.stack("}
{"line": 256, "text": "        [data[i + 1:i + T + 1] for i in ix]"}
{"line": 257, "text": "    )"}
{"line": 258, "text": ""}
{"line": 259, "text": "    return x, y"}
{"line": 260, "text": ""}
{"line": 261, "text": ""}
{"line": 262, "text": "# ============================================================"}
{"line": 263, "text": "# LINEAR"}
{"line": 264, "text": "# ============================================================"}
{"line": 265, "text": ""}
{"line": 266, "text": "class Linear:"}
{"line": 267, "text": ""}
{"line": 268, "text": "    def __init__(self, nin, nout, bias=True):"}
{"line": 269, "text": ""}
{"line": 270, "text": "        self.W = randn(nin, nout)"}
{"line": 271, "text": ""}
{"line": 272, "text": "        self.b = ("}
{"line": 273, "text": "            zeros(nout)"}
{"line": 274, "text": "            if bias"}
{"line": 275, "text": "            else None"}
{"line": 276, "text": "        )"}
{"line": 277, "text": ""}
{"line": 278, "text": "        self.dW = zeros(nin, nout)"}
{"line": 279, "text": ""}
{"line": 280, "text": "        self.db = ("}
{"line": 281, "text": "            zeros(nout)"}
{"line": 282, "text": "            if bias"}
{"line": 283, "text": "            else None"}
{"line": 284, "text": "        )"}
{"line": 285, "text": ""}
{"line": 286, "text": "        self.x = None"}
{"line": 287, "text": ""}
{"line": 288, "text": ""}
{"line": 289, "text": "    def forward(self, x):"}
{"line": 290, "text": ""}
{"line": 291, "text": "        self.x = x"}
{"line": 292, "text": ""}
{"line": 293, "text": "        out = x @ self.W"}
{"line": 294, "text": ""}
{"line": 295, "text": "        if self.b is not None:"}
{"line": 296, "text": "            out = out + self.b"}
{"line": 297, "text": ""}
{"line": 298, "text": "        return out.astype(np.float32)"}
{"line": 299, "text": ""}
{"line": 300, "text": ""}
{"line": 301, "text": "    def backward(self, dout):"}
{"line": 302, "text": ""}
{"line": 303, "text": "        x2 = self.x.reshape("}
{"line": 304, "text": "            -1,"}
{"line": 305, "text": "            self.x.shape[-1]"}
{"line": 306, "text": "        )"}
{"line": 307, "text": ""}
{"line": 308, "text": "        d2 = dout.reshape("}
{"line": 309, "text": "            -1,"}
{"line": 310, "text": "            dout.shape[-1]"}
{"line": 311, "text": "        )"}
{"line": 312, "text": ""}
{"line": 313, "text": "        self.dW[:] = x2.T @ d2"}
{"line": 314, "text": ""}
{"line": 315, "text": "        if self.b is not None:"}
{"line": 316, "text": "            self.db[:] = d2.sum("}
{"line": 317, "text": "                axis=0"}
{"line": 318, "text": "            )"}
{"line": 319, "text": ""}
{"line": 320, "text": "        return ("}
{"line": 321, "text": "            dout @ self.W.T"}
{"line": 322, "text": "        ).astype(np.float32)"}
{"line": 323, "text": ""}
{"line": 324, "text": ""}
{"line": 325, "text": "# ============================================================"}
{"line": 326, "text": "# LAYER NORM"}
{"line": 327, "text": "# ============================================================"}
{"line": 328, "text": ""}
{"line": 329, "text": "class LayerNorm:"}
{"line": 330, "text": ""}
{"line": 331, "text": "    def __init__(self, dim, eps=1e-5):"}
{"line": 332, "text": ""}
{"line": 333, "text": "        self.g = np.ones("}
{"line": 334, "text": "            dim,"}
{"line": 335, "text": "            dtype=np.float32"}
{"line": 336, "text": "        )"}
{"line": 337, "text": ""}
{"line": 338, "text": "        self.b = zeros(dim)"}
{"line": 339, "text": ""}
{"line": 340, "text": "        self.eps = eps"}
{"line": 341, "text": ""}
{"line": 342, "text": "        self.xhat = None"}
{"line": 343, "text": "        self.invstd = None"}
{"line": 344, "text": ""}
{"line": 345, "text": "        self.dg = zeros(dim)"}
{"line": 346, "text": "        self.db = zeros(dim)"}
{"line": 347, "text": ""}
{"line": 348, "text": ""}
{"line": 349, "text": "    def forward(self, x):"}
{"line": 350, "text": ""}
{"line": 351, "text": "        mean = x.mean("}
{"line": 352, "text": "            axis=-1,"}
{"line": 353, "text": "            keepdims=True"}
{"line": 354, "text": "        )"}
{"line": 355, "text": ""}
{"line": 356, "text": "        var = x.var("}
{"line": 357, "text": "            axis=-1,"}
{"line": 358, "text": "            keepdims=True"}
{"line": 359, "text": "        )"}
{"line": 360, "text": ""}
{"line": 361, "text": "        self.invstd = 1.0 / np.sqrt("}
{"line": 362, "text": "            var + self.eps"}
{"line": 363, "text": "        )"}
{"line": 364, "text": ""}
{"line": 365, "text": "        self.xhat = ("}
{"line": 366, "text": "            x - mean"}
{"line": 367, "text": "        ) * self.invstd"}
{"line": 368, "text": ""}
{"line": 369, "text": "        return ("}
{"line": 370, "text": "            self.xhat * self.g + self.b"}
{"line": 371, "text": "        ).astype(np.float32)"}
{"line": 372, "text": ""}
{"line": 373, "text": ""}
{"line": 374, "text": "    def backward(self, dout):"}
{"line": 375, "text": ""}
{"line": 376, "text": "        axes = tuple("}
{"line": 377, "text": "            range(dout.ndim - 1)"}
{"line": 378, "text": "        )"}
{"line": 379, "text": ""}
{"line": 380, "text": "        self.dg[:] = ("}
{"line": 381, "text": "            dout * self.xhat"}
{"line": 382, "text": "        ).sum(axis=axes)"}
{"line": 383, "text": ""}
{"line": 384, "text": "        self.db[:] = dout.sum(axis=axes)"}
{"line": 385, "text": ""}
{"line": 386, "text": "        N = dout.shape[-1]"}
{"line": 387, "text": ""}
{"line": 388, "text": "        dxhat = dout * self.g"}
{"line": 389, "text": ""}
{"line": 390, "text": "        dx = ("}
{"line": 391, "text": "            1.0 / N"}
{"line": 392, "text": "        ) * self.invstd * ("}
{"line": 393, "text": "            N * dxhat"}
{"line": 394, "text": "            - dxhat.sum("}
{"line": 395, "text": "                axis=-1,"}
{"line": 396, "text": "                keepdims=True"}
{"line": 397, "text": "            )"}
{"line": 398, "text": "            - self.xhat * ("}
{"line": 399, "text": "                dxhat * self.xhat"}
{"line": 400, "text": "            ).sum("}
{"line": 401, "text": "                axis=-1,"}
{"line": 402, "text": "                keepdims=True"}
{"line": 403, "text": "            )"}
{"line": 404, "text": "        )"}
{"line": 405, "text": ""}
{"line": 406, "text": "        return dx.astype(np.float32)"}
{"line": 407, "text": ""}
{"line": 408, "text": ""}
{"line": 409, "text": "# ============================================================"}
{"line": 410, "text": "# CAUSAL SELF ATTENTION"}
{"line": 411, "text": "# ============================================================"}
{"line": 412, "text": ""}
{"line": 413, "text": "class CausalSelfAttention:"}
{"line": 414, "text": ""}
{"line": 415, "text": "    def __init__(self, D, H, rope_cos, rope_sin):"}
{"line": 416, "text": ""}
{"line": 417, "text": "        self.H = H"}
{"line": 418, "text": "        self.DH = D // H"}
{"line": 419, "text": "        self.scale = 1.0 / math.sqrt(self.DH)"}
{"line": 420, "text": ""}
{"line": 421, "text": "        self.qkv = Linear(D, 3 * D)"}
{"line": 422, "text": "        self.proj = Linear(D, D)"}
{"line": 423, "text": ""}
{"line": 424, "text": "        self.rope_cos = rope_cos"}
{"line": 425, "text": "        self.rope_sin = rope_sin"}
{"line": 426, "text": ""}
{"line": 427, "text": "        self.q = None"}
{"line": 428, "text": "        self.k = None"}
{"line": 429, "text": "        self.v = None"}
{"line": 430, "text": "        self.att = None"}
{"line": 431, "text": ""}
{"line": 432, "text": ""}
{"line": 433, "text": "    def forward(self, x):"}
{"line": 434, "text": ""}
{"line": 435, "text": "        B, seq, C = x.shape"}
{"line": 436, "text": ""}
{"line": 437, "text": "        qkv = self.qkv.forward(x)"}
{"line": 438, "text": ""}
{"line": 439, "text": "        q, k, v = np.split("}
{"line": 440, "text": "            qkv,"}
{"line": 441, "text": "            3,"}
{"line": 442, "text": "            axis=-1"}
{"line": 443, "text": "        )"}
{"line": 444, "text": ""}
{"line": 445, "text": "        q = q.reshape("}
{"line": 446, "text": "            B, seq, self.H, self.DH"}
{"line": 447, "text": "        ).transpose(0, 2, 1, 3)"}
{"line": 448, "text": ""}
{"line": 449, "text": "        k = k.reshape("}
{"line": 450, "text": "            B, seq, self.H, self.DH"}
{"line": 451, "text": "        ).transpose(0, 2, 1, 3)"}
{"line": 452, "text": ""}
{"line": 453, "text": "        v = v.reshape("}
{"line": 454, "text": "            B, seq, self.H, self.DH"}
{"line": 455, "text": "        ).transpose(0, 2, 1, 3)"}
{"line": 456, "text": ""}
{"line": 457, "text": "        # RoPE"}
{"line": 458, "text": "        q = rope_rotate("}
{"line": 459, "text": "            q,"}
{"line": 460, "text": "            self.rope_cos,"}
{"line": 461, "text": "            self.rope_sin"}
{"line": 462, "text": "        )"}
{"line": 463, "text": ""}
{"line": 464, "text": "        k = rope_rotate("}
{"line": 465, "text": "            k,"}
{"line": 466, "text": "            self.rope_cos,"}
{"line": 467, "text": "            self.rope_sin"}
{"line": 468, "text": "        )"}
{"line": 469, "text": ""}
{"line": 470, "text": "        scores = ("}
{"line": 471, "text": "            q @ k.transpose(0, 1, 3, 2)"}
{"line": 472, "text": "        ) * self.scale"}
{"line": 473, "text": ""}
{"line": 474, "text": "        mask = np.triu("}
{"line": 475, "text": "            np.full("}
{"line": 476, "text": "                (seq, seq),"}
{"line": 477, "text": "                -1e9,"}
{"line": 478, "text": "                dtype=np.float32"}
{"line": 479, "text": "            ),"}
{"line": 480, "text": "            k=1"}
{"line": 481, "text": "        )"}
{"line": 482, "text": ""}
{"line": 483, "text": "        scores = scores + mask"}
{"line": 484, "text": ""}
{"line": 485, "text": "        # Stable softmax"}
{"line": 486, "text": "        scores = scores - scores.max("}
{"line": 487, "text": "            axis=-1,"}
{"line": 488, "text": "            keepdims=True"}
{"line": 489, "text": "        )"}
{"line": 490, "text": ""}
{"line": 491, "text": "        exp_scores = np.exp("}
{"line": 492, "text": "            np.clip(scores, -80.0, 0.0)"}
{"line": 493, "text": "        )"}
{"line": 494, "text": ""}
{"line": 495, "text": "        att = exp_scores / ("}
{"line": 496, "text": "            exp_scores.sum("}
{"line": 497, "text": "                axis=-1,"}
{"line": 498, "text": "                keepdims=True"}
{"line": 499, "text": "            ) + 1e-9"}
{"line": 500, "text": "        )"}
{"line": 501, "text": ""}
{"line": 502, "text": "        y = att @ v"}
{"line": 503, "text": ""}
{"line": 504, "text": "        y = y.transpose("}
{"line": 505, "text": "            0, 2, 1, 3"}
{"line": 506, "text": "        ).reshape(B, seq, C)"}
{"line": 507, "text": ""}
{"line": 508, "text": "        self.q = q"}
{"line": 509, "text": "        self.k = k"}
{"line": 510, "text": "        self.v = v"}
{"line": 511, "text": "        self.att = att"}
{"line": 512, "text": ""}
{"line": 513, "text": "        return self.proj.forward(y)"}
{"line": 514, "text": ""}
{"line": 515, "text": ""}
{"line": 516, "text": "    def backward(self, dout):"}
{"line": 517, "text": ""}
{"line": 518, "text": "        B, seq, C = dout.shape"}
{"line": 519, "text": ""}
{"line": 520, "text": "        dy = self.proj.backward(dout)"}
{"line": 521, "text": ""}
{"line": 522, "text": "        dy = dy.reshape("}
{"line": 523, "text": "            B,"}
{"line": 524, "text": "            seq,"}
{"line": 525, "text": "            self.H,"}
{"line": 526, "text": "            self.DH"}
{"line": 527, "text": "        ).transpose(0, 2, 1, 3)"}
{"line": 528, "text": ""}
{"line": 529, "text": "        q = self.q"}
{"line": 530, "text": "        k = self.k"}
{"line": 531, "text": "        v = self.v"}
{"line": 532, "text": "        att = self.att"}
{"line": 533, "text": ""}
{"line": 534, "text": "        # y = att @ v"}
{"line": 535, "text": "        datt = ("}
{"line": 536, "text": "            dy @ v.transpose(0, 1, 3, 2)"}
{"line": 537, "text": "        )"}
{"line": 538, "text": ""}
{"line": 539, "text": "        dv = ("}
{"line": 540, "text": "            att.transpose(0, 1, 3, 2)"}
{"line": 541, "text": "            @ dy"}
{"line": 542, "text": "        )"}
{"line": 543, "text": ""}
{"line": 544, "text": "        # Stable softmax backward"}
{"line": 545, "text": "        dscore = att * ("}
{"line": 546, "text": "            datt"}
{"line": 547, "text": "            - ("}
{"line": 548, "text": "                datt * att"}
{"line": 549, "text": "            ).sum("}
{"line": 550, "text": "                axis=-1,"}
{"line": 551, "text": "                keepdims=True"}
{"line": 552, "text": "            )"}
{"line": 553, "text": "        )"}
{"line": 554, "text": ""}
{"line": 555, "text": "        # scores = (q @ k.T) * scale"}
{"line": 556, "text": "        dq = ("}
{"line": 557, "text": "            dscore @ k"}
{"line": 558, "text": "        ) * self.scale"}
{"line": 559, "text": ""}
{"line": 560, "text": "        dk = ("}
{"line": 561, "text": "            dscore.transpose(0, 1, 3, 2)"}
{"line": 562, "text": "            @ q"}
{"line": 563, "text": "        ) * self.scale"}
{"line": 564, "text": ""}
{"line": 565, "text": "        # Exact inverse RoPE"}
{"line": 566, "text": "        dq = rope_inverse("}
{"line": 567, "text": "            dq,"}
{"line": 568, "text": "            self.rope_cos,"}
{"line": 569, "text": "            self.rope_sin"}
{"line": 570, "text": "        )"}
{"line": 571, "text": ""}
{"line": 572, "text": "        dk = rope_inverse("}
{"line": 573, "text": "            dk,"}
{"line": 574, "text": "            self.rope_cos,"}
{"line": 575, "text": "            self.rope_sin"}
{"line": 576, "text": "        )"}
{"line": 577, "text": ""}
{"line": 578, "text": "        dq = dq.transpose("}
{"line": 579, "text": "            0, 2, 1, 3"}
{"line": 580, "text": "        ).reshape(B, seq, C)"}
{"line": 581, "text": ""}
{"line": 582, "text": "        dk = dk.transpose("}
{"line": 583, "text": "            0, 2, 1, 3"}
{"line": 584, "text": "        ).reshape(B, seq, C)"}
{"line": 585, "text": ""}
{"line": 586, "text": "        dv = dv.transpose("}
{"line": 587, "text": "            0, 2, 1, 3"}
{"line": 588, "text": "        ).reshape(B, seq, C)"}
{"line": 589, "text": ""}
{"line": 590, "text": "        return self.qkv.backward("}
{"line": 591, "text": "            np.concatenate("}
{"line": 592, "text": "                [dq, dk, dv],"}
{"line": 593, "text": "                axis=-1"}
{"line": 594, "text": "            )"}
{"line": 595, "text": "        )"}
{"line": 596, "text": ""}
{"line": 597, "text": ""}
{"line": 598, "text": "# ============================================================"}
{"line": 599, "text": "# MLP"}
{"line": 600, "text": "# ============================================================"}
{"line": 601, "text": ""}
{"line": 602, "text": "class MLP:"}
{"line": 603, "text": ""}
{"line": 604, "text": "    def __init__(self, D):"}
{"line": 605, "text": ""}
{"line": 606, "text": "        self.fc1 = Linear(D, 4 * D)"}
{"line": 607, "text": "        self.fc2 = Linear(4 * D, D)"}
{"line": 608, "text": ""}
{"line": 609, "text": "        self.h = None"}
{"line": 610, "text": ""}
{"line": 611, "text": ""}
{"line": 612, "text": "    def forward(self, x):"}
{"line": 613, "text": ""}
{"line": 614, "text": "        h = self.fc1.forward(x)"}
{"line": 615, "text": ""}
{"line": 616, "text": "        # GELU approximation"}
{"line": 617, "text": "        self.h = h"}
{"line": 618, "text": ""}
{"line": 619, "text": "        c = np.sqrt("}
{"line": 620, "text": "            2.0 / np.pi"}
{"line": 621, "text": "        )"}
{"line": 622, "text": ""}
{"line": 623, "text": "        u = c * ("}
{"line": 624, "text": "            h + 0.044715 * h ** 3"}
{"line": 625, "text": "        )"}
{"line": 626, "text": ""}
{"line": 627, "text": "        return self.fc2.forward("}
{"line": 628, "text": "            0.5 * h * ("}
{"line": 629, "text": "                1.0 + np.tanh(u)"}
{"line": 630, "text": "            )"}
{"line": 631, "text": "        )"}
{"line": 632, "text": ""}
{"line": 633, "text": ""}
{"line": 634, "text": "    def backward(self, dout):"}
{"line": 635, "text": ""}
{"line": 636, "text": "        dh = self.fc2.backward(dout)"}
{"line": 637, "text": ""}
{"line": 638, "text": "        h = self.h"}
{"line": 639, "text": ""}
{"line": 640, "text": "        c = np.sqrt("}
{"line": 641, "text": "            2.0 / np.pi"}
{"line": 642, "text": "        )"}
{"line": 643, "text": ""}
{"line": 644, "text": "        u = c * ("}
{"line": 645, "text": "            h + 0.044715 * h ** 3"}
{"line": 646, "text": "        )"}
{"line": 647, "text": ""}
{"line": 648, "text": "        tanh_u = np.tanh(u)"}
{"line": 649, "text": ""}
{"line": 650, "text": "        du = c * ("}
{"line": 651, "text": "            1.0 + 3.0 * 0.044715 * h ** 2"}
{"line": 652, "text": "        )"}
{"line": 653, "text": ""}
{"line": 654, "text": "        gelu_grad = ("}
{"line": 655, "text": "            0.5 * ("}
{"line": 656, "text": "                1.0 + tanh_u"}
{"line": 657, "text": "            )"}
{"line": 658, "text": "            + 0.5 * h * ("}
{"line": 659, "text": "                1.0 - tanh_u ** 2"}
{"line": 660, "text": "            ) * du"}
{"line": 661, "text": "        )"}
{"line": 662, "text": ""}
{"line": 663, "text": "        return self.fc1.backward("}
{"line": 664, "text": "            dh * gelu_grad"}
{"line": 665, "text": "        )"}
{"line": 666, "text": ""}
{"line": 667, "text": ""}
{"line": 668, "text": "# ============================================================"}
{"line": 669, "text": "# BLOCK"}
{"line": 670, "text": "# ============================================================"}
{"line": 671, "text": ""}
{"line": 672, "text": "class Block:"}
{"line": 673, "text": ""}
{"line": 674, "text": "    def __init__("}
{"line": 675, "text": "        self,"}
{"line": 676, "text": "        D,"}
{"line": 677, "text": "        H,"}
{"line": 678, "text": "        rope_cos,"}
{"line": 679, "text": "        rope_sin"}
{"line": 680, "text": "    ):"}
{"line": 681, "text": ""}
{"line": 682, "text": "        self.ln1 = LayerNorm(D)"}
{"line": 683, "text": ""}
{"line": 684, "text": "        self.attn = CausalSelfAttention("}
{"line": 685, "text": "            D,"}
{"line": 686, "text": "            H,"}
{"line": 687, "text": "            rope_cos,"}
{"line": 688, "text": "            rope_sin"}
{"line": 689, "text": "        )"}
{"line": 690, "text": ""}
{"line": 691, "text": "        self.ln2 = LayerNorm(D)"}
{"line": 692, "text": ""}
{"line": 693, "text": "        self.mlp = MLP(D)"}
{"line": 694, "text": ""}
{"line": 695, "text": ""}
{"line": 696, "text": "    def forward(self, x):"}
{"line": 697, "text": ""}
{"line": 698, "text": "        x = x + self.attn.forward("}
{"line": 699, "text": "            self.ln1.forward(x)"}
{"line": 700, "text": "        )"}
{"line": 701, "text": ""}
{"line": 702, "text": "        x = x + self.mlp.forward("}
{"line": 703, "text": "            self.ln2.forward(x)"}
{"line": 704, "text": "        )"}
{"line": 705, "text": ""}
{"line": 706, "text": "        return x"}
{"line": 707, "text": ""}
{"line": 708, "text": ""}
{"line": 709, "text": "    def backward(self, dout):"}
{"line": 710, "text": ""}
{"line": 711, "text": "        d_mlp = self.mlp.backward(dout)"}
{"line": 712, "text": ""}
{"line": 713, "text": "        d_ln2 = self.ln2.backward(d_mlp)"}
{"line": 714, "text": ""}
{"line": 715, "text": "        d_after_attn = dout + d_ln2"}
{"line": 716, "text": ""}
{"line": 717, "text": "        d_attn = self.attn.backward("}
{"line": 718, "text": "            d_after_attn"}
{"line": 719, "text": "        )"}
{"line": 720, "text": ""}
{"line": 721, "text": "        d_ln1 = self.ln1.backward(d_attn)"}
{"line": 722, "text": ""}
{"line": 723, "text": "        return d_after_attn + d_ln1"}
{"line": 724, "text": ""}
{"line": 725, "text": ""}
{"line": 726, "text": "# ============================================================"}
{"line": 727, "text": "# GPT"}
{"line": 728, "text": "# ============================================================"}
{"line": 729, "text": ""}
{"line": 730, "text": "class GPT:"}
{"line": 731, "text": ""}
{"line": 732, "text": "    def __init__(self, vs, D, H, L, T):"}
{"line": 733, "text": ""}
{"line": 734, "text": "        self.T = T"}
{"line": 735, "text": ""}
{"line": 736, "text": "        self.wte = randn(vs, D)"}
{"line": 737, "text": ""}
{"line": 738, "text": "        rope_cos, rope_sin = precompute_rope("}
{"line": 739, "text": "            D // H,"}
{"line": 740, "text": "            T"}
{"line": 741, "text": "        )"}
{"line": 742, "text": ""}
{"line": 743, "text": "        self.blocks = ["}
{"line": 744, "text": "            Block("}
{"line": 745, "text": "                D,"}
{"line": 746, "text": "                H,"}
{"line": 747, "text": "                rope_cos,"}
{"line": 748, "text": "                rope_sin"}
{"line": 749, "text": "            )"}
{"line": 750, "text": "            for _ in range(L)"}
{"line": 751, "text": "        ]"}
{"line": 752, "text": ""}
{"line": 753, "text": "        self.ln_f = LayerNorm(D)"}
{"line": 754, "text": ""}
{"line": 755, "text": "        self.lm_head = Linear("}
{"line": 756, "text": "            D,"}
{"line": 757, "text": "            vs,"}
{"line": 758, "text": "            bias=False"}
{"line": 759, "text": "        )"}
{"line": 760, "text": ""}
{"line": 761, "text": "        # True tied weights"}
{"line": 762, "text": "        self.lm_head.W = self.wte.T"}
{"line": 763, "text": ""}
{"line": 764, "text": "        self.idx = None"}
{"line": 765, "text": "        self.probs = None"}
{"line": 766, "text": "        self.targets = None"}
{"line": 767, "text": ""}
{"line": 768, "text": "        self.d_wte = zeros(vs, D)"}
{"line": 769, "text": ""}
{"line": 770, "text": ""}
{"line": 771, "text": "    def forward(self, idx, targets=None):"}
{"line": 772, "text": ""}
{"line": 773, "text": "        B, seq = idx.shape"}
{"line": 774, "text": ""}
{"line": 775, "text": "        if seq != self.T:"}
{"line": 776, "text": "            raise ValueError("}
{"line": 777, "text": "                f\"Expected context {self.T}, got {seq}\""}
{"line": 778, "text": "            )"}
{"line": 779, "text": ""}
{"line": 780, "text": "        self.idx = idx"}
{"line": 781, "text": ""}
{"line": 782, "text": "        x = self.wte[idx]"}
{"line": 783, "text": ""}
{"line": 784, "text": "        for block in self.blocks:"}
{"line": 785, "text": "            x = block.forward(x)"}
{"line": 786, "text": ""}
{"line": 787, "text": "        x = self.ln_f.forward(x)"}
{"line": 788, "text": ""}
{"line": 789, "text": "        logits = self.lm_head.forward(x)"}
{"line": 790, "text": ""}
{"line": 791, "text": "        loss = None"}
{"line": 792, "text": ""}
{"line": 793, "text": "        if targets is not None:"}
{"line": 794, "text": ""}
{"line": 795, "text": "            flat = logits.reshape("}
{"line": 796, "text": "                -1,"}
{"line": 797, "text": "                logits.shape[-1]"}
{"line": 798, "text": "            )"}
{"line": 799, "text": ""}
{"line": 800, "text": "            flat = flat - flat.max("}
{"line": 801, "text": "                axis=1,"}
{"line": 802, "text": "                keepdims=True"}
{"line": 803, "text": "            )"}
{"line": 804, "text": ""}
{"line": 805, "text": "            exp = np.exp("}
{"line": 806, "text": "                np.clip(flat, -80.0, 0.0)"}
{"line": 807, "text": "            )"}
{"line": 808, "text": ""}
{"line": 809, "text": "            probs = exp / ("}
{"line": 810, "text": "                exp.sum("}
{"line": 811, "text": "                    axis=1,"}
{"line": 812, "text": "                    keepdims=True"}
{"line": 813, "text": "                ) + 1e-9"}
{"line": 814, "text": "            )"}
{"line": 815, "text": ""}
{"line": 816, "text": "            target_flat = targets.reshape(-1)"}
{"line": 817, "text": ""}
{"line": 818, "text": "            loss = -np.log("}
{"line": 819, "text": "                probs["}
{"line": 820, "text": "                    np.arange(B * seq),"}
{"line": 821, "text": "                    target_flat"}
{"line": 822, "text": "                ] + 1e-9"}
{"line": 823, "text": "            ).mean()"}
{"line": 824, "text": ""}
{"line": 825, "text": "            self.probs = probs.reshape("}
{"line": 826, "text": "                B,"}
{"line": 827, "text": "                seq,"}
{"line": 828, "text": "                -1"}
{"line": 829, "text": "            )"}
{"line": 830, "text": ""}
{"line": 831, "text": "            self.targets = targets"}
{"line": 832, "text": ""}
{"line": 833, "text": "        return logits, float(loss) if loss is not None else None"}
{"line": 834, "text": ""}
{"line": 835, "text": ""}
{"line": 836, "text": "    def backward(self):"}
{"line": 837, "text": ""}
{"line": 838, "text": "        B, seq, V = self.probs.shape"}
{"line": 839, "text": ""}
{"line": 840, "text": "        dlogits = self.probs.copy()"}
{"line": 841, "text": ""}
{"line": 842, "text": "        dlogits.reshape("}
{"line": 843, "text": "            -1,"}
{"line": 844, "text": "            V"}
{"line": 845, "text": "        )["}
{"line": 846, "text": "            np.arange(B * seq),"}
{"line": 847, "text": "            self.targets.reshape(-1)"}
{"line": 848, "text": "        ] -= 1.0"}
{"line": 849, "text": ""}
{"line": 850, "text": "        dlogits /= ("}
{"line": 851, "text": "            B * seq"}
{"line": 852, "text": "        )"}
{"line": 853, "text": ""}
{"line": 854, "text": "        dx = self.lm_head.backward("}
{"line": 855, "text": "            dlogits"}
{"line": 856, "text": "        )"}
{"line": 857, "text": ""}
{"line": 858, "text": "        dx = self.ln_f.backward(dx)"}
{"line": 859, "text": ""}
{"line": 860, "text": "        for block in reversed(self.blocks):"}
{"line": 861, "text": "            dx = block.backward(dx)"}
{"line": 862, "text": ""}
{"line": 863, "text": "        d_wte = zeros(*self.wte.shape)"}
{"line": 864, "text": ""}
{"line": 865, "text": "        np.add.at("}
{"line": 866, "text": "            d_wte,"}
{"line": 867, "text": "            self.idx.reshape(-1),"}
{"line": 868, "text": "            dx.reshape(-1, dx.shape[-1])"}
{"line": 869, "text": "        )"}
{"line": 870, "text": ""}
{"line": 871, "text": "        # Output head gradient belongs to tied embedding matrix."}
{"line": 872, "text": "        d_wte += self.lm_head.dW.T"}
{"line": 873, "text": ""}
{"line": 874, "text": "        self.d_wte[:] = d_wte"}
{"line": 875, "text": ""}
{"line": 876, "text": ""}
{"line": 877, "text": "# ============================================================"}
{"line": 878, "text": "# PARAMETER / GRADIENT COLLECTION"}
{"line": 879, "text": "# ============================================================"}
{"line": 880, "text": ""}
{"line": 881, "text": "def collect_params():"}
{"line": 882, "text": ""}
{"line": 883, "text": "    params = ["}
{"line": 884, "text": "        (\"wte\", model.wte, model.d_wte)"}
{"line": 885, "text": "    ]"}
{"line": 886, "text": ""}
{"line": 887, "text": "    for i, b in enumerate(model.blocks):"}
{"line": 888, "text": ""}
{"line": 889, "text": "        params.extend(["}
{"line": 890, "text": "            ("}
{"line": 891, "text": "                f\"b{i}.qkv.W\","}
{"line": 892, "text": "                b.attn.qkv.W,"}
{"line": 893, "text": "                b.attn.qkv.dW"}
{"line": 894, "text": "            ),"}
{"line": 895, "text": "            ("}
{"line": 896, "text": "                f\"b{i}.qkv.b\","}
{"line": 897, "text": "                b.attn.qkv.b,"}
{"line": 898, "text": "                b.attn.qkv.db"}
{"line": 899, "text": "            ),"}
{"line": 900, "text": "            ("}
{"line": 901, "text": "                f\"b{i}.proj.W\","}
{"line": 902, "text": "                b.attn.proj.W,"}
{"line": 903, "text": "                b.attn.proj.dW"}
{"line": 904, "text": "            ),"}
{"line": 905, "text": "            ("}
{"line": 906, "text": "                f\"b{i}.proj.b\","}
{"line": 907, "text": "                b.attn.proj.b,"}
{"line": 908, "text": "                b.attn.proj.db"}
{"line": 909, "text": "            ),"}
{"line": 910, "text": "            ("}
{"line": 911, "text": "                f\"b{i}.ln1.g\","}
{"line": 912, "text": "                b.ln1.g,"}
{"line": 913, "text": "                b.ln1.dg"}
{"line": 914, "text": "            ),"}
{"line": 915, "text": "            ("}
{"line": 916, "text": "                f\"b{i}.ln1.b\","}
{"line": 917, "text": "                b.ln1.b,"}
{"line": 918, "text": "                b.ln1.db"}
{"line": 919, "text": "            ),"}
{"line": 920, "text": "            ("}
{"line": 921, "text": "                f\"b{i}.ln2.g\","}
{"line": 922, "text": "                b.ln2.g,"}
{"line": 923, "text": "                b.ln2.dg"}
{"line": 924, "text": "            ),"}
{"line": 925, "text": "            ("}
{"line": 926, "text": "                f\"b{i}.ln2.b\","}
{"line": 927, "text": "                b.ln2.b,"}
{"line": 928, "text": "                b.ln2.db"}
{"line": 929, "text": "            ),"}
{"line": 930, "text": "            ("}
{"line": 931, "text": "                f\"b{i}.fc1.W\","}
{"line": 932, "text": "                b.mlp.fc1.W,"}
{"line": 933, "text": "                b.mlp.fc1.dW"}
{"line": 934, "text": "            ),"}
{"line": 935, "text": "            ("}
{"line": 936, "text": "                f\"b{i}.fc1.b\","}
{"line": 937, "text": "                b.mlp.fc1.b,"}
{"line": 938, "text": "                b.mlp.fc1.db"}
{"line": 939, "text": "            ),"}
{"line": 940, "text": "            ("}
{"line": 941, "text": "                f\"b{i}.fc2.W\","}
{"line": 942, "text": "                b.mlp.fc2.W,"}
{"line": 943, "text": "                b.mlp.fc2.dW"}
{"line": 944, "text": "            ),"}
{"line": 945, "text": "            ("}
{"line": 946, "text": "                f\"b{i}.fc2.b\","}
{"line": 947, "text": "                b.mlp.fc2.b,"}
{"line": 948, "text": "                b.mlp.fc2.db"}
{"line": 949, "text": "            ),"}
{"line": 950, "text": "        ])"}
{"line": 951, "text": ""}
{"line": 952, "text": "    params.extend(["}
{"line": 953, "text": "        ("}
{"line": 954, "text": "            \"lnf.g\","}
{"line": 955, "text": "            model.ln_f.g,"}
{"line": 956, "text": "            model.ln_f.dg"}
{"line": 957, "text": "        ),"}
{"line": 958, "text": "        ("}
{"line": 959, "text": "            \"lnf.b\","}
{"line": 960, "text": "            model.ln_f.b,"}
{"line": 961, "text": "            model.ln_f.db"}
{"line": 962, "text": "        ),"}
{"line": 963, "text": "    ])"}
{"line": 964, "text": ""}
{"line": 965, "text": "    return params"}
{"line": 966, "text": ""}
{"line": 967, "text": ""}
{"line": 968, "text": "def count_params(model):"}
{"line": 969, "text": ""}
{"line": 970, "text": "    seen = set()"}
{"line": 971, "text": "    total = 0"}
{"line": 972, "text": ""}
{"line": 973, "text": "    for _, p, _ in collect_params():"}
{"line": 974, "text": "        key = id(p)"}
{"line": 975, "text": ""}
{"line": 976, "text": "        if key not in seen:"}
{"line": 977, "text": "            seen.add(key)"}
{"line": 978, "text": "            total += p.size"}
{"line": 979, "text": ""}
{"line": 980, "text": "    return total"}
{"line": 981, "text": ""}
{"line": 982, "text": ""}
{"line": 983, "text": "# ============================================================"}
{"line": 984, "text": "# BUILD"}
{"line": 985, "text": "# ============================================================"}
{"line": 986, "text": ""}
{"line": 987, "text": "print("}
{"line": 988, "text": "    f\"[MODEL] Building {PRESET} \""}
{"line": 989, "text": "    f\"D={D} H={H} L={L} T={T}\""}
{"line": 990, "text": ")"}
{"line": 991, "text": ""}
{"line": 992, "text": "model = GPT("}
{"line": 993, "text": "    vocab_size,"}
{"line": 994, "text": "    D,"}
{"line": 995, "text": "    H,"}
{"line": 996, "text": "    L,"}
{"line": 997, "text": "    T"}
{"line": 998, "text": ")"}
{"line": 999, "text": ""}
{"line": 1000, "text": "params = collect_params()"}
{"line": 1001, "text": ""}
{"line": 1002, "text": "print("}
{"line": 1003, "text": "    f\"[MODEL] \""}
{"line": 1004, "text": "    f\"{count_params(model) / 1e6:.2f}M parameters\""}
{"line": 1005, "text": ")"}
{"line": 1006, "text": ""}
{"line": 1007, "text": ""}
{"line": 1008, "text": "# ============================================================"}
{"line": 1009, "text": "# NUMERICAL GRADIENT CHECK"}
{"line": 1010, "text": "# ============================================================"}
{"line": 1011, "text": ""}
{"line": 1012, "text": "print(\"[CHECK] Running pre-training finite diagnostic...\")"}
{"line": 1013, "text": ""}
{"line": 1014, "text": "test_x, test_y = get_batch()"}
{"line": 1015, "text": ""}
{"line": 1016, "text": "_, test_loss = model.forward("}
{"line": 1017, "text": "    test_x,"}
{"line": 1018, "text": "    test_y"}
{"line": 1019, "text": ")"}
{"line": 1020, "text": ""}
{"line": 1021, "text": "model.backward()"}
{"line": 1022, "text": ""}
{"line": 1023, "text": "check_finite("}
{"line": 1024, "text": "    \"initial_loss\","}
{"line": 1025, "text": "    np.array(test_loss)"}
{"line": 1026, "text": ")"}
{"line": 1027, "text": ""}
{"line": 1028, "text": "for name, _, grad in params:"}
{"line": 1029, "text": "    check_finite("}
{"line": 1030, "text": "        f\"grad:{name}\","}
{"line": 1031, "text": "        grad"}
{"line": 1032, "text": "    )"}
{"line": 1033, "text": ""}
{"line": 1034, "text": "grad_norm_sq = sum("}
{"line": 1035, "text": "    float(np.sum(grad.astype(np.float64) ** 2))"}
{"line": 1036, "text": "    for _, _, grad in params"}
{"line": 1037, "text": ")"}
{"line": 1038, "text": ""}
{"line": 1039, "text": "initial_grad_norm = math.sqrt(grad_norm_sq)"}
{"line": 1040, "text": ""}
{"line": 1041, "text": "print("}
{"line": 1042, "text": "    f\"[CHECK] PASS \""}
{"line": 1043, "text": "    f\"loss={test_loss:.6f} \""}
{"line": 1044, "text": "    f\"grad_norm={initial_grad_norm:.6f}\""}
{"line": 1045, "text": ")"}
{"line": 1046, "text": ""}
{"line": 1047, "text": ""}
{"line": 1048, "text": "# ============================================================"}
{"line": 1049, "text": "# ADAM + GLOBAL GRADIENT CLIPPING"}
{"line": 1050, "text": "# ============================================================"}
{"line": 1051, "text": ""}
{"line": 1052, "text": "adam_m = {"}
{"line": 1053, "text": "    name: zeros(*p.shape)"}
{"line": 1054, "text": "    for name, p, _ in params"}
{"line": 1055, "text": "}"}
{"line": 1056, "text": ""}
{"line": 1057, "text": "adam_v = {"}
{"line": 1058, "text": "    name: zeros(*p.shape)"}
{"line": 1059, "text": "    for name, p, _ in params"}
{"line": 1060, "text": "}"}
{"line": 1061, "text": ""}
{"line": 1062, "text": ""}
{"line": 1063, "text": "def apply_grads(step, lr):"}
{"line": 1064, "text": ""}
{"line": 1065, "text": "    global_norm_sq = 0.0"}
{"line": 1066, "text": ""}
{"line": 1067, "text": "    for _, _, grad in params:"}
{"line": 1068, "text": ""}
{"line": 1069, "text": "        check_finite("}
{"line": 1070, "text": "            \"gradient\","}
{"line": 1071, "text": "            grad"}
{"line": 1072, "text": "        )"}
{"line": 1073, "text": ""}
{"line": 1074, "text": "        global_norm_sq += float("}
{"line": 1075, "text": "            np.sum("}
{"line": 1076, "text": "                grad.astype(np.float64) ** 2"}
{"line": 1077, "text": "            )"}
{"line": 1078, "text": "        )"}
{"line": 1079, "text": ""}
{"line": 1080, "text": "    global_norm = math.sqrt("}
{"line": 1081, "text": "        global_norm_sq"}
{"line": 1082, "text": "    )"}
{"line": 1083, "text": ""}
{"line": 1084, "text": "    clip_coef = min("}
{"line": 1085, "text": "        1.0,"}
{"line": 1086, "text": "        MAX_GRAD_NORM / ("}
{"line": 1087, "text": "            global_norm + 1e-12"}
{"line": 1088, "text": "        )"}
{"line": 1089, "text": "    )"}
{"line": 1090, "text": ""}
{"line": 1091, "text": "    for name, param, grad in params:"}
{"line": 1092, "text": ""}
{"line": 1093, "text": "        g = grad * clip_coef"}
{"line": 1094, "text": ""}
{"line": 1095, "text": "        m = adam_m[name]"}
{"line": 1096, "text": "        v = adam_v[name]"}
{"line": 1097, "text": ""}
{"line": 1098, "text": "        m[:] = ("}
{"line": 1099, "text": "            BETA1 * m"}
{"line": 1100, "text": "            + (1.0 - BETA1) * g"}
{"line": 1101, "text": "        )"}
{"line": 1102, "text": ""}
{"line": 1103, "text": "        v[:] = ("}
{"line": 1104, "text": "            BETA2 * v"}
{"line": 1105, "text": "            + (1.0 - BETA2) * (g * g)"}
{"line": 1106, "text": "        )"}
{"line": 1107, "text": ""}
{"line": 1108, "text": "        m_hat = m / ("}
{"line": 1109, "text": "            1.0 - BETA1 ** step"}
{"line": 1110, "text": "        )"}
{"line": 1111, "text": ""}
{"line": 1112, "text": "        v_hat = v / ("}
{"line": 1113, "text": "            1.0 - BETA2 ** step"}
{"line": 1114, "text": "        )"}
{"line": 1115, "text": ""}
{"line": 1116, "text": "        # Weight decay only for matrices."}
{"line": 1117, "text": "        if param.ndim >= 2:"}
{"line": 1118, "text": "            param *= ("}
{"line": 1119, "text": "                1.0"}
{"line": 1120, "text": "                - lr * WEIGHT_DECAY"}
{"line": 1121, "text": "            )"}
{"line": 1122, "text": ""}
{"line": 1123, "text": "        param -= ("}
{"line": 1124, "text": "            lr"}
{"line": 1125, "text": "            * m_hat"}
{"line": 1126, "text": "            / ("}
{"line": 1127, "text": "                np.sqrt(v_hat) + EPS"}
{"line": 1128, "text": "            )"}
{"line": 1129, "text": "        )"}
{"line": 1130, "text": ""}
{"line": 1131, "text": "        check_finite("}
{"line": 1132, "text": "            f\"parameter:{name}\","}
{"line": 1133, "text": "            param"}
{"line": 1134, "text": "        )"}
{"line": 1135, "text": ""}
{"line": 1136, "text": "    # Preserve exact weight tying."}
{"line": 1137, "text": "    model.lm_head.W = model.wte.T"}
{"line": 1138, "text": ""}
{"line": 1139, "text": "    return global_norm, clip_coef"}
{"line": 1140, "text": ""}
{"line": 1141, "text": ""}
{"line": 1142, "text": "# ============================================================"}
{"line": 1143, "text": "# CHECKPOINT"}
{"line": 1144, "text": "# ============================================================"}
{"line": 1145, "text": ""}
{"line": 1146, "text": "def save_ckpt(step, loss):"}
{"line": 1147, "text": ""}
{"line": 1148, "text": "    path = ("}
{"line": 1149, "text": "        CKPT_DIR"}
{"line": 1150, "text": "        / f\"bloom_real_{PRESET}_step{step}.pkl\""}
{"line": 1151, "text": "    )"}
{"line": 1152, "text": ""}
{"line": 1153, "text": "    state = {"}
{"line": 1154, "text": "        \"step\": step,"}
{"line": 1155, "text": "        \"loss\": loss,"}
{"line": 1156, "text": "        \"preset\": PRESET,"}
{"line": 1157, "text": "        \"config\": cfg,"}
{"line": 1158, "text": "        \"stoi\": stoi,"}
{"line": 1159, "text": "        \"itos\": itos,"}
{"line": 1160, "text": "        \"wte\": model.wte.copy(),"}
{"line": 1161, "text": "        \"blocks\": [],"}
{"line": 1162, "text": "        \"ln_f_g\": model.ln_f.g.copy(),"}
{"line": 1163, "text": "        \"ln_f_b\": model.ln_f.b.copy(),"}
{"line": 1164, "text": "    }"}
{"line": 1165, "text": ""}
{"line": 1166, "text": "    for b in model.blocks:"}
{"line": 1167, "text": ""}
{"line": 1168, "text": "        state[\"blocks\"].append({"}
{"line": 1169, "text": "            \"qkv_W\": b.attn.qkv.W.copy(),"}
{"line": 1170, "text": "            \"qkv_b\": b.attn.qkv.b.copy(),"}
{"line": 1171, "text": "            \"proj_W\": b.attn.proj.W.copy(),"}
{"line": 1172, "text": "            \"proj_b\": b.attn.proj.b.copy(),"}
{"line": 1173, "text": "            \"ln1_g\": b.ln1.g.copy(),"}
{"line": 1174, "text": "            \"ln1_b\": b.ln1.b.copy(),"}
{"line": 1175, "text": "            \"ln2_g\": b.ln2.g.copy(),"}
{"line": 1176, "text": "            \"ln2_b\": b.ln2.b.copy(),"}
{"line": 1177, "text": "            \"fc1_W\": b.mlp.fc1.W.copy(),"}
{"line": 1178, "text": "            \"fc1_b\": b.mlp.fc1.b.copy(),"}
{"line": 1179, "text": "            \"fc2_W\": b.mlp.fc2.W.copy(),"}
{"line": 1180, "text": "            \"fc2_b\": b.mlp.fc2.b.copy(),"}
{"line": 1181, "text": "        })"}
{"line": 1182, "text": ""}
{"line": 1183, "text": "    with open(path, \"wb\") as f:"}
{"line": 1184, "text": "        pickle.dump("}
{"line": 1185, "text": "            state,"}
{"line": 1186, "text": "            f,"}
{"line": 1187, "text": "            protocol=pickle.HIGHEST_PROTOCOL"}
{"line": 1188, "text": "        )"}
{"line": 1189, "text": ""}
{"line": 1190, "text": "    print("}
{"line": 1191, "text": "        f\"[CKPT] {path.name}\""}
{"line": 1192, "text": "    )"}
{"line": 1193, "text": ""}
{"line": 1194, "text": ""}
{"line": 1195, "text": "# ============================================================"}
{"line": 1196, "text": "# TRAIN"}
{"line": 1197, "text": "# ============================================================"}
{"line": 1198, "text": ""}
{"line": 1199, "text": "print(\"[TRAIN] Starting stable real training...\")"}
{"line": 1200, "text": ""}
{"line": 1201, "text": "t0 = time.time()"}
{"line": 1202, "text": ""}
{"line": 1203, "text": "best_loss = float(\"inf\")"}
{"line": 1204, "text": ""}
{"line": 1205, "text": "for step in range("}
{"line": 1206, "text": "    1,"}
{"line": 1207, "text": "    MAX_ITERS + 1"}
{"line": 1208, "text": "):"}
{"line": 1209, "text": ""}
{"line": 1210, "text": "    x, y = get_batch()"}
{"line": 1211, "text": ""}
{"line": 1212, "text": "    _, loss = model.forward("}
{"line": 1213, "text": "        x,"}
{"line": 1214, "text": "        y"}
{"line": 1215, "text": "    )"}
{"line": 1216, "text": ""}
{"line": 1217, "text": "    check_finite("}
{"line": 1218, "text": "        \"loss\","}
{"line": 1219, "text": "        np.array(loss)"}
{"line": 1220, "text": "    )"}
{"line": 1221, "text": ""}
{"line": 1222, "text": "    model.backward()"}
{"line": 1223, "text": ""}
{"line": 1224, "text": "    warmup = min("}
{"line": 1225, "text": "        1.0,"}
{"line": 1226, "text": "        step / 100.0"}
{"line": 1227, "text": "    )"}
{"line": 1228, "text": ""}
{"line": 1229, "text": "    lr = LR * warmup"}
{"line": 1230, "text": ""}
{"line": 1231, "text": "    grad_norm, clip_coef = apply_grads("}
{"line": 1232, "text": "        step,"}
{"line": 1233, "text": "        lr"}
{"line": 1234, "text": "    )"}
{"line": 1235, "text": ""}
{"line": 1236, "text": "    if step % EVAL_EVERY == 0 or step == 1:"}
{"line": 1237, "text": ""}
{"line": 1238, "text": "        elapsed = time.time() - t0"}
{"line": 1239, "text": ""}
{"line": 1240, "text": "        print("}
{"line": 1241, "text": "            f\"step {step:5d} | \""}
{"line": 1242, "text": "            f\"loss {loss:.6f} | \""}
{"line": 1243, "text": "            f\"lr {lr:.2e} | \""}
{"line": 1244, "text": "            f\"grad {grad_norm:.4f} | \""}
{"line": 1245, "text": "            f\"clip {clip_coef:.4f} | \""}
{"line": 1246, "text": "            f\"{elapsed:.0f}s\""}
{"line": 1247, "text": "        )"}
{"line": 1248, "text": ""}
{"line": 1249, "text": "        if loss < best_loss:"}
{"line": 1250, "text": ""}
{"line": 1251, "text": "            best_loss = loss"}
{"line": 1252, "text": ""}
{"line": 1253, "text": "            save_ckpt("}
{"line": 1254, "text": "                step,"}
{"line": 1255, "text": "                loss"}
{"line": 1256, "text": "            )"}
{"line": 1257, "text": ""}
{"line": 1258, "text": "print("}
{"line": 1259, "text": "    f\"[TRAIN] COMPLETE \""}
{"line": 1260, "text": "    f\"best_loss={best_loss:.6f}\""}
{"line": 1261, "text": ")"}
{"line": 1262, "text": ""}
{"line": 1263, "text": "save_ckpt("}
{"line": 1264, "text": "    MAX_ITERS,"}
{"line": 1265, "text": "    loss"}
{"line": 1266, "text": ")"}
{"line": 1267, "text": ""}
{"line": 1268, "text": ""}
{"line": 1269, "text": "# ============================================================"}
{"line": 1270, "text": "# RETRIEVAL"}
{"line": 1271, "text": "# ============================================================"}
{"line": 1272, "text": ""}
{"line": 1273, "text": "archive_texts = []"}
{"line": 1274, "text": ""}
{"line": 1275, "text": "for f in glob.glob(str(ARCH_DIR / \"*\")):"}
{"line": 1276, "text": ""}
{"line": 1277, "text": "    path = pathlib.Path(f)"}
{"line": 1278, "text": ""}
{"line": 1279, "text": "    if not path.is_file():"}
{"line": 1280, "text": "        continue"}
{"line": 1281, "text": ""}
{"line": 1282, "text": "    try:"}
{"line": 1283, "text": "        text = path.read_text("}
{"line": 1284, "text": "            errors=\"ignore\""}
{"line": 1285, "text": "        )"}
{"line": 1286, "text": ""}
{"line": 1287, "text": "        archive_texts.append("}
{"line": 1288, "text": "            (path.name, text)"}
{"line": 1289, "text": "        )"}
{"line": 1290, "text": ""}
{"line": 1291, "text": "    except Exception:"}
{"line": 1292, "text": "        pass"}
{"line": 1293, "text": ""}
{"line": 1294, "text": ""}
{"line": 1295, "text": "def retrieve(query, k=2):"}
{"line": 1296, "text": ""}
{"line": 1297, "text": "    if not archive_texts:"}
{"line": 1298, "text": "        return []"}
{"line": 1299, "text": ""}
{"line": 1300, "text": "    qchars = set(query.lower())"}
{"line": 1301, "text": ""}
{"line": 1302, "text": "    scored = []"}
{"line": 1303, "text": ""}
{"line": 1304, "text": "    for name, text in archive_texts:"}
{"line": 1305, "text": ""}
{"line": 1306, "text": "        score = len("}
{"line": 1307, "text": "            qchars"}
{"line": 1308, "text": "            & set(text[:5000].lower())"}
{"line": 1309, "text": "        )"}
{"line": 1310, "text": ""}
{"line": 1311, "text": "        scored.append("}
{"line": 1312, "text": "            (score, name, text)"}
{"line": 1313, "text": "        )"}
{"line": 1314, "text": ""}
{"line": 1315, "text": "    scored.sort("}
{"line": 1316, "text": "        key=lambda z: z[0],"}
{"line": 1317, "text": "        reverse=True"}
{"line": 1318, "text": "    )"}
{"line": 1319, "text": ""}
{"line": 1320, "text": "    return scored[:k]"}
{"line": 1321, "text": ""}
{"line": 1322, "text": ""}
{"line": 1323, "text": "# ============================================================"}
{"line": 1324, "text": "# GENERATION"}
{"line": 1325, "text": "# ============================================================"}
{"line": 1326, "text": ""}
{"line": 1327, "text": "def generate("}
{"line": 1328, "text": "    prompt,"}
{"line": 1329, "text": "    n=300,"}
{"line": 1330, "text": "    temperature=0.0"}
{"line": 1331, "text": "):"}
{"line": 1332, "text": ""}
{"line": 1333, "text": "    ids = ["}
{"line": 1334, "text": "        stoi.get(c, 0)"}
{"line": 1335, "text": "        for c in prompt"}
{"line": 1336, "text": "    ]"}
{"line": 1337, "text": ""}
{"line": 1338, "text": "    if len(ids) < T:"}
{"line": 1339, "text": "        ids = ("}
{"line": 1340, "text": "            [0] * (T - len(ids))"}
{"line": 1341, "text": "            + ids"}
{"line": 1342, "text": "        )"}
{"line": 1343, "text": "    else:"}
{"line": 1344, "text": "        ids = ids[-T:]"}
{"line": 1345, "text": ""}
{"line": 1346, "text": "    out = prompt"}
{"line": 1347, "text": ""}
{"line": 1348, "text": "    for _ in range(n):"}
{"line": 1349, "text": ""}
{"line": 1350, "text": "        x = np.array("}
{"line": 1351, "text": "            ids[-T:],"}
{"line": 1352, "text": "            dtype=np.int32"}
{"line": 1353, "text": "        )[None, :]"}
{"line": 1354, "text": ""}
{"line": 1355, "text": "        logits, _ = model.forward(x)"}
{"line": 1356, "text": ""}
{"line": 1357, "text": "        logits = logits["}
{"line": 1358, "text": "            0,"}
{"line": 1359, "text": "            -1"}
{"line": 1360, "text": "        ].astype(np.float64)"}
{"line": 1361, "text": ""}
{"line": 1362, "text": "        if temperature <= 0:"}
{"line": 1363, "text": ""}
{"line": 1364, "text": "            idx = int("}
{"line": 1365, "text": "                np.argmax(logits)"}
{"line": 1366, "text": "            )"}
{"line": 1367, "text": ""}
{"line": 1368, "text": "        else:"}
{"line": 1369, "text": ""}
{"line": 1370, "text": "            logits = ("}
{"line": 1371, "text": "                logits - logits.max()"}
{"line": 1372, "text": "            ) / temperature"}
{"line": 1373, "text": ""}
{"line": 1374, "text": "            probs = np.exp("}
{"line": 1375, "text": "                np.clip("}
{"line": 1376, "text": "                    logits,"}
{"line": 1377, "text": "                    -80.0,"}
{"line": 1378, "text": "                    80.0"}
{"line": 1379, "text": "                )"}
{"line": 1380, "text": "            )"}
{"line": 1381, "text": ""}
{"line": 1382, "text": "            probs /= probs.sum()"}
{"line": 1383, "text": ""}
{"line": 1384, "text": "            idx = int("}
{"line": 1385, "text": "                np.random.choice("}
{"line": 1386, "text": "                    len(probs),"}
{"line": 1387, "text": "                    p=probs"}
{"line": 1388, "text": "                )"}
{"line": 1389, "text": "            )"}
{"line": 1390, "text": ""}
{"line": 1391, "text": "        out += itos[idx]"}
{"line": 1392, "text": ""}
{"line": 1393, "text": "        ids.append(idx)"}
{"line": 1394, "text": ""}
{"line": 1395, "text": "    return out"}
{"line": 1396, "text": ""}
{"line": 1397, "text": ""}
{"line": 1398, "text": "# ============================================================"}
{"line": 1399, "text": "# INTERACTIVE"}
{"line": 1400, "text": "# ============================================================"}
{"line": 1401, "text": ""}
{"line": 1402, "text": "print()"}
{"line": 1403, "text": "print("}
{"line": 1404, "text": "    f\"[BLOOM REAL READY] \""}
{"line": 1405, "text": "    f\"{PRESET} | stable gradients\""}
{"line": 1406, "text": ")"}
{"line": 1407, "text": "print("}
{"line": 1408, "text": "    \"Commands: exit | quit | discover\""}
{"line": 1409, "text": ")"}
{"line": 1410, "text": "print()"}
{"line": 1411, "text": ""}
{"line": 1412, "text": "while True:"}
{"line": 1413, "text": ""}
{"line": 1414, "text": "    try:"}
{"line": 1415, "text": "        q = input(\"> \").strip()"}
{"line": 1416, "text": ""}
{"line": 1417, "text": "    except ("}
