{"line": 23, "text": "print(f\"Model file       : {MODEL}\")"}
{"line": 24, "text": "print(f\"Lines            : {len(lines):,}\")"}
{"line": 25, "text": "print(f\"Characters       : {len(text):,}\")"}
{"line": 26, "text": "print()"}
{"line": 27, "text": ""}
{"line": 28, "text": "# ----------------------------------------------------------------------"}
{"line": 29, "text": "# AST STRUCTURE"}
{"line": 30, "text": "# ----------------------------------------------------------------------"}
{"line": 31, "text": ""}
{"line": 32, "text": "try:"}
{"line": 33, "text": "    tree = ast.parse(text)"}
{"line": 34, "text": "except Exception as e:"}
{"line": 35, "text": "    print(\"STATUS: PARSE_ERROR\")"}
{"line": 36, "text": "    print(e)"}
{"line": 37, "text": "    raise SystemExit(1)"}
{"line": 38, "text": ""}
{"line": 39, "text": "classes = ["}
{"line": 40, "text": "    n for n in ast.walk(tree)"}
{"line": 41, "text": "    if isinstance(n, ast.ClassDef)"}
{"line": 42, "text": "]"}
{"line": 43, "text": ""}
{"line": 44, "text": "functions = ["}
{"line": 45, "text": "    n for n in ast.walk(tree)"}
{"line": 46, "text": "    if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))"}
{"line": 47, "text": "]"}
{"line": 48, "text": ""}
{"line": 49, "text": "print(\"=\" * 72)"}
{"line": 50, "text": "print(\"MODEL ARCHITECTURE\")"}
{"line": 51, "text": "print(\"=\" * 72)"}
{"line": 52, "text": ""}
{"line": 53, "text": "for cls in classes:"}
{"line": 54, "text": "    print(f\"\\nCLASS: {cls.name}\")"}
{"line": 55, "text": ""}
{"line": 56, "text": "    methods = ["}
{"line": 57, "text": "        n.name"}
{"line": 58, "text": "        for n in cls.body"}
{"line": 59, "text": "        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))"}
{"line": 60, "text": "    ]"}
{"line": 61, "text": ""}
{"line": 62, "text": "    print("}
{"line": 63, "text": "        \"Methods         : \""}
{"line": 64, "text": "        + (\", \".join(methods) if methods else \"none\")"}
{"line": 65, "text": "    )"}
{"line": 66, "text": ""}
{"line": 67, "text": "print()"}
{"line": 68, "text": "print(\"Top-level functions:\")"}
{"line": 69, "text": "for fn in functions:"}
{"line": 70, "text": "    parent = None"}
{"line": 71, "text": ""}
{"line": 72, "text": "    for cls in classes:"}
{"line": 73, "text": "        if fn in cls.body:"}
{"line": 74, "text": "            parent = cls.name"}
{"line": 75, "text": "            break"}
{"line": 76, "text": ""}
{"line": 77, "text": "    if parent is None:"}
{"line": 78, "text": "        print(f\"  {fn.name}\")"}
{"line": 79, "text": ""}
{"line": 80, "text": "# ----------------------------------------------------------------------"}
{"line": 81, "text": "# CONFIGURATION CONSTANTS"}
{"line": 82, "text": "# ----------------------------------------------------------------------"}
{"line": 83, "text": ""}
{"line": 84, "text": "print()"}
{"line": 85, "text": "print(\"=\" * 72)"}
{"line": 86, "text": "print(\"MODEL CONFIGURATION CONSTANTS\")"}
{"line": 87, "text": "print(\"=\" * 72)"}
{"line": 88, "text": ""}
{"line": 89, "text": "interesting_names = {"}
{"line": 90, "text": "    \"VOCAB_SIZE\","}
{"line": 91, "text": "    \"BLOCK_SIZE\","}
{"line": 92, "text": "    \"N_LAYER\","}
{"line": 93, "text": "    \"N_HEAD\","}
{"line": 94, "text": "    \"N_EMBD\","}
{"line": 95, "text": "    \"DROPOUT\","}
{"line": 96, "text": "    \"BATCH_SIZE\","}
{"line": 97, "text": "    \"LR\","}
{"line": 98, "text": "    \"LEARNING_RATE\","}
{"line": 99, "text": "    \"WEIGHT_DECAY\","}
{"line": 100, "text": "    \"STEPS\","}
{"line": 101, "text": "    \"ITERATIONS\","}
{"line": 102, "text": "    \"TRAIN_STEPS\","}
{"line": 103, "text": "    \"EVAL_INTERVAL\","}
{"line": 104, "text": "    \"WARMUP\","}
{"line": 105, "text": "    \"BETA1\","}
{"line": 106, "text": "    \"BETA2\","}
{"line": 107, "text": "    \"EPS\","}
{"line": 108, "text": "    \"SEQ_LEN\","}
{"line": 109, "text": "    \"CONTEXT\","}
{"line": 110, "text": "}"}
{"line": 111, "text": ""}
{"line": 112, "text": "found_constants = {}"}
{"line": 113, "text": ""}
{"line": 114, "text": "for node in tree.body:"}
{"line": 115, "text": "    if isinstance(node, ast.Assign):"}
{"line": 116, "text": "        for target in node.targets:"}
{"line": 117, "text": "            if isinstance(target, ast.Name):"}
{"line": 118, "text": "                if target.id in interesting_names:"}
{"line": 119, "text": "                    try:"}
{"line": 120, "text": "                        value = ast.literal_eval(node.value)"}
{"line": 121, "text": "                    except Exception:"}
{"line": 122, "text": "                        value = ast.unparse(node.value)"}
{"line": 123, "text": ""}
{"line": 124, "text": "                    found_constants[target.id] = value"}
{"line": 125, "text": ""}
{"line": 126, "text": "for key, value in found_constants.items():"}
{"line": 127, "text": "    print(f\"{key:<20} = {value}\")"}
{"line": 128, "text": ""}
{"line": 129, "text": "if not found_constants:"}
{"line": 130, "text": "    print(\"No obvious top-level configuration constants found.\")"}
{"line": 131, "text": ""}
{"line": 132, "text": "# ----------------------------------------------------------------------"}
{"line": 133, "text": "# DATA LOADING"}
{"line": 134, "text": "# ----------------------------------------------------------------------"}
{"line": 135, "text": ""}
{"line": 136, "text": "print()"}
{"line": 137, "text": "print(\"=\" * 72)"}
{"line": 138, "text": "print(\"DATA LOADING PATH\")"}
{"line": 139, "text": "print(\"=\" * 72)"}
{"line": 140, "text": ""}
{"line": 141, "text": "data_patterns = ["}
{"line": 142, "text": "    r\"load_text\","}
{"line": 143, "text": "    r\"get_batch\","}
{"line": 144, "text": "    r\"training_corpus\","}
{"line": 145, "text": "    r\"bloom_train\","}
{"line": 146, "text": "    r\"train_v2\","}
{"line": 147, "text": "    r\"valid_v2\","}
{"line": 148, "text": "    r\"bloom_train\\.txt\","}
{"line": 149, "text": "    r\"bloom_valid\\.txt\","}
{"line": 150, "text": "    r\"open\\(\","}
{"line": 151, "text": "    r\"read_text\","}
{"line": 152, "text": "    r\"Path\\(\","}
{"line": 153, "text": "]"}
{"line": 154, "text": ""}
{"line": 155, "text": "for pattern in data_patterns:"}
{"line": 156, "text": "    hits = ["}
{"line": 157, "text": "        i + 1"}
{"line": 158, "text": "        for i, line in enumerate(lines)"}
{"line": 159, "text": "        if re.search(pattern, line, re.IGNORECASE)"}
{"line": 160, "text": "    ]"}
{"line": 161, "text": ""}
{"line": 162, "text": "    if hits:"}
{"line": 163, "text": "        print(f\"{pattern:<25} lines: {hits}\")"}
{"line": 164, "text": ""}
{"line": 165, "text": "print()"}
{"line": 166, "text": "print(\"Relevant source lines:\")"}
{"line": 167, "text": "for i, line in enumerate(lines, 1):"}
{"line": 168, "text": "    low = line.lower()"}
{"line": 169, "text": ""}
{"line": 170, "text": "    if any("}
{"line": 171, "text": "        x in low"}
{"line": 172, "text": "        for x in ("}
{"line": 173, "text": "            \"load_text\","}
{"line": 174, "text": "            \"get_batch\","}
{"line": 175, "text": "            \"training_corpus\","}
{"line": 176, "text": "            \"bloom_train\","}
{"line": 177, "text": "            \"bloom_valid\","}
{"line": 178, "text": "            \"train_v2\","}
{"line": 179, "text": "            \"valid_v2\","}
{"line": 180, "text": "        )"}
{"line": 181, "text": "    ):"}
{"line": 182, "text": "        print(f\"{i:5d}: {line}\")"}
{"line": 183, "text": ""}
{"line": 184, "text": "# ----------------------------------------------------------------------"}
{"line": 185, "text": "# TRAINING LOOP"}
{"line": 186, "text": "# ----------------------------------------------------------------------"}
{"line": 187, "text": ""}
{"line": 188, "text": "print()"}
{"line": 189, "text": "print(\"=\" * 72)"}
{"line": 190, "text": "print(\"TRAINING LOOP DETECTION\")"}
{"line": 191, "text": "print(\"=\" * 72)"}
{"line": 192, "text": ""}
{"line": 193, "text": "training_patterns = ["}
{"line": 194, "text": "    r\"for .*range\","}
{"line": 195, "text": "    r\"while \","}
{"line": 196, "text": "    r\"loss\","}
{"line": 197, "text": "    r\"backward\","}
{"line": 198, "text": "    r\"apply_grads\","}
{"line": 199, "text": "    r\"learning_rate\","}
{"line": 200, "text": "    r\"lr\","}
{"line": 201, "text": "    r\"optimizer\","}
{"line": 202, "text": "    r\"update\","}
{"line": 203, "text": "    r\"step\","}
{"line": 204, "text": "    r\"save_ckpt\","}
{"line": 205, "text": "    r\"checkpoint\","}
{"line": 206, "text": "]"}
{"line": 207, "text": ""}
{"line": 208, "text": "for pattern in training_patterns:"}
{"line": 209, "text": "    hits = ["}
{"line": 210, "text": "        i + 1"}
{"line": 211, "text": "        for i, line in enumerate(lines)"}
{"line": 212, "text": "        if re.search(pattern, line, re.IGNORECASE)"}
{"line": 213, "text": "    ]"}
{"line": 214, "text": ""}
{"line": 215, "text": "    if hits:"}
{"line": 216, "text": "        print(f\"{pattern:<20} {hits}\")"}
{"line": 217, "text": ""}
{"line": 218, "text": "# ----------------------------------------------------------------------"}
{"line": 219, "text": "# MAIN / EXECUTION PATH"}
{"line": 220, "text": "# ----------------------------------------------------------------------"}
{"line": 221, "text": ""}
{"line": 222, "text": "print()"}
{"line": 223, "text": "print(\"=\" * 72)"}
{"line": 224, "text": "print(\"EXECUTION PATH\")"}
{"line": 225, "text": "print(\"=\" * 72)"}
{"line": 226, "text": ""}
{"line": 227, "text": "main_lines = []"}
{"line": 228, "text": ""}
{"line": 229, "text": "for i, line in enumerate(lines, 1):"}
{"line": 230, "text": "    if \"__name__\" in line or \"GPT(\" in line:"}
{"line": 231, "text": "        main_lines.append((i, line))"}
{"line": 232, "text": ""}
{"line": 233, "text": "if main_lines:"}
{"line": 234, "text": "    for i, line in main_lines:"}
{"line": 235, "text": "        print(f\"{i:5d}: {line}\")"}
{"line": 236, "text": "else:"}
{"line": 237, "text": "    print(\"No obvious __main__ or GPT construction found.\")"}
{"line": 238, "text": ""}
{"line": 239, "text": "# ----------------------------------------------------------------------"}
{"line": 240, "text": "# CHECKPOINTS"}
{"line": 241, "text": "# ----------------------------------------------------------------------"}
{"line": 242, "text": ""}
{"line": 243, "text": "print()"}
{"line": 244, "text": "print(\"=\" * 72)"}
{"line": 245, "text": "print(\"CHECKPOINT / STATE\")"}
{"line": 246, "text": "print(\"=\" * 72)"}
{"line": 247, "text": ""}
{"line": 248, "text": "for i, line in enumerate(lines, 1):"}
{"line": 249, "text": "    low = line.lower()"}
{"line": 250, "text": ""}
{"line": 251, "text": "    if any("}
{"line": 252, "text": "        x in low"}
{"line": 253, "text": "        for x in ("}
{"line": 254, "text": "            \"save_ckpt\","}
{"line": 255, "text": "            \"load_ckpt\","}
{"line": 256, "text": "            \"checkpoint\","}
{"line": 257, "text": "            \"pickle\","}
{"line": 258, "text": "            \".pkl\","}
{"line": 259, "text": "            \".ckpt\","}
{"line": 260, "text": "            \"state\","}
{"line": 261, "text": "        )"}
{"line": 262, "text": "    ):"}
{"line": 263, "text": "        print(f\"{i:5d}: {line}\")"}
{"line": 264, "text": ""}
{"line": 265, "text": "# ----------------------------------------------------------------------"}
{"line": 266, "text": "# TOKENIZATION"}
{"line": 267, "text": "# ----------------------------------------------------------------------"}
{"line": 268, "text": ""}
{"line": 269, "text": "print()"}
{"line": 270, "text": "print(\"=\" * 72)"}
{"line": 271, "text": "print(\"TOKENIZATION / VOCABULARY\")"}
{"line": 272, "text": "print(\"=\" * 72)"}
{"line": 273, "text": ""}
{"line": 274, "text": "token_patterns = ["}
{"line": 275, "text": "    r\"token\","}
{"line": 276, "text": "    r\"vocab\","}
{"line": 277, "text": "    r\"encode\","}
{"line": 278, "text": "    r\"decode\","}
{"line": 279, "text": "    r\"stoi\","}
{"line": 280, "text": "    r\"itos\","}
{"line": 281, "text": "    r\"ord\\(\","}
{"line": 282, "text": "    r\"chr\\(\","}
{"line": 283, "text": "]"}
{"line": 284, "text": ""}
{"line": 285, "text": "for pattern in token_patterns:"}
{"line": 286, "text": "    hits = ["}
{"line": 287, "text": "        i + 1"}
{"line": 288, "text": "        for i, line in enumerate(lines)"}
{"line": 289, "text": "        if re.search(pattern, line, re.IGNORECASE)"}
{"line": 290, "text": "    ]"}
{"line": 291, "text": ""}
{"line": 292, "text": "    if hits:"}
{"line": 293, "text": "        print(f\"{pattern:<15} {hits}\")"}
{"line": 294, "text": ""}
{"line": 295, "text": "# ----------------------------------------------------------------------"}
{"line": 296, "text": "# GRADIENT PATH"}
{"line": 297, "text": "# ----------------------------------------------------------------------"}
{"line": 298, "text": ""}
{"line": 299, "text": "print()"}
{"line": 300, "text": "print(\"=\" * 72)"}
{"line": 301, "text": "print(\"GRADIENT PATH\")"}
{"line": 302, "text": "print(\"=\" * 72)"}
{"line": 303, "text": ""}
{"line": 304, "text": "gradient_patterns = ["}
{"line": 305, "text": "    r\"\\.grad\","}
{"line": 306, "text": "    r\"backward\","}
{"line": 307, "text": "    r\"apply_grads\","}
{"line": 308, "text": "    r\"grad\","}
{"line": 309, "text": "    r\"finite\","}
{"line": 310, "text": "    r\"nan\","}
{"line": 311, "text": "    r\"isfinite\","}
{"line": 312, "text": "]"}
{"line": 313, "text": ""}
{"line": 314, "text": "for pattern in gradient_patterns:"}
{"line": 315, "text": "    hits = ["}
{"line": 316, "text": "        i + 1"}
{"line": 317, "text": "        for i, line in enumerate(lines)"}
{"line": 318, "text": "        if re.search(pattern, line, re.IGNORECASE)"}
{"line": 319, "text": "    ]"}
{"line": 320, "text": ""}
{"line": 321, "text": "    if hits:"}
{"line": 322, "text": "        print(f\"{pattern:<15} {hits}\")"}
{"line": 323, "text": ""}
{"line": 324, "text": "# ----------------------------------------------------------------------"}
{"line": 325, "text": "# MODEL PARAMETER ESTIMATE FROM CONFIG"}
{"line": 326, "text": "# ----------------------------------------------------------------------"}
{"line": 327, "text": ""}
{"line": 328, "text": "print()"}
{"line": 329, "text": "print(\"=\" * 72)"}
{"line": 330, "text": "print(\"PARAMETER ESTIMATE\")"}
{"line": 331, "text": "print(\"=\" * 72)"}
{"line": 332, "text": ""}
{"line": 333, "text": "def get_num(name):"}
{"line": 334, "text": "    value = found_constants.get(name)"}
{"line": 335, "text": "    try:"}
{"line": 336, "text": "        return int(value)"}
{"line": 337, "text": "    except Exception:"}
{"line": 338, "text": "        return None"}
{"line": 339, "text": ""}
{"line": 340, "text": "vocab = get_num(\"VOCAB_SIZE\")"}
{"line": 341, "text": "embd = get_num(\"N_EMBD\")"}
{"line": 342, "text": "layers = get_num(\"N_LAYER\")"}
{"line": 343, "text": ""}
{"line": 344, "text": "estimated = None"}
{"line": 345, "text": ""}
{"line": 346, "text": "if vocab and embd and layers:"}
{"line": 347, "text": "    # Approximate GPT parameter count."}
{"line": 348, "text": "    # Embedding + output + transformer blocks."}
{"line": 349, "text": "    embedding = vocab * embd"}
{"line": 350, "text": ""}
{"line": 351, "text": "    # Attention approximately 4 * d^2"}
{"line": 352, "text": "    attention = 4 * embd * embd"}
{"line": 353, "text": ""}
{"line": 354, "text": "    # MLP approximately 8 * d^2 for 4d expansion"}
{"line": 355, "text": "    mlp = 8 * embd * embd"}
{"line": 356, "text": ""}
{"line": 357, "text": "    # Two LayerNorm parameter sets"}
{"line": 358, "text": "    norms = 4 * embd"}
{"line": 359, "text": ""}
{"line": 360, "text": "    per_block = attention + mlp + norms"}
{"line": 361, "text": ""}
{"line": 362, "text": "    estimated = embedding + layers * per_block"}
{"line": 363, "text": ""}
{"line": 364, "text": "    print(f\"Vocabulary       : {vocab:,}\")"}
{"line": 365, "text": "    print(f\"Embedding width  : {embd:,}\")"}
{"line": 366, "text": "    print(f\"Layers           : {layers:,}\")"}
{"line": 367, "text": "    print(f\"Approx parameters: {estimated:,}\")"}
{"line": 368, "text": ""}
{"line": 369, "text": "else:"}
{"line": 370, "text": "    print(\"Could not infer enough constants for parameter estimate.\")"}
{"line": 371, "text": ""}
{"line": 372, "text": "# ----------------------------------------------------------------------"}
{"line": 373, "text": "# CORPUS AVAILABILITY"}
{"line": 374, "text": "# ----------------------------------------------------------------------"}
{"line": 375, "text": ""}
{"line": 376, "text": "print()"}
{"line": 377, "text": "print(\"=\" * 72)"}
{"line": 378, "text": "print(\"AVAILABLE TRAINING CORPORA\")"}
{"line": 379, "text": "print(\"=\" * 72)"}
{"line": 380, "text": ""}
{"line": 381, "text": "corpus_candidates = ["}
{"line": 382, "text": "    ROOT / \"training_corpus.txt\","}
{"line": 383, "text": "    ROOT / \"training_corpus_clean.txt\","}
{"line": 384, "text": "    ROOT / \"training_corpus_semantic.txt\","}
{"line": 385, "text": "    ROOT / \"training_corpus_semantic_v2.txt\","}
{"line": 386, "text": "    ROOT / \"bloom_train.txt\","}
{"line": 387, "text": "    ROOT / \"bloom_valid.txt\","}
{"line": 388, "text": "    ROOT / \"bloom_train_v2.txt\","}
{"line": 389, "text": "    ROOT / \"bloom_valid_v2.txt\","}
{"line": 390, "text": "]"}
{"line": 391, "text": ""}
{"line": 392, "text": "for path in corpus_candidates:"}
{"line": 393, "text": "    if path.exists():"}
{"line": 394, "text": "        data = path.read_text("}
{"line": 395, "text": "            encoding=\"utf-8\","}
{"line": 396, "text": "            errors=\"replace\""}
{"line": 397, "text": "        )"}
{"line": 398, "text": ""}
{"line": 399, "text": "        words = data.split()"}
{"line": 400, "text": ""}
{"line": 401, "text": "        print("}
{"line": 402, "text": "            f\"{path.name:<35} \""}
{"line": 403, "text": "            f\"{len(data):>8,} chars | \""}
{"line": 404, "text": "            f\"{len(words):>7,} words | \""}
{"line": 405, "text": "            f\"{path.stat().st_size:>8,} bytes\""}
{"line": 406, "text": "        )"}
{"line": 407, "text": "    else:"}
{"line": 408, "text": "        print("}
{"line": 409, "text": "            f\"{path.name:<35} MISSING\""}
{"line": 410, "text": "        )"}
{"line": 411, "text": ""}
{"line": 412, "text": "# ----------------------------------------------------------------------"}
{"line": 413, "text": "# FINAL CLASSIFICATION"}
{"line": 414, "text": "# ----------------------------------------------------------------------"}
{"line": 415, "text": ""}
{"line": 416, "text": "print()"}
{"line": 417, "text": "print(\"=\" * 72)"}
{"line": 418, "text": "print(\"ARCHITECTURE PROBE VERDICT\")"}
{"line": 419, "text": "print(\"=\" * 72)"}
{"line": 420, "text": ""}
{"line": 421, "text": "has_gpt = any("}
{"line": 422, "text": "    cls.name == \"GPT\""}
{"line": 423, "text": "    for cls in classes"}
{"line": 424, "text": ")"}
{"line": 425, "text": ""}
{"line": 426, "text": "has_attention = any("}
{"line": 427, "text": "    cls.name == \"CausalSelfAttention\""}
{"line": 428, "text": "    for cls in classes"}
{"line": 429, "text": ")"}
{"line": 430, "text": ""}
{"line": 431, "text": "has_backward = bool("}
{"line": 432, "text": "    re.search(r\"\\bbackward\\b\", text)"}
{"line": 433, "text": ")"}
{"line": 434, "text": ""}
{"line": 435, "text": "has_grads = bool("}
{"line": 436, "text": "    re.search(r\"apply_grads|\\.grad|grad\", text)"}
{"line": 437, "text": ")"}
{"line": 438, "text": ""}
{"line": 439, "text": "has_batch = bool("}
{"line": 440, "text": "    re.search(r\"get_batch\", text)"}
{"line": 441, "text": ")"}
{"line": 442, "text": ""}
{"line": 443, "text": "has_checkpoint = bool("}
{"line": 444, "text": "    re.search(r\"save_ckpt|checkpoint\", text)"}
{"line": 445, "text": ")"}
{"line": 446, "text": ""}
{"line": 447, "text": "if ("}
{"line": 448, "text": "    has_gpt"}
{"line": 449, "text": "    and has_attention"}
{"line": 450, "text": "    and has_backward"}
{"line": 451, "text": "    and has_grads"}
{"line": 452, "text": "    and has_batch"}
{"line": 453, "text": "):"}
{"line": 454, "text": "    print(\"ARCHITECTURE: REAL_TRAINABLE_GPT\")"}
{"line": 455, "text": "    print(\"FORWARD_PATH: PRESENT\")"}
{"line": 456, "text": "    print(\"BACKWARD_PATH: PRESENT\")"}
{"line": 457, "text": "    print(\"GRADIENT_UPDATE: PRESENT\")"}
{"line": 458, "text": "    print(\"BATCH_LOADER: PRESENT\")"}
{"line": 459, "text": ""}
{"line": 460, "text": "    if has_checkpoint:"}
{"line": 461, "text": "        print(\"CHECKPOINTING: PRESENT\")"}
{"line": 462, "text": "    else:"}
{"line": 463, "text": "        print(\"CHECKPOINTING: NOT_DETECTED\")"}
{"line": 464, "text": ""}
{"line": 465, "text": "    print()"}
{"line": 466, "text": "    print(\"NEXT TEST:\")"}
{"line": 467, "text": "    print(\"RUN THE ACTUAL bloom_real.py TRAINING LOOP\")"}
