{"line": 227, "text": "            \"vocabulary\","}
{"line": 228, "text": "            \"tokenizer\","}
{"line": 229, "text": "            \"token_id\","}
{"line": 230, "text": "            \"token_ids\","}
{"line": 231, "text": "            \"token2id\","}
{"line": 232, "text": "            \"id2token\","}
{"line": 233, "text": "            \"itos\","}
{"line": 234, "text": "            \"stoi\","}
{"line": 235, "text": "            \"encode\","}
{"line": 236, "text": "            \"decode\","}
{"line": 237, "text": "        ],"}
{"line": 238, "text": "        \"model\": ["}
{"line": 239, "text": "            \"model\","}
{"line": 240, "text": "            \"model_dim\","}
{"line": 241, "text": "            \"hidden_dim\","}
{"line": 242, "text": "            \"hidden_size\","}
{"line": 243, "text": "            \"embedding\","}
{"line": 244, "text": "            \"embed_dim\","}
{"line": 245, "text": "            \"n_embd\","}
{"line": 246, "text": "            \"vocab_size\","}
{"line": 247, "text": "            \"num_embeddings\","}
{"line": 248, "text": "        ],"}
{"line": 249, "text": "        \"runtime\": ["}
{"line": 250, "text": "            \"runtime\","}
{"line": 251, "text": "            \"checkpoint\","}
{"line": 252, "text": "            \"load_state_dict\","}
{"line": 253, "text": "            \"state_dict\","}
{"line": 254, "text": "            \"weights\","}
