{"line": 270, "text": ""}
{"line": 271, "text": "def search_contracts():"}
{"line": 272, "text": "    keywords = contract_keywords()"}
{"line": 273, "text": "    findings = []"}
{"line": 274, "text": ""}
{"line": 275, "text": "    for path in python_files():"}
{"line": 276, "text": "        text, _, parse_error = parse_python(path)"}
{"line": 277, "text": ""}
{"line": 278, "text": "        if parse_error:"}
{"line": 279, "text": "            findings.append({"}
{"line": 280, "text": "                \"file\": str(path.relative_to(ROOT)),"}
{"line": 281, "text": "                \"type\": \"parse_error\","}
{"line": 282, "text": "                \"detail\": parse_error,"}
{"line": 283, "text": "            })"}
{"line": 284, "text": "            continue"}
{"line": 285, "text": ""}
{"line": 286, "text": "        lines = text.splitlines()"}
{"line": 287, "text": ""}
{"line": 288, "text": "        for category, terms in keywords.items():"}
{"line": 289, "text": "            for i, line in enumerate(lines, 1):"}
{"line": 290, "text": "                lower = line.lower()"}
{"line": 291, "text": ""}
{"line": 292, "text": "                hits = [term for term in terms if term.lower() in lower]"}
{"line": 293, "text": ""}
{"line": 294, "text": "                if hits:"}
{"line": 295, "text": "                    findings.append({"}
{"line": 296, "text": "                        \"file\": str(path.relative_to(ROOT)),"}
{"line": 297, "text": "                        \"line\": i,"}
{"line": 298, "text": "                        \"category\": category,"}
{"line": 299, "text": "                        \"hits\": hits,"}
{"line": 300, "text": "                        \"text\": line[:500],"}
{"line": 301, "text": "                    })"}
{"line": 302, "text": ""}
{"line": 303, "text": "    return findings"}
{"line": 304, "text": ""}
{"line": 305, "text": ""}
{"line": 306, "text": "def producer_consumer_analysis(findings):"}
{"line": 307, "text": "    groups = {}"}
{"line": 308, "text": ""}
{"line": 309, "text": "    for item in findings:"}
{"line": 310, "text": "        if \"category\" not in item:"}
{"line": 311, "text": "            continue"}
{"line": 312, "text": ""}
{"line": 313, "text": "        groups.setdefault(item[\"category\"], []).append(item)"}
{"line": 314, "text": ""}
{"line": 315, "text": "    analysis = {}"}
{"line": 316, "text": ""}
{"line": 317, "text": "    for category, entries in groups.items():"}
{"line": 318, "text": "        producers = []"}
{"line": 319, "text": "        consumers = []"}
{"line": 320, "text": ""}
{"line": 321, "text": "        for e in entries:"}
{"line": 322, "text": "            text = e.get(\"text\", \"\").lower()"}
{"line": 323, "text": ""}
{"line": 324, "text": "            producer_words = ("}
{"line": 325, "text": "                \"create\","}
{"line": 326, "text": "                \"build\","}
{"line": 327, "text": "                \"construct\","}
{"line": 328, "text": "                \"load\","}
{"line": 329, "text": "                \"generate\","}
{"line": 330, "text": "                \"initialize\","}
{"line": 331, "text": "                \"init\","}
{"line": 332, "text": "                \"fit\","}
{"line": 333, "text": "                \"train\","}
{"line": 334, "text": "                \"make\","}
{"line": 335, "text": "                \"define\","}
{"line": 336, "text": "                \"save\","}
{"line": 337, "text": "                \"write\","}
{"line": 338, "text": "            )"}
{"line": 339, "text": ""}
{"line": 340, "text": "            consumer_words = ("}
{"line": 341, "text": "                \"use\","}
{"line": 342, "text": "                \"get\","}
{"line": 343, "text": "                \"retrieve\","}
{"line": 344, "text": "                \"lookup\","}
{"line": 345, "text": "                \"encode\","}
{"line": 346, "text": "                \"decode\","}
{"line": 347, "text": "                \"predict\","}
{"line": 348, "text": "                \"forward\","}
{"line": 349, "text": "                \"input\","}
{"line": 350, "text": "                \"expected\","}
{"line": 351, "text": "                \"require\","}
{"line": 352, "text": "            )"}
{"line": 353, "text": ""}
{"line": 354, "text": "            if any(w in text for w in producer_words):"}
{"line": 355, "text": "                producers.append(e)"}
{"line": 356, "text": ""}
{"line": 357, "text": "            if any(w in text for w in consumer_words):"}
{"line": 358, "text": "                consumers.append(e)"}
{"line": 359, "text": ""}
{"line": 360, "text": "        analysis[category] = {"}
{"line": 361, "text": "            \"total_mentions\": len(entries),"}
{"line": 362, "text": "            \"candidate_producers\": producers,"}
{"line": 363, "text": "            \"candidate_consumers\": consumers,"}
{"line": 364, "text": "        }"}
{"line": 365, "text": ""}
{"line": 366, "text": "    return analysis"}
{"line": 367, "text": ""}
{"line": 368, "text": ""}
{"line": 369, "text": "def detect_known_contract_failures(findings):"}
{"line": 370, "text": "    failures = []"}
{"line": 371, "text": ""}
{"line": 372, "text": "    vocab = [x for x in findings if x.get(\"category\") == \"vocabulary\"]"}
{"line": 373, "text": "    model = [x for x in findings if x.get(\"category\") == \"model\"]"}
{"line": 374, "text": ""}
{"line": 375, "text": "    vocab_producer_terms = ("}
{"line": 376, "text": "        \"build\","}
{"line": 377, "text": "        \"create\","}
{"line": 378, "text": "        \"generate\","}
{"line": 379, "text": "        \"load\","}
{"line": 380, "text": "        \"initialize\","}
{"line": 381, "text": "        \"tokenizer\","}
{"line": 382, "text": "        \"vocab\","}
{"line": 383, "text": "    )"}
{"line": 384, "text": ""}
{"line": 385, "text": "    vocab_consumers = ("}
{"line": 386, "text": "        \"encode\","}
{"line": 387, "text": "        \"decode\","}
{"line": 388, "text": "        \"token_id\","}
{"line": 389, "text": "        \"token_ids\","}
{"line": 390, "text": "        \"retrieve\","}
{"line": 391, "text": "    )"}
{"line": 392, "text": ""}
{"line": 393, "text": "    producer_candidates = ["}
{"line": 394, "text": "        x for x in vocab"}
{"line": 395, "text": "        if any(t in x.get(\"text\", \"\").lower() for t in vocab_producer_terms)"}
{"line": 396, "text": "    ]"}
{"line": 397, "text": ""}
{"line": 398, "text": "    consumer_candidates = ["}
{"line": 399, "text": "        x for x in vocab"}
{"line": 400, "text": "        if any(t in x.get(\"text\", \"\").lower() for t in vocab_consumers)"}
{"line": 401, "text": "    ]"}
{"line": 402, "text": ""}
{"line": 403, "text": "    if consumer_candidates and not producer_candidates:"}
{"line": 404, "text": "        failures.append({"}
{"line": 405, "text": "            \"severity\": \"CRITICAL\","}
{"line": 406, "text": "            \"contract\": \"runtime_vocabulary\","}
{"line": 407, "text": "            \"problem\": \"Consumers of vocabulary/token IDs were found, but no defensible vocabulary producer was found in scanned Python source.\","}
{"line": 408, "text": "            \"evidence\": consumer_candidates[:30],"}
{"line": 409, "text": "            \"required_action\": \"Trace the actual runtime initialization path and reconstruct the producer contract from source/config/checkpoint evidence.\","}
{"line": 410, "text": "            \"fabrication_allowed\": False,"}
{"line": 411, "text": "        })"}
{"line": 412, "text": ""}
{"line": 413, "text": "    model_mentions = len(model)"}
{"line": 414, "text": ""}
{"line": 415, "text": "    if model_mentions == 0:"}
{"line": 416, "text": "        failures.append({"}
{"line": 417, "text": "            \"severity\": \"HIGH\","}
{"line": 418, "text": "            \"contract\": \"model\","}
{"line": 419, "text": "            \"problem\": \"No model contract evidence was found in Python source.\","}
{"line": 420, "text": "            \"required_action\": \"Trace runtime imports and model initialization.\","}
{"line": 421, "text": "            \"fabrication_allowed\": False,"}
{"line": 422, "text": "        })"}
{"line": 423, "text": ""}
{"line": 424, "text": "    return failures"}
{"line": 425, "text": ""}
{"line": 426, "text": ""}
{"line": 427, "text": "def compile_check():"}
{"line": 428, "text": "    results = []"}
{"line": 429, "text": ""}
{"line": 430, "text": "    for path in python_files():"}
{"line": 431, "text": "        try:"}
{"line": 432, "text": "            source = path.read_text("}
{"line": 433, "text": "                encoding=\"utf-8\","}
{"line": 434, "text": "                errors=\"replace\","}
{"line": 435, "text": "            )"}
{"line": 436, "text": "            compile("}
{"line": 437, "text": "                source,"}
{"line": 438, "text": "                str(path),"}
{"line": 439, "text": "                \"exec\","}
{"line": 440, "text": "            )"}
{"line": 441, "text": ""}
{"line": 442, "text": "            results.append({"}
{"line": 443, "text": "                \"file\": str(path.relative_to(ROOT)),"}
{"line": 444, "text": "                \"status\": \"PASS\","}
{"line": 445, "text": "            })"}
{"line": 446, "text": ""}
{"line": 447, "text": "        except Exception as e:"}
{"line": 448, "text": "            results.append({"}
{"line": 449, "text": "                \"file\": str(path.relative_to(ROOT)),"}
{"line": 450, "text": "                \"status\": \"FAIL\","}
{"line": 451, "text": "                \"error\": repr(e),"}
{"line": 452, "text": "            })"}
{"line": 453, "text": ""}
{"line": 454, "text": "    return results"}
{"line": 455, "text": ""}
{"line": 456, "text": ""}
{"line": 457, "text": "def shell_inventory():"}
{"line": 458, "text": "    result = []"}
{"line": 459, "text": ""}
{"line": 460, "text": "    for pattern in ("}
{"line": 461, "text": "        \"*.sh\","}
{"line": 462, "text": "        \"*.json\","}
{"line": 463, "text": "        \"*.jsonl\","}
{"line": 464, "text": "        \"*.txt\","}
{"line": 465, "text": "        \"*.yaml\","}
{"line": 466, "text": "        \"*.yml\","}
{"line": 467, "text": "        \"*.toml\","}
{"line": 468, "text": "    ):"}
{"line": 469, "text": "        for p in ROOT.rglob(pattern):"}
{"line": 470, "text": "            if any(part in PYTHON_EXCLUDE for part in p.parts):"}
{"line": 471, "text": "                continue"}
{"line": 472, "text": ""}
{"line": 473, "text": "            try:"}
{"line": 474, "text": "                result.append({"}
{"line": 475, "text": "                    \"path\": str(p.relative_to(ROOT)),"}
{"line": 476, "text": "                    \"bytes\": p.stat().st_size,"}
{"line": 477, "text": "                    \"sha256\": sha256_file(p),"}
{"line": 478, "text": "                })"}
{"line": 479, "text": "            except Exception:"}
{"line": 480, "text": "                pass"}
{"line": 481, "text": ""}
{"line": 482, "text": "    return sorted(result, key=lambda x: x[\"path\"])"}
{"line": 483, "text": ""}
{"line": 484, "text": ""}
{"line": 485, "text": "def runtime_processes():"}
{"line": 486, "text": "    try:"}
{"line": 487, "text": "        proc = subprocess.run("}
{"line": 488, "text": "            [\"ps\", \"-A\"],"}
{"line": 489, "text": "            capture_output=True,"}
{"line": 490, "text": "            text=True,"}
{"line": 491, "text": "            timeout=5,"}
{"line": 492, "text": "        )"}
{"line": 493, "text": ""}
{"line": 494, "text": "        return proc.stdout[:20000]"}
{"line": 495, "text": ""}
{"line": 496, "text": "    except Exception as e:"}
{"line": 497, "text": "        return f\"PROCESS_QUERY_ERROR: {e!r}\""}
{"line": 498, "text": ""}
{"line": 499, "text": ""}
{"line": 500, "text": "def runtime_environment():"}
{"line": 501, "text": "    keys = ["}
{"line": 502, "text": "        \"PREFIX\","}
{"line": 503, "text": "        \"HOME\","}
{"line": 504, "text": "        \"PATH\","}
{"line": 505, "text": "        \"PYTHONPATH\","}
{"line": 506, "text": "        \"VIRTUAL_ENV\","}
{"line": 507, "text": "    ]"}
{"line": 508, "text": ""}
{"line": 509, "text": "    return {"}
{"line": 510, "text": "        key: os.environ.get(key)"}
{"line": 511, "text": "        for key in keys"}
{"line": 512, "text": "        if os.environ.get(key) is not None"}
{"line": 513, "text": "    }"}
{"line": 514, "text": ""}
{"line": 515, "text": ""}
{"line": 516, "text": "def state_integrity(state):"}
{"line": 517, "text": "    return {"}
{"line": 518, "text": "        \"state_exists\": STATE_FILE.exists(),"}
{"line": 519, "text": "        \"ledger_exists\": LEDGER_FILE.exists(),"}
{"line": 520, "text": "        \"backup_dir_exists\": BACKUP_DIR.exists(),"}
{"line": 521, "text": "        \"report_dir_exists\": REPORT_DIR.exists(),"}
{"line": 522, "text": "        \"state_runs\": state.get(\"runs\"),"}
{"line": 523, "text": "        \"repairs_attempted\": state.get(\"repairs_attempted\"),"}
{"line": 524, "text": "        \"repairs_successful\": state.get(\"repairs_successful\"),"}
{"line": 525, "text": "        \"repairs_failed\": state.get(\"repairs_failed\"),"}
{"line": 526, "text": "    }"}
{"line": 527, "text": ""}
{"line": 528, "text": ""}
{"line": 529, "text": "def build_source_bundle():"}
{"line": 530, "text": "    \"\"\""}
{"line": 531, "text": "    Create a complete evidence bundle without modifying source."}
{"line": 532, "text": "    \"\"\""}
{"line": 533, "text": ""}
{"line": 534, "text": "    bundle = REPORT_DIR / \"source_evidence.txt\""}
{"line": 535, "text": ""}
{"line": 536, "text": "    with bundle.open(\"w\", encoding=\"utf-8\") as out:"}
{"line": 537, "text": "        out.write(\"=\" * 80 + \"\\n\")"}
{"line": 538, "text": "        out.write(\"BLOOM SOURCE EVIDENCE BUNDLE\\n\")"}
{"line": 539, "text": "        out.write(\"=\" * 80 + \"\\n\")"}
{"line": 540, "text": "        out.write(f\"Generated: {now()}\\n\")"}
{"line": 541, "text": "        out.write(f\"Root: {ROOT}\\n\\n\")"}
{"line": 542, "text": ""}
{"line": 543, "text": "        for path in python_files():"}
{"line": 544, "text": "            rel = path.relative_to(ROOT)"}
{"line": 545, "text": ""}
{"line": 546, "text": "            out.write(\"\\n\" + \"=\" * 80 + \"\\n\")"}
{"line": 547, "text": "            out.write(f\"FILE: {rel}\\n\")"}
{"line": 548, "text": "            out.write(\"=\" * 80 + \"\\n\")"}
{"line": 549, "text": ""}
{"line": 550, "text": "            try:"}
{"line": 551, "text": "                text = path.read_text("}
{"line": 552, "text": "                    encoding=\"utf-8\","}
{"line": 553, "text": "                    errors=\"replace\","}
{"line": 554, "text": "                )"}
{"line": 555, "text": ""}
{"line": 556, "text": "                for i, line in enumerate(text.splitlines(), 1):"}
{"line": 557, "text": "                    out.write("}
{"line": 558, "text": "                        json.dumps("}
{"line": 559, "text": "                            {"}
{"line": 560, "text": "                                \"line\": i,"}
{"line": 561, "text": "                                \"text\": line,"}
{"line": 562, "text": "                            },"}
{"line": 563, "text": "                            ensure_ascii=False,"}
{"line": 564, "text": "                        )"}
{"line": 565, "text": "                        + \"\\n\""}
{"line": 566, "text": "                    )"}
{"line": 567, "text": ""}
{"line": 568, "text": "            except Exception as e:"}
{"line": 569, "text": "                out.write(f\"READ_ERROR: {e!r}\\n\")"}
{"line": 570, "text": ""}
{"line": 571, "text": "    return bundle"}
{"line": 572, "text": ""}
{"line": 573, "text": ""}
{"line": 574, "text": "def create_repair_plan(report):"}
{"line": 575, "text": "    failures = report[\"contract_failures\"]"}
{"line": 576, "text": ""}
{"line": 577, "text": "    plan = []"}
{"line": 578, "text": ""}
{"line": 579, "text": "    for failure in failures:"}
{"line": 580, "text": "        plan.append({"}
{"line": 581, "text": "            \"contract\": failure.get(\"contract\"),"}
{"line": 582, "text": "            \"severity\": failure.get(\"severity\"),"}
{"line": 583, "text": "            \"status\": \"BLOCKED_PENDING_EVIDENCE\","}
{"line": 584, "text": "            \"action\": failure.get(\"required_action\"),"}
{"line": 585, "text": "            \"fabrication_allowed\": False,"}
{"line": 586, "text": "        })"}
{"line": 587, "text": ""}
{"line": 588, "text": "    if not failures:"}
{"line": 589, "text": "        plan.append({"}
{"line": 590, "text": "            \"status\": \"NO_CONTRACT_FAILURES_DETECTED\","}
{"line": 591, "text": "            \"action\": \"Proceed to runtime integration tests.\","}
{"line": 592, "text": "        })"}
{"line": 593, "text": ""}
{"line": 594, "text": "    return plan"}
{"line": 595, "text": ""}
{"line": 596, "text": ""}
{"line": 597, "text": "def main():"}
{"line": 598, "text": "    state = load_state()"}
{"line": 599, "text": "    state[\"runs\"] = int(state.get(\"runs\", 0)) + 1"}
{"line": 600, "text": "    state[\"last_run\"] = now()"}
{"line": 601, "text": ""}
{"line": 602, "text": "    print(\"=\" * 80)"}
{"line": 603, "text": "    print(\"BLOOM AUTONOMOUS REPAIR ENGINE\")"}
{"line": 604, "text": "    print(\"=\" * 80)"}
{"line": 605, "text": "    print(f\"ROOT: {ROOT}\")"}
{"line": 606, "text": "    print(f\"RUN: {state['runs']}\")"}
{"line": 607, "text": "    print()"}
{"line": 608, "text": ""}
{"line": 609, "text": "    inventory = source_inventory()"}
{"line": 610, "text": "    findings = search_contracts()"}
{"line": 611, "text": "    contracts = producer_consumer_analysis(findings)"}
{"line": 612, "text": "    failures = detect_known_contract_failures(findings)"}
{"line": 613, "text": "    compile_results = compile_check()"}
{"line": 614, "text": "    auxiliary = shell_inventory()"}
{"line": 615, "text": "    bundle = build_source_bundle()"}
{"line": 616, "text": ""}
{"line": 617, "text": "    report = {"}
{"line": 618, "text": "        \"timestamp\": now(),"}
{"line": 619, "text": "        \"root\": str(ROOT),"}
{"line": 620, "text": "        \"source_inventory\": inventory,"}
{"line": 621, "text": "        \"auxiliary_inventory\": auxiliary,"}
{"line": 622, "text": "        \"contract_findings\": findings,"}
{"line": 623, "text": "        \"producer_consumer_analysis\": contracts,"}
{"line": 624, "text": "        \"contract_failures\": failures,"}
{"line": 625, "text": "        \"compile_check\": compile_results,"}
{"line": 626, "text": "        \"runtime_environment\": runtime_environment(),"}
{"line": 627, "text": "        \"runtime_processes\": runtime_processes(),"}
{"line": 628, "text": "        \"state_integrity\": state_integrity(state),"}
{"line": 629, "text": "        \"source_bundle\": str(bundle),"}
{"line": 630, "text": "    }"}
{"line": 631, "text": ""}
{"line": 632, "text": "    plan = create_repair_plan(report)"}
{"line": 633, "text": "    report[\"repair_plan\"] = plan"}
{"line": 634, "text": ""}
{"line": 635, "text": "    report_path = ("}
{"line": 636, "text": "        REPORT_DIR /"}
{"line": 637, "text": "        f\"repair_report_{int(time.time())}.json\""}
{"line": 638, "text": "    )"}
{"line": 639, "text": ""}
{"line": 640, "text": "    report_path.write_text("}
{"line": 641, "text": "        json.dumps(report, indent=2, ensure_ascii=False),"}
{"line": 642, "text": "        encoding=\"utf-8\","}
{"line": 643, "text": "    )"}
{"line": 644, "text": ""}
