ROOT = Path.home() / "BLOOM"
MODEL = ROOT / "bloom_real.py"

STATE_FILE = ROOT / "bloom_autonomous_state.json"
LEDGER_FILE = ROOT / "bloom_autonomous_ledger.jsonl"
BACKUP_DIR = ROOT / ".bloom_operator_backups"

