# SOURCE INTROSPECTION
# ============================================================

class SourceIntrospector:

    def __init__(self, model: Path = MODEL):
        self.model = Path(model)

        self.source = ""
        self.tree: ast.AST | None = None

        self.definitions = {}
        self.references = {}
        self.functions = {}
        self.classes = {}
        self.imports = set()

        self.assignments = {}
        self.calls = []
        self.top_level_order = []

    def load(self):
        if not self.model.exists():
            raise FileNotFoundError(
                f"Missing model: {self.model}"
            )

        self.source = self.model.read_text(
            encoding="utf-8",
            errors="replace",
        )

        self.tree = ast.parse(
            self.source
        )

        self.inspect()

        return self

    def _target_names(self, target):
        names = []

        if isinstance(target, ast.Name):
            names.append(target.id)

        elif isinstance(
            target,
            (ast.Tuple, ast.List),
        ):
            for item in target.elts:
                names.extend(
                    self._target_names(item)
                )

        elif isinstance(target, ast.Starred):
            names.extend(
                self._target_names(
                    target.value
                )
            )

        elif isinstance(target, ast.Attribute):
            pass

        elif isinstance(target, ast.Subscript):
            pass

        return names

    def _expr_names(self, node):
        result = []

        for child in ast.walk(node):

            if isinstance(child, ast.Name):
                result.append(child.id)

        return sorted(set(result))

    def _call_name(self, node):
        if not isinstance(node, ast.Call):
            return None

        func = node.func

        if isinstance(func, ast.Name):
            return func.id

        if isinstance(func, ast.Attribute):

            parts = []
            cur = func

            while isinstance(cur, ast.Attribute):
                parts.append(cur.attr)
                cur = cur.value

            if isinstance(cur, ast.Name):
                parts.append(cur.id)

            return ".".join(reversed(parts))

        return None

    def inspect(self):

        if self.tree is None:
            raise RuntimeError(
                "AST has not been loaded."
            )

        self.definitions.clear()
        self.references.clear()
        self.functions.clear()
        self.classes.clear()
        self.imports.clear()
        self.assignments.clear()
        self.calls.clear()
        self.top_level_order.clear()

        builtin_names = set(
            dir(__builtins__)
        )

        # ----------------------------------------------------
        # IMPORTS
        # ----------------------------------------------------

        for node in ast.walk(self.tree):

            if isinstance(node, ast.Import):

                for alias in node.names:
                    self.imports.add(
                        alias.asname
                        or alias.name.split(".")[0]
                    )

            elif isinstance(
                node,
                ast.ImportFrom,
            ):

                for alias in node.names:
                    self.imports.add(
                        alias.asname
                        or alias.name
                    )

        # ----------------------------------------------------
        # TOP LEVEL DEFINITIONS
        # ----------------------------------------------------

        for index, node in enumerate(
            self.tree.body,
            start=1,
        ):

            self.top_level_order.append({
                "index": index,
                "line": getattr(
                    node,
                    "lineno",
                    None,
                ),
                "type": type(node).__name__,
                "source": ast.get_source_segment(
                    self.source,
                    node,
                ),
            })

            if isinstance(
                node,
                ast.Assign,
            ):

                names = []

                for target in node.targets:
                    names.extend(
                        self._target_names(target)
                    )

                for name in names:

                    self.definitions[name] = {
                        "line": node.lineno,
                        "kind": "assignment",
                    }

                    self.assignments.setdefault(
                        name,
                        [],
                    ).append({
                        "line": node.lineno,
                        "end_line": getattr(
                            node,
                            "end_lineno",
                            node.lineno,
                        ),
                        "kind": "Assign",
                        "targets": names,
                        "reads": self._expr_names(
                            node.value
                        ),
                        "source": ast.get_source_segment(
                            self.source,
                            node,
                        ),
                    })

            elif isinstance(
                node,
                ast.AnnAssign,
            ):

                names = self._target_names(
                    node.target
                )

                for name in names:

                    self.definitions[name] = {
                        "line": node.lineno,
                        "kind": "annotated_assignment",
                    }

                    self.assignments.setdefault(
                        name,
                        [],
                    ).append({
                        "line": node.lineno,
                        "end_line": getattr(
                            node,
                            "end_lineno",
                            node.lineno,
                        ),
                        "kind": "AnnAssign",
                        "targets": names,
                        "reads": (
                            self._expr_names(
                                node.value
                            )
                            if node.value
                            else []
                        ),
                        "source": ast.get_source_segment(
                            self.source,
                            node,
                        ),
                    })

            elif isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                    ast.ClassDef,
                ),
            ):

                self.definitions[node.name] = {
                    "line": node.lineno,
                    "kind": type(node).__name__,
                }

        # ----------------------------------------------------
        # FUNCTIONS / CLASSES / CALLS / REFERENCES
        # ----------------------------------------------------

        for node in ast.walk(self.tree):

            if isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            ):

                self.functions[node.name] = {
                    "line": node.lineno,
                    "end_line": getattr(
                        node,
                        "end_lineno",
                        node.lineno,
                    ),
                }

            elif isinstance(
                node,
                ast.ClassDef,
            ):

                self.classes[node.name] = {
                    "line": node.lineno,
                    "end_line": getattr(
                        node,
                        "end_lineno",
                        node.lineno,
                    ),
                }

            elif isinstance(
                node,
                ast.Call,
            ):

                name = self._call_name(node)

                if name:

                    self.calls.append({
                        "name": name,
                        "line": node.lineno,
                        "args": [
                            ast.get_source_segment(
                                self.source,
                                arg,
                            )
                            for arg in node.args
                        ],
                    })

            elif isinstance(
                node,
                ast.Name,
            ):

                if not isinstance(
                    node.ctx,
                    ast.Load,
                ):
                    continue

                self.references.setdefault(
                    node.id,
                    [],
                ).append(
                    node.lineno
                )

    def source_segment(self, name: str):

        if self.tree is None:
            return None

        for node in ast.walk(self.tree):

            if isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                    ast.ClassDef,
                ),
            ):

                if node.name == name:
                    return ast.get_source_segment(
                        self.source,
                        node,
                    )

        return None

    def line_context(
        self,
        line: int,
        radius: int = 15,
    ):

        lines = self.source.splitlines()

        start = max(
            1,
            line - radius,
        )

        end = min(
            len(lines),
            line + radius,
        )

        return {
            "start_line": start,
            "end_line": end,
            "lines": [
                {
                    "line": i,
                    "text": lines[i - 1],
                }
                for i in range(
                    start,
                    end + 1,
                )
            ],
        }

    def symbol_forensics(
        self,
        name: str,
    ):

        return {
            "symbol": name,
            "definition": self.definitions.get(
                name
            ),
            "references": self.references.get(
                name,
                [],
            ),
            "assignments": self.assignments.get(
                name,
                [],
            ),
            "function": self.functions.get(
                name
            ),
            "class": self.classes.get(
                name
            ),
        }

    def unresolved_references(self):

        builtin_names = set(
            dir(__builtins__)
        )

        result = {}

        for name, lines in self.references.items():

            if name in self.definitions:
                continue

            if name in self.imports:
                continue

            if name in builtin_names:
                continue

            result[name] = sorted(
                set(lines)
            )

        return result

    def dependency_graph(self):

        graph = {}

        for name in self.functions:

            segment = self.source_segment(name)

            if not segment:
                continue

            try:
                tree = ast.parse(segment)
            except Exception:
                continue

            reads = sorted({
                node.id
                for node in ast.walk(tree)
                if (
                    isinstance(node, ast.Name)
                    and isinstance(
                        node.ctx,
                        ast.Load,
                    )
                )
            })

            graph[name] = {
                "reads": reads,
                "undefined_reads": [
                    x
                    for x in reads
                    if (
                        x not in self.definitions
                        and x not in self.imports
                        and x not in dir(__builtins__)
                    )
                ],
            }

        return graph

    def symbol_order(self):

        order = {}

        for name, info in self.definitions.items():
            order[name] = info.get("line")

        return order

    def summary(self):

        return {
            "model": str(self.model),
            "bytes": len(
                self.source.encode("utf-8")
            ),
            "sha256": sha256_file(
                self.model
            ),
            "definitions": self.definitions,
            "references": self.references,
            "functions": self.functions,
            "classes": self.classes,
            "imports": sorted(self.imports),
            "assignments": self.assignments,
            "unresolved_references":
                self.unresolved_references(),
            "dependency_graph":
                self.dependency_graph(),
            "symbol_order":
                self.symbol_order(),
        }


