class RuntimeProbe:

    def __init__(
        self,
        terminal: AutonomousTerminal,
    ):
        self.terminal = terminal

    def import_model(self):

        probe = r'''
import sys
import traceback

ROOT = %r

sys.path.insert(0, ROOT)

try:

    import bloom_real

    print("BLOOM_IMPORT_SUCCESS")

    names = [
        "VALIDATION_TEXT",
        "stoi",
        "itos",
        "vocab_size",
        "data",
        "validation_data",
        "get_batch",
        "GPT",
        "model",
        "params",
        "adam_m",
        "adam_v",
        "best_loss",
        "generate",
        "retrieve",
    ]

    for name in names:

        if hasattr(
            bloom_real,
            name,
        ):

            value = getattr(
                bloom_real,
                name,
            )

            try:
                length = len(value)
            except Exception:
                length = None

            shape = getattr(
                value,
                "shape",
                None,
            )

            print(
                "RUNTIME_SYMBOL",
                name,
                "type=",
                type(value).__name__,
                "len=",
                length,
                "shape=",
                shape,
            )

        else:

            print(
                "RUNTIME_MISSING",
                name,
            )

except Exception as exc:

    print(
        "BLOOM_IMPORT_FAILURE",
        type(exc).__name__,
        str(exc),
    )

    traceback.print_exc()
''' % str(ROOT)

        return self.terminal.run(
            f"{shlex.quote(sys.executable)} "
            f"-c {shlex.quote(probe)}",
            timeout=120,
        )

    def corpus_probe(self):

        probe = r'''
