                    ]

                return decision

            # ----------------------------------------------
            # GENERAL NAME ERROR
            # ----------------------------------------------

            decision["decision"] = (
                "TRACE_MISSING_SYMBOL"
            )

            decision["confidence"] = 0.90

            decision["next_actions"] = [
                "locate producer",
