class ValidationEngine:

    def __init__(
        self,
        terminal: AutonomousTerminal,
    ):
        self.terminal = terminal

    def compile(self):

        return self.terminal.run(
            "python3 -m py_compile bloom_real.py",
            timeout=120,
        )

    def import_probe(self):

        return RuntimeProbe(
            self.terminal
        ).import_model()

    def corpus_probe(self):

        return RuntimeProbe(
            self.terminal
        ).corpus_probe()


