# ============================================================

class BloomAutonomousOperator:

    def __init__(self):

        self.terminal = (
            AutonomousTerminal()
        )

        self.inspector = (
            SourceIntrospector()
        )

        self.tracer = None

        self.discerner = (
            ErrorDiscerner()
        )

        self.safety = (
            RepairSafety()
        )

        self.validation = (
            ValidationEngine(
                self.terminal
            )
        )

        self.state = {
            "system": "BLOOM",
            "operator":
                "evidence-first",
            "mode":
                "OBSERVE -> TRACE -> DISCERN -> VERIFY",
            "started": now(),
            "cycles": [],
        }

    # --------------------------------------------------------
    # INSPECTION
    # --------------------------------------------------------

    def inspect(self):

        self.inspector.load()

        self.tracer = ContractTracer(
            self.inspector
        )

        return self.inspector.summary()

    # --------------------------------------------------------
    # PROBE
    # --------------------------------------------------------

    def probe(self):

        result = self.validation.import_probe()

        error = self.discerner.classify(
            result.stdout,
            result.stderr,
            result.returncode,
        )

        return result, error

    # --------------------------------------------------------
    # PRINT SYMBOL
    # --------------------------------------------------------

    def print_symbol(
        self,
        name: str,
    ):

        evidence = (
            self.tracer.trace_symbol(name)
        )

        print()
        print(
            f"--- SYMBOL: {name} ---"
        )

        print(
            "DEFINITION:",
            evidence["definition"],
        )

        print(
            "REFERENCES:",
            evidence["references"],
        )

        print(
            "PRODUCER:",
            evidence["producer_exists"],
        )

        for assignment in (
            evidence["assignments"]
        ):

            print(
                "ASSIGNMENT:",
                assignment["line"],
                "reads=",
                assignment["reads"],
            )

            print(
                assignment["source"]
            )

    # --------------------------------------------------------
    # DEEP TRACE
    # --------------------------------------------------------

    def print_deep_trace(
        self,
        trace: dict[str, Any],
    ):

        print()
        print("=" * 80)
        print(
            "DEEP TOKENIZATION CONTRACT TRACE"
        )
        print("=" * 80)

        tokenization = trace[
            "tokenization"
        ]

        print()
        print("CORPUS EVIDENCE:")

        for corpus in (
            tokenization[
                "corpus_producers"
            ]
        ):

            print(
                " ",
                corpus["path"],
                "bytes=",
                corpus["bytes"],
                "sha256=",
                corpus["sha256"],
            )

        if not tokenization[
            "corpus_producers"
        ]:

            print(
                "  NO KNOWN CORPUS FILE FOUND"
            )

        print()
        print(
            "TOKENIZATION FUNCTIONS:"
        )

        for fn in (
            tokenization[
                "tokenization_functions"
            ]
        ):

            print(
                " ",
                fn,
            )

        if not tokenization[
            "tokenization_functions"
        ]:

            print(
                "  NONE DISCOVERED"
            )

        print()

        for symbol in [
            "VALIDATION_TEXT",
            "stoi",
            "itos",
            "vocab_size",
            "data",
            "validation_data",
        ]:

            self.print_symbol(symbol)

        print()
        print("=" * 80)
        print("MODEL CONTRACT")
        print("=" * 80)

        print(
            json.dumps(
                trace["model"],
                indent=2,
                default=str,
            )
        )

        print()
        print("=" * 80)
        print("BATCH CONTRACT")
        print("=" * 80)

        print(
            json.dumps(
                trace["batching"],
                indent=2,
                default=str,
            )
        )

        print()
        print("=" * 80)
        print("INFERENCE CONTRACT")
        print("=" * 80)

        print(
            json.dumps(
                trace["inference"],
                indent=2,
                default=str,
            )
        )

    # --------------------------------------------------------
    # RUN
    # --------------------------------------------------------

    def run(
        self,
        max_cycles: int = 5,
    ):

        print("=" * 80)
        print("BLOOM AUTONOMOUS OPERATOR")
        print("=" * 80)

        print(
            "MODE:",
            "OBSERVE -> TRACE -> DISCERN -> VERIFY",
        )

        print(
            "POLICY:",
            "EVIDENCE-FIRST / NO FABRICATION",
        )

        print(
            "MODEL:",
            MODEL,
        )

        print()

        for cycle_number in range(
            1,
            max_cycles + 1,
        ):

            cycle_started = now()

            print("=" * 80)
            print(
                f"CYCLE {cycle_number}"
            )
            print("=" * 80)

            try:

                source = self.inspect()

                print(
                    "AST: SUCCESS"
                )

                print(
                    "DEFINITIONS:",
                    len(
                        source[
                            "definitions"
                        ]
                    ),
                )

                print(
                    "FUNCTIONS:",
                    len(
                        source[
                            "functions"
                        ]
                    ),
                )

                print(
                    "CLASSES:",
                    len(
                        source[
                            "classes"
                        ]
                    ),
                )

            except Exception as exc:

                print(
                    "AST FAILURE:",
                    type(exc).__name__,
                    str(exc),
                )

                traceback.print_exc()

                self.state[
                    "fatal_error"
                ] = {
                    "type":
                        type(exc).__name__,
                    "detail":
                        str(exc),
                }

                break

            runtime, error = self.probe()

            print()
            print(
                "RUNTIME:",
                error["category"],
            )

            print(
                "DETAIL:",
                error["detail"],
            )

            trace = self.tracer.full_trace()

            decision = (
                self.discerner.analyze(
                    error,
                    trace,
                )
            )

            cycle = {
                "cycle":
                    cycle_number,
                "timestamp":
                    now(),
                "runtime":
                    runtime.as_dict(),
                "error":
                    error,
                "decision":
                    decision,
                "trace":
                    trace,
                "source": {
                    "sha256":
                        source["sha256"],
                    "definitions":
                        source["definitions"],
                    "functions":
                        source["functions"],
                    "classes":
                        source["classes"],
                    "unresolved":
                        source[
                            "unresolved_references"
                        ],
                },
                "duration":
                    now() - cycle_started,
            }

            self.state[
                "cycles"
            ].append(cycle)

            print()
            print("=" * 80)
            print("DISCERNMENT")
            print("=" * 80)

            print(
                "DECISION:",
                decision["decision"],
            )

            print(
                "CONFIDENCE:",
                decision["confidence"],
            )

            print()
            print("KNOWN:")

            for item in (
                decision[
                    "knowledge"
                ]["known"]
            ):

                print(
                    "  +",
                    item,
                )

            print()
            print("INFERRED:")

            for item in (
                decision[
                    "knowledge"
                ]["inferred"]
            ):

                print(
                    "  ~",
                    item,
                )

            print()
            print("UNKNOWN:")

            for item in (
                decision[
                    "knowledge"
                ]["unknown"]
            ):

                print(
                    "  ?",
                    item,
                )

            print()
            print("NEXT ACTIONS:")

            for index, action in enumerate(
                decision[
                    "next_actions"
                ],
                start=1,
            ):

                print(
                    f"  {index:02d}.",
                    action,
                )

            # ------------------------------------------------
            # DEEP TOKEN TRACE
            # ------------------------------------------------

            if (
                error["category"]
                == "NAME_ERROR"
                and error["detail"]
                in TOKEN_SYMBOLS
            ):

                self.print_deep_trace(
                    trace
                )

            # ------------------------------------------------
            # SUCCESS
            # ------------------------------------------------

            if (
                error["category"]
                == "NO_ERROR"
            ):

                print()
                print("=" * 80)
                print("IMPORT CONTRACT: PASS")
                print("=" * 80)

                print(
                    "BLOOM has passed module import."
                )

                print(
                    "TRAINING IS STILL LOCKED."
                )

                print(
                    "NEXT GATE:",
                    "vocabulary -> batch -> model -> "
                    "gradient -> checkpoint -> generation",
                )

                break

            # ------------------------------------------------
            # SAFETY GATE
            # ------------------------------------------------

            if (
                decision["confidence"]
                < 0.80
            ):

                print()
                print("=" * 80)
                print("AUTONOMY HALTED")
                print("=" * 80)

                print(
                    "Reason:",
                    "insufficient evidence for safe repair.",
                )

                break

            # ------------------------------------------------
            # MISSING TOKEN PRODUCER
            # ------------------------------------------------

            if (
                decision["decision"]
                == "TOKEN_PRODUCER_MISSING"
            ):

                print()
                print("=" * 80)
                print("REPAIR BOUNDARY REACHED")
                print("=" * 80)

                print(
                    "The operator has established that "
                    "the runtime vocabulary producer is absent."
                )

                print()
                print("CRITICAL:")

                print(
                    "No vocabulary, token IDs, validation IDs, "
                    "or model dimensions will be fabricated."
                )

                print()
                print(
                    "The next task is reconstruction of the "
                    "exact producer contract from real source evidence."
                )

                print()
                print(
                    "REPAIR STATUS:",
                    "NOT EXECUTED",
                )

                break

            # ------------------------------------------------
            # EXISTING PRODUCER
            # ------------------------------------------------

            if (
                decision["decision"]
                == "TRACE_EXISTING_TOKEN_PRODUCER"
            ):

                print()
                print("=" * 80)
                print("EXISTING PRODUCER FOUND")
                print("=" * 80)

                print(
                    "The producer exists in source."
                )

                print(
                    "Next operation:",
                    "producer ordering + dependency validation",
                )

                break

            print()
            print(
                "No safe autonomous modification boundary "
                "established in this cycle."
            )

            break

        # ----------------------------------------------------
        # SAVE STATE
        # ----------------------------------------------------

        self.state[
            "finished"
        ] = now()

        write_json(
            STATE_FILE,
            self.state,
        )

        print()
        print("=" * 80)
        print("AUTONOMOUS OPERATOR STATE")
        print("=" * 80)

        print(
            "STATE:",
            STATE_FILE,
        )

        print(
            "LEDGER:",
            LEDGER_FILE,
        )

        print(
            "BACKUPS:",
            BACKUP_DIR,
        )

        print("=" * 80)


