#!/usr/bin/env python3

from __future__ import annotations

import ast
import hashlib
import json
import os
import re
import shlex
import subprocess
import sys
import time
import traceback
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Any


ROOT = Path.home() / "BLOOM"
MODEL = ROOT / "bloom_real.py"

STATE_FILE = ROOT / "bloom_operator_state.json"
LEDGER_FILE = ROOT / "bloom_operator_ledger.jsonl"


# ============================================================
# CORE DATA TYPES
# ============================================================

@dataclass
class CommandResult:
    command: str
    cwd: str
    returncode: int
    stdout: str
    stderr: str
    duration: float
    timed_out: bool

    @property
    def success(self):
        return (
            self.returncode == 0
            and not self.timed_out
        )

    def as_dict(self):
        return asdict(self)


# ============================================================
# AUTONOMOUS TERMINAL
# ============================================================

class BloomTerminal:

    def __init__(self, root=ROOT):
        self.root = Path(root).resolve()
        self.root.mkdir(
            parents=True,
            exist_ok=True,
        )

    def snapshot(self):
        result = {}

        for path in self.root.rglob("*"):

            if not path.is_file():
                continue

            # Do not allow the terminal's own logs to become
            # an uncontrolled recursive observation surface.
            try:
                rel = path.relative_to(self.root)
            except Exception:
                continue

            try:
                raw = path.read_bytes()
            except Exception:
                continue

            result[str(rel)] = {
                "bytes": len(raw),
                "sha256": hashlib.sha256(raw).hexdigest(),
            }

        return result

    def run(
        self,
        command,
        timeout=120,
        cwd=None,
    ):

        cwd = (
            self.root
            if cwd is None
            else Path(cwd).resolve()
        )

        if self.root not in cwd.parents and cwd != self.root:
            raise ValueError(
                "Terminal cwd escaped BLOOM root."
            )

        before = self.snapshot()

        started = time.time()

        try:

            proc = subprocess.run(
                command,
                shell=True,
                cwd=str(cwd),
                text=True,
                capture_output=True,
                timeout=timeout,
            )

            result = CommandResult(
                command=command,
                cwd=str(cwd),
                returncode=proc.returncode,
                stdout=proc.stdout or "",
                stderr=proc.stderr or "",
                duration=time.time() - started,
                timed_out=False,
            )

        except subprocess.TimeoutExpired as e:

            stdout = e.stdout or ""
            stderr = e.stderr or ""

            if isinstance(stdout, bytes):
                stdout = stdout.decode(
                    "utf-8",
                    "replace",
                )

            if isinstance(stderr, bytes):
                stderr = stderr.decode(
                    "utf-8",
                    "replace",
                )

            result = CommandResult(
                command=command,
                cwd=str(cwd),
                returncode=-1,
                stdout=stdout,
                stderr=stderr,
                duration=time.time() - started,
                timed_out=True,
            )

        after = self.snapshot()

        changed = {}

        for path in sorted(
            set(before) | set(after)
        ):

            if before.get(path) != after.get(path):

                changed[path] = {
                    "before": before.get(path),
                    "after": after.get(path),
                }

        record = {
            "timestamp": time.time(),
            "type": "terminal_execution",
            "command": command,
            "cwd": str(cwd),
            "result": result.as_dict(),
            "changed_files": changed,
        }

        self.record(record)

        return result

    def record(self, record):

        with LEDGER_FILE.open(
            "a",
            encoding="utf-8",
        ) as f:

            f.write(
                json.dumps(
                    record,
                    ensure_ascii=False,
                )
                + "\n"
            )


# ============================================================
# SOURCE INTROSPECTION
# ============================================================

class SourceIntrospector:

    def __init__(self, model=MODEL):

        self.model = Path(model)

        self.source = ""
        self.tree = None

        self.definitions = {}
        self.references = {}
        self.functions = {}
        self.classes = {}
        self.imports = set()

    def load(self):

        if not self.model.exists():

            raise FileNotFoundError(
                f"Missing model: {self.model}"
            )

        self.source = self.model.read_text(
            encoding="utf-8",
            errors="replace",
        )

        self.tree = ast.parse(
            self.source
        )

        self._inspect()

        return self

    def _inspect(self):

        self.definitions.clear()
        self.references.clear()
        self.functions.clear()
        self.classes.clear()
        self.imports.clear()

        # Imports

        for node in ast.walk(self.tree):

            if isinstance(node, ast.Import):

                for alias in node.names:

                    self.imports.add(
                        alias.asname
                        or alias.name.split(".")[0]
                    )

            elif isinstance(
                node,
                ast.ImportFrom,
            ):

                for alias in node.names:

                    self.imports.add(
                        alias.asname
                        or alias.name
                    )

        # Top-level definitions

        for node in self.tree.body:

            if isinstance(node, ast.Assign):

                for target in node.targets:

                    if isinstance(
                        target,
                        ast.Name,
                    ):

                        self.definitions[
                            target.id
                        ] = {
                            "line": node.lineno,
                            "kind": "assignment",
                        }

            elif isinstance(
                node,
                ast.AnnAssign,
            ):

                if isinstance(
                    node.target,
                    ast.Name,
                ):

                    self.definitions[
                        node.target.id
                    ] = {
                        "line": node.lineno,
                        "kind": "assignment",
                    }

            elif isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                    ast.ClassDef,
                ),
            ):

                self.definitions[
                    node.name
                ] = {
                    "line": node.lineno,
                    "kind": type(node).__name__,
                }

        # Functions/classes anywhere

        for node in ast.walk(self.tree):

            if isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            ):

                self.functions[node.name] = {
                    "line": node.lineno,
                    "end_line": getattr(
                        node,
                        "end_lineno",
                        node.lineno,
                    ),
                }

            elif isinstance(
                node,
                ast.ClassDef,
            ):

                self.classes[node.name] = {
                    "line": node.lineno,
                    "end_line": getattr(
                        node,
                        "end_lineno",
                        node.lineno,
                    ),
                }

        # References

        for node in ast.walk(self.tree):

            if not isinstance(
                node,
                ast.Name,
            ):
                continue

            if not isinstance(
                node.ctx,
                ast.Load,
            ):
                continue

            self.references.setdefault(
                node.id,
                [],
            ).append(node.lineno)

    def source_segment(
        self,
        name,
    ):

        node = None

        if name in self.functions:

            target_line = self.functions[
                name
            ]["line"]

            for n in ast.walk(self.tree):

                if isinstance(
                    n,
                    (
                        ast.FunctionDef,
                        ast.AsyncFunctionDef,
                    ),
                ) and n.name == name:

                    if n.lineno == target_line:
                        node = n
                        break

        elif name in self.classes:

            target_line = self.classes[
                name
            ]["line"]

            for n in ast.walk(self.tree):

                if isinstance(
                    n,
                    ast.ClassDef,
                ) and n.name == name:

                    if n.lineno == target_line:
                        node = n
                        break

        if node is None:
            return None

        return ast.get_source_segment(
            self.source,
            node,
        )

    def top_level_source(self):

        return [
            {
                "line": node.lineno,
                "end_line": getattr(
                    node,
                    "end_lineno",
                    node.lineno,
                ),
                "type": type(node).__name__,
            }
            for node in self.tree.body
        ]

    def unresolved_references(
        self,
        names=None,
    ):

        if names is None:
            names = sorted(
                self.references
            )

        result = {}

        builtin_names = set(
            dir(__builtins__)
        )

        for name in names:

            if name in self.definitions:
                continue

            if name in self.imports:
                continue

            if name in builtin_names:
                continue

            result[name] = self.references.get(
                name,
                [],
            )

        return result


