def parse_python(
    path: Path,
) -> tuple[str, ast.AST | None, str | None]:

    try:
        text = path.read_text(
            encoding="utf-8",
            errors="replace",
        )

        tree = ast.parse(
            text,
            filename=str(path),
        )

        return text, tree, None

    except Exception as exc:
        return "", None, repr(exc)


def build_symbol_graph() -> dict[str, Any]:

    symbols: list[dict[str, Any]] = []
    references: list[dict[str, Any]] = []
    imports: list[dict[str, Any]] = []
    parse_errors: list[dict[str, Any]] = []

    for path in python_files():

        text, tree, error = parse_python(path)

        if tree is None:
            parse_errors.append(
                {
                    "file": rel(path),
                    "error": error,
                }
            )
            continue

        lines = text.splitlines()

        def context(line_no: int) -> str:
            if 1 <= line_no <= len(lines):
                return lines[line_no - 1][:500]
            return ""

        module = path.stem

        for node in ast.walk(tree):

            if isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            ):
                symbols.append(
                    asdict(
                        Symbol(
                            file=rel(path),
                            kind="function",
                            name=node.name,
                            line=node.lineno,
                            end_line=getattr(
                                node,
                                "end_lineno",
                                node.lineno,
                            ),
                            qualified=f"{module}.{node.name}",
                        )
                    )
                )

            elif isinstance(node, ast.ClassDef):
                symbols.append(
                    asdict(
                        Symbol(
                            file=rel(path),
                            kind="class",
                            name=node.name,
                            line=node.lineno,
                            end_line=getattr(
                                node,
                                "end_lineno",
                                node.lineno,
                            ),
                            qualified=f"{module}.{node.name}",
                        )
                    )
                )

            elif isinstance(node, ast.Import):
                for alias in node.names:
                    imports.append(
                        {
                            "file": rel(path),
                            "line": node.lineno,
                            "module": alias.name,
                            "alias": alias.asname,
                        }
                    )

            elif isinstance(node, ast.ImportFrom):
                for alias in node.names:
                    imports.append(
                        {
                            "file": rel(path),
                            "line": node.lineno,
                            "module": node.module or "",
                            "name": alias.name,
                            "alias": alias.asname,
                        }
                    )

            # IMPORTANT:
            # Only calls and attribute access are treated as meaningful
            # consumer evidence. Ordinary variable mentions are not.
            elif isinstance(node, ast.Call):

                if isinstance(node.func, ast.Name):
                    name = node.func.id

                elif isinstance(node.func, ast.Attribute):
                    name = node.func.attr

                else:
                    name = "<unknown>"

                references.append(
                    asdict(
                        Reference(
                            file=rel(path),
                            kind="call",
                            name=name,
                            line=node.lineno,
                            context=context(node.lineno),
                        )
                    )
                )

            elif isinstance(node, ast.Attribute):
                references.append(
                    asdict(
                        Reference(
                            file=rel(path),
                            kind="attribute",
                            name=node.attr,
                            line=node.lineno,
                            context=context(node.lineno),
                        )
                    )
                )

    return {
        "symbols": symbols,
        "references": references,
        "imports": imports,
        "parse_errors": parse_errors,
    }


def definitions_by_name(
    graph: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:

    result: dict[str, list[dict[str, Any]]] = {}

    for symbol in graph["symbols"]:
        result.setdefault(
            symbol["name"],
            [],
        ).append(symbol)

    return result


def contract_analysis(
    graph: dict[str, Any],
) -> dict[str, Any]:

    definitions = definitions_by_name(graph)

    output = {}

    for category, spec in CONTRACTS.items():

        evidence = {
            "producer_definitions": [],
            "consumer_references": [],
            "unresolved_names": [],
        }

        names = {
            x.lower()
            for x in spec["names"]
        }

        calls = {
            x.lower()
            for x in spec["consumer_calls"]
        }

        for symbol in graph["symbols"]:

            name = symbol["name"].lower()

            if name in names:
                evidence[
                    "producer_definitions"
                ].append(symbol)

        for ref in graph["references"]:

            name = ref["name"].lower()

            if (
                name in names
                or name in calls
            ):
                evidence[
                    "consumer_references"
                ].append(ref)

        for ref in evidence[
            "consumer_references"
        ]:

            name = ref["name"]

            if name not in definitions:

                evidence[
                    "unresolved_names"
                ].append(
                    {
                        "name": name,
                        "file": ref["file"],
                        "line": ref["line"],
                        "context": ref["context"],
                    }
                )

        producer_count = len(
            evidence[
                "producer_definitions"
            ]
        )

        consumer_count = len(
            evidence[
                "consumer_references"
            ]
        )

        unresolved_count = len(
            evidence[
                "unresolved_names"
            ]
        )

        if (
            consumer_count > 0
            and producer_count == 0
        ):
            status = "MISSING_PRODUCER_EVIDENCE"

        elif (
            unresolved_count > 0
        ):
            status = "UNRESOLVED_REFERENCE"

        elif (
            producer_count > 0
            and consumer_count > 0
        ):
            status = "EVIDENCE_PRESENT"

        else:
            status = "NO_STRONG_EVIDENCE"

        output[category] = {
            "status": status,
            "producer_count": producer_count,
            "consumer_count": consumer_count,
            "unresolved_count": unresolved_count,
            "evidence": evidence,
        }

    return output


def compile_all() -> dict[str, Any]:

    results = []

    for path in python_files():

        try:
            source = path.read_text(
                encoding="utf-8",
                errors="replace",
            )

            compile(
                source,
                str(path),
                "exec",
            )

            results.append(
                {
                    "file": rel(path),
                    "status": "PASS",
                }
            )

        except Exception as exc:

            results.append(
                {
                    "file": rel(path),
                    "status": "FAIL",
                    "error": repr(exc),
                }
            )

    failures = [
        x
        for x in results
        if x["status"] == "FAIL"
    ]

    return {
        "total": len(results),
        "passed": len(results) - len(failures),
        "failed": len(failures),
        "results": results,
    }


def find_entrypoints() -> list[dict[str, Any]]:

    candidates = []

    priority_names = {
        "main.py",
        "app.py",
        "run.py",
        "train.py",
        "serve.py",
        "runtime.py",
        "bloom.py",
        "model.py",
        "inference.py",
        "cli.py",
    }

    for path in python_files():

        # Never classify the repair controller as an application
        # entrypoint for its own smoke test.
        if path.resolve() == SELF_FILE:
            continue

        text = path.read_text(
            encoding="utf-8",
            errors="replace",
        )

        score = 0
        reasons = []

        if path.name in priority_names:
            score += 5
            reasons.append(
                "priority_filename"
            )

        if "__main__" in text:
            score += 5
            reasons.append(
                "main_guard"
            )

        if re.search(
            r"\bdef\s+main\s*\(",
            text,
        ):
            score += 3
            reasons.append(
                "main_function"
            )

        if re.search(
            r"argparse|sys\.argv",
            text,
        ):
            score += 2
            reasons.append(
                "cli"
            )

        if score:
            candidates.append(
                {
                    "file": rel(path),
                    "score": score,
                    "reasons": reasons,
                }
            )

    return sorted(
        candidates,
        key=lambda x: (
            -x["score"],
            x["file"],
        ),
    )


def runtime_smoke_test(
    entrypoints: list[dict[str, Any]],
    timeout: int = 8,
) -> list[dict[str, Any]]:

    results = []

    for item in entrypoints[:8]:

        path = ROOT / item["file"]

        command = [
            sys.executable,
            "-u",
            str(path),
        ]

        try:

            proc = subprocess.run(
                command,
                cwd=str(ROOT),
                capture_output=True,
                text=True,
                timeout=timeout,
                env=os.environ.copy(),
            )

            output = (
                proc.stdout
                + "\n"
                + proc.stderr
            )

            results.append(
                {
                    "file": item["file"],
                    "returncode": proc.returncode,
                    "status": (
                        "PASS"
                        if proc.returncode == 0
                        else "FAIL"
                    ),
                    "output": output[-12000:],
                }
            )

        except subprocess.TimeoutExpired as exc:

            results.append(
                {
                    "file": item["file"],
                    "returncode": None,
                    "status": "TIMEOUT",
                    "output": str(exc)[-12000:],
                }
            )

        except Exception as exc:

            results.append(
                {
                    "file": item["file"],
                    "returncode": None,
                    "status": "ERROR",
                    "output": repr(exc),
                }
            )

    return results


def extract_runtime_failures(
    smoke: list[dict[str, Any]],
) -> list[dict[str, Any]]:

    failures = []

    patterns = [
        (
            "missing_module",
            r"No module named ['\"]([^'\"]+)"
        ),
        (
            "missing_name",
            r"NameError: name ['\"]([^'\"]+)['\"]"
        ),
        (
            "missing_attribute",
            r"AttributeError: .*['\"]([^'\"]+)['\"]"
        ),
        (
            "missing_file",
            r"FileNotFoundError: .*['\"]([^'\"]+)['\"]"
        ),
        (
            "key_error",
            r"KeyError: ['\"]([^'\"]+)['\"]"
        ),
        (
            "value_error",
            r"ValueError: (.*)"
        ),
        (
            "runtime_error",
            r"RuntimeError: (.*)"
        ),
        (
            "type_error",
            r"TypeError: (.*)"
        ),
        (
            "assertion_error",
            r"AssertionError: (.*)"
        ),
    ]

    for result in smoke:

        if result["status"] == "PASS":
            continue

        output = result.get(
            "output",
            "",
        )

        detected = False

        for kind, pattern in patterns:

            match = re.search(
                pattern,
                output,
                re.IGNORECASE,
            )

            if match:

                failures.append(
                    {
                        "file": result["file"],
                        "kind": kind,
                        "detail": (
                            match.group(1)
                            if match.lastindex
                            else match.group(0)
                        ),
                        "output": output[-6000:],
                    }
                )

                detected = True
                break

        if not detected:

            failures.append(
                {
                    "file": result["file"],
                    "kind": (
                        "timeout"
                        if result["status"] == "TIMEOUT"
                        else "unclassified_runtime_failure"
                    ),
                    "detail": (
                        "Process timeout."
                        if result["status"] == "TIMEOUT"
                        else "No known exception signature matched."
                    ),
                    "output": output[-6000:],
                }
            )

    return failures


def detect_contract_failures(
    contracts: dict[str, Any],
) -> list[dict[str, Any]]:

    failures = []

    for category, data in contracts.items():

        if data["status"] == "MISSING_PRODUCER_EVIDENCE":

            failures.append(
                {
                    "severity": "HIGH",
                    "contract": category,
                    "problem": (
                        "Consumer evidence exists, "
                        "but this static pass found no "
                        "matching local producer definition."
                    ),
                    "producer_count": data[
                        "producer_count"
                    ],
                    "consumer_count": data[
                        "consumer_count"
                    ],
                    "unresolved_count": data[
                        "unresolved_count"
                    ],
                    "action": (
                        "Trace actual imports, external modules, "
                        "configuration, checkpoint metadata, "
                        "and runtime initialization before repair."
                    ),
                    "fabrication_allowed": False,
                }
            )

        elif data["status"] == "UNRESOLVED_REFERENCE":

            failures.append(
                {
                    "severity": "HIGH",
                    "contract": category,
                    "problem": (
                        "Contract-related calls or attributes "
                        "cannot be resolved to local definitions."
                    ),
                    "producer_count": data[
                        "producer_count"
                    ],
                    "consumer_count": data[
                        "consumer_count"
                    ],
                    "unresolved_count": data[
                        "unresolved_count"
                    ],
                    "action": (
                        "Trace actual imports and runtime "
                        "initialization before constructing a repair."
                    ),
                    "fabrication_allowed": False,
                }
            )

    return failures


def backup_file(
    path: Path,
    run_id: str,
) -> Path:

    destination = (
        BACKUP_DIR
        / str(run_id)
        / rel(path)
    )

    destination.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    shutil.copy2(
        path,
        destination,
    )

    return destination


def restore_backup(
    backup: Path,
    original: Path,
) -> None:

    original.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    shutil.copy2(
        backup,
        original,
    )


def fingerprint_failure(
    failure: dict[str, Any],
) -> str:

    raw = json.dumps(
        {
            "kind": failure.get("kind"),
            "detail": failure.get("detail"),
            "contract": failure.get("contract"),
        },
        sort_keys=True,
    )

    return hashlib.sha256(
        raw.encode("utf-8")
    ).hexdigest()[:24]


def learned_match(
    learned: dict[str, Any],
    failure: dict[str, Any],
) -> list[dict[str, Any]]:

    fingerprint = fingerprint_failure(
        failure
    )

    patterns = learned.get(
        "patterns",
        {},
    )

    matches = []

    for key, value in patterns.items():

        if (
            key == fingerprint
            or failure.get("kind")
            == value.get("failure_kind")
        ):
            matches.append(value)

    return matches


def record_learning(
    learned: dict[str, Any],
    failure: dict[str, Any],
    repair: dict[str, Any],
    validation: dict[str, Any],
) -> None:

    # Only validated repairs are eligible for positive learning.
    if not validation.get("passed"):
        return

    fingerprint = fingerprint_failure(
        failure
    )

    patterns = learned.setdefault(
        "patterns",
        {},
    )

    current = patterns.get(
        fingerprint,
        {
            "attempts": 0,
            "successes": 0,
            "failures": 0,
        },
    )

    current["attempts"] += 1
    current["successes"] += 1
    current["failure_kind"] = failure.get(
        "kind"
    )
    current["failure_detail"] = failure.get(
        "detail"
    )
    current["last_repair"] = repair
    current["last_validation"] = validation

    current["success_rate"] = (
        current["successes"]
        / current["attempts"]
    )

    patterns[fingerprint] = current


def safe_text_replace(
    path: Path,
    old: str,
    new: str,
) -> bool:

    source = path.read_text(
        encoding="utf-8",
        errors="replace",
    )

    if old not in source:
        return False

    if source.count(old) != 1:
        return False

    updated = source.replace(
        old,
        new,
        1,
    )

    path.write_text(
        updated,
        encoding="utf-8",
    )

    return True


def propose_runtime_repair(
    failure: dict[str, Any],
    graph: dict[str, Any],
) -> dict[str, Any] | None:

    kind = failure.get("kind")
    detail = failure.get("detail")

    if kind == "missing_name":

        name = str(detail)

        matches = [
            symbol
            for symbol in graph["symbols"]
            if symbol["name"] == name
        ]

        if len(matches) == 1:

            return {
                "type": "import_or_reference_repair",
                "reason": (
                    "Exactly one local definition exists "
                    "for the missing runtime name."
                ),
                "name": name,
                "definition": matches[0],
                "automatic": False,
                "requires_source_evidence": True,
            }

    return None


def validate_system(
    entrypoints: list[dict[str, Any]],
) -> dict[str, Any]:

    compile_result = compile_all()

    if compile_result["failed"]:

        return {
            "passed": False,
            "reason": "compile_failure",
            "compile": compile_result,
            "smoke": [],
            "runtime_failures": [],
        }

    smoke = runtime_smoke_test(
        entrypoints,
        timeout=8,
    )

    runtime_failures = extract_runtime_failures(
        smoke
    )

    passed = len(runtime_failures) == 0

    return {
        "passed": passed,
        "reason": (
            "runtime_smoke_passed"
            if passed
            else "runtime_failures"
        ),
        "compile": compile_result,
        "smoke": smoke,
        "runtime_failures": runtime_failures,
    }


def autonomous_repair_cycle(
    state: dict[str, Any],
    learned: dict[str, Any],
) -> dict[str, Any]:

    graph = build_symbol_graph()

    contracts = contract_analysis(
        graph
    )

    contract_failures = detect_contract_failures(
        contracts
    )

    entrypoints = find_entrypoints()

    before_validation = validate_system(
        entrypoints
    )

    runtime_failures = before_validation[
        "runtime_failures"
    ]

    all_failures = []

    for failure in contract_failures:
        all_failures.append(
            {
                "source": "static_contract",
                **failure,
            }
        )

    for failure in runtime_failures:
        all_failures.append(
            {
                "source": "runtime",
                **failure,
            }
        )

    repair_results = []

    for failure in all_failures:

        state["repairs_attempted"] += 1

        matches = learned_match(
            learned,
            failure,
        )

        candidate = None

        if failure.get("source") == "runtime":

            candidate = propose_runtime_repair(
                failure,
                graph,
            )

        if candidate is None:

            repair_results.append(
                {
                    "failure": failure,
                    "status": "BLOCKED",
                    "reason": (
                        "No evidence-backed automatic "
                        "repair is currently safe."
                    ),
                    "learned_matches": matches,
                }
            )

            state["repairs_failed"] += 1

            continue

        repair_results.append(
            {
                "failure": failure,
                "candidate": candidate,
                "status": "CANDIDATE_ONLY",
                "learned_matches": matches,
            }
        )

    save_learned(
        learned
    )

    return {
        "graph": graph,
        "contracts": contracts,
        "contract_failures": contract_failures,
        "entrypoints": entrypoints,
        "before_validation": before_validation,
        "runtime_failures": runtime_failures,
        "repair_results": repair_results,
    }


